import os, pathlib, shutil, subprocess, tempfile

TIDY = r'''#!/usr/bin/env bash
# tidy: sort the files at the top of a folder into subfolders by type. Safe to run again.
set -euo pipefail

usage() { echo "usage: tidy [-n] FOLDER    -n: only show what would move"; }

dry_run=false
while getopts "nh" opt; do
  case "$opt" in
    n) dry_run=true ;;
    h) usage; exit 0 ;;
    *) usage >&2; exit 2 ;;
  esac
done
shift $((OPTIND - 1))
[ "$#" -eq 1 ] || { usage >&2; exit 2; }
folder=${1%/}
[ -d "$folder" ] || { echo "tidy: no such folder: $folder" >&2; exit 1; }

# mkdir is atomic, so only one run can hold the lock; the trap removes it however the script ends
lock="$folder/.tidy.lock"
mkdir "$lock" 2> /dev/null || { echo "tidy: already running on $folder" >&2; exit 1; }
trap 'rmdir "$lock"' EXIT

category() {
  local ext
  ext=$(printf '%s' "${1##*.}" | tr '[:upper:]' '[:lower:]')
  case "$ext" in
    jpg|jpeg|png|gif|heic) echo images ;;
    pdf|doc|docx|txt|md|csv) echo documents ;;
    zip|tar|gz|dmg) echo archives ;;
    *) echo other ;;
  esac
}

free_name() {   # $2, or "$2 (1)", "$2 (2)"... whichever doesn't exist yet in folder $1
  local dir=$1 name=$2 base ext n=1 candidate=$2
  if [[ $name == ?*.* ]]; then base=${name%.*} ext=.${name##*.}; else base=$name ext=; fi
  while [ -e "$dir/$candidate" ]; do candidate="$base ($n)$ext"; n=$((n + 1)); done
  printf '%s\n' "$candidate"
}

count=0
for path in "$folder"/*; do
  [ -f "$path" ] || continue          # skip folders, and the unexpanded * of an empty folder
  name=${path##*/}
  dest=$(category "$name")
  target=$(free_name "$folder/$dest" "$name")
  if $dry_run; then
    echo "would move: $name -> $dest/$target"
  else
    mkdir -p "$folder/$dest"
    mv -n "$path" "$folder/$dest/$target"
    echo "moved: $name -> $dest/$target"
  fi
  count=$((count + 1))
done
[ "$count" -gt 0 ] || echo "nothing to tidy in $folder"
'''

def run(cmd, cwd, env):
    r = subprocess.run([shutil.which("bash"), "--norc", "--noprofile", "-c", cmd], cwd=cwd, env=env,
                       capture_output=True, text=True)
    print(f"$ {cmd}")
    for line in r.stdout.splitlines(): print(f"   {line}")
    for line in r.stderr.splitlines(): print(f"   (stderr) {line}")
    if r.returncode: print(f"   (exit status {r.returncode})")

def tree(folder):
    for p in sorted(folder.rglob("*")):
        if p.is_file(): print(f"   {p.relative_to(folder.parent)}")

with tempfile.TemporaryDirectory() as tmp:
    root = pathlib.Path(tmp); (root / "bin").mkdir()
    script = root / "bin" / "tidy"; script.write_text(TIDY); script.chmod(0o755)
    downloads = root / "Downloads"
    for name in ["Holiday 2025.JPG", "invoice-0423.pdf", "report.pdf", "notes.txt", "photo.png",
                 "backup.tar.gz", "Makefile", "documents/report.pdf", "projects/plan.md"]:
        p = downloads / name; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(name)
    env = {"PATH": f"{root / 'bin'}:{os.environ['PATH']}", "HOME": "/home/learner", "LC_ALL": "C"}

    run("tidy", root, env)
    run("tidy -n Downloads", root, env)
    run("tidy Downloads/", root, env)
    print("After one run:"); tree(downloads)
    run("tidy Downloads", root, env)
    run("tidy Nowhere", root, env)
    run('mkdir Downloads/.tidy.lock; tidy Downloads || echo "refused, status $?"; '
        'rmdir Downloads/.tidy.lock', root, env)
    kept = (downloads / "documents/report.pdf").read_text() == "documents/report.pdf"
    print(f"no lock left behind: {not (downloads / '.tidy.lock').exists()}; "
          f"the report already in documents/ is untouched: {kept}")

import ast, re

# 1. "Go to file": find the files whose paths contain the query's letters in order, best first.
FILES = ["README.md", "pyproject.toml", "src/shop/__init__.py", "src/shop/models/order.py",
         "src/shop/models/data_loader.py", "src/shop/views/menu.py", "src/shop/views/order_detail.py",
         "src/shop/utils/money.py", "tests/test_models.py", "tests/test_order_detail.py", "docs/deploy.md"]

def fuzzy(query, path):
    """The best score for finding the query's letters in order in the path, and where they are.
    A letter scores more at the start of a word, right after the previous match, or in the file name;
    letters skipped between matches cost a little."""
    q, p, n = query.lower(), path.lower(), len(path)
    name_start = path.rfind("/") + 1
    def value(j): return 1 + 8 * (j == 0 or p[j - 1] in "/_-.") + 2 * (j >= name_start)
    best = {}                                          # best[(i, j)]: score with q[i] matched at p[j]
    for i, ch in enumerate(q):
        for j in range(n):
            if p[j] != ch: continue
            if i == 0: best[(i, j)] = (value(j) - 0.1 * j, [j])
            else:
                options = [(s + value(j) + (8 if k == j - 1 else -0.2 * (j - k - 1)), at + [j])
                           for (pi, k), (s, at) in best.items() if pi == i - 1 and k < j]
                if options: best[(i, j)] = max(options)
    finals = [v for (i, _), v in best.items() if i == len(q) - 1]
    return max(finals) if finals else None

def marked(path, at): return "".join(f"[{c}]" if i in at else c for i, c in enumerate(path))

for query in ("mdl", "tmod", "odet", "ord"):
    ranked = sorted(((fuzzy(query, f), f) for f in FILES if fuzzy(query, f)), key=lambda t: -t[0][0])
    print(f"go to file '{query}':")
    for (score, at), f in ranked[:3]: print(f"   {score:5.1f}  {marked(f, at)}")

# 2. Search in files: every line that matches, with its file and line number, like rg or grep -rn
PROJECT = {"src/shop/models/order.py": "class Order:\n    total = 0\n",
           "src/shop/views/menu.py": "def show(menu):\n    # TODO: prices\n    return menu\n",
           "src/shop/utils/money.py": "def cents(x):\n    return round(x * 100)  # TODO: negative?\n"}
print("search for TODO in every file:")
for path, text in sorted(PROJECT.items()):
    for n, line in enumerate(text.splitlines(), 1):
        if re.search(r"TODO", line): print(f"   {path}:{n}: {line.strip()}")

# 3. Rename: text replacement versus a rename that knows what each name refers to
SOURCE = '''def total(items):
    return sum(items)

class Receipt:
    total = 0                              # a different thing with the same name

def report(carts):
    totals = [total(cart) for cart in carts]
    print("total:", total(totals))
'''

def rename_function(source, old, new):
    """Rename the module-level function `old`: its definition, and each use that refers to it."""
    tree = ast.parse(source); spots = []
    def visit(node, shadowed):
        if isinstance(node, ast.FunctionDef) and node.name == old and not shadowed:
            line = source.splitlines()[node.lineno - 1]
            spots.append((node.lineno, line.index(old, node.col_offset)))
        if isinstance(node, ast.Name) and node.id == old and not shadowed:
            spots.append((node.lineno, node.col_offset))
        if isinstance(node, (ast.ClassDef, ast.FunctionDef)):      # a name assigned inside is a new thing
            assigned = {t.id for n in ast.walk(node) for t in getattr(n, "targets", [])
                        if isinstance(t, ast.Name)}
            args = {a.arg for a in node.args.args} if isinstance(node, ast.FunctionDef) else set()
            shadowed = shadowed or old in assigned | args
            for child in node.body: visit(child, shadowed)
        else:
            for child in ast.iter_child_nodes(node): visit(child, shadowed)
    for child in tree.body: visit(child, False)
    lines = source.splitlines(keepends=True)
    for row, col in sorted(spots, reverse=True):
        lines[row - 1] = lines[row - 1][:col] + new + lines[row - 1][col + len(old):]
    return "".join(lines)

def changed(before, after):
    return [f"   line {n}: {b.strip()}  ->  {a.strip()}"
            for n, (b, a) in enumerate(zip(before.splitlines(), after.splitlines()), 1) if a != b]

for label, after in (("replace every 'total'", SOURCE.replace("total", "grand_total")),
                     ("replace whole words only, \\btotal\\b", re.sub(r"\btotal\b", "grand_total", SOURCE)),
                     ("rename the function, as an editor's Rename Symbol does",
                      rename_function(SOURCE, "total", "grand_total"))):
    print(f"{label}:"); print("\n".join(changed(SOURCE, after)))
    compile(after, "after.py", "exec")

import string

TEXT = """It was the best of times, it was the worst of times, it was the age of wisdom,
it was the age of foolishness, it was the epoch of belief, it was the epoch of incredulity."""

# 1. A problem broken into small functions, each with one job, input in and result out
def words(text):
    """Lower-case words, with punctuation stripped."""
    return [w.strip(string.punctuation) for w in text.lower().split()]
def count(items):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts
def top(counts, n, ignore=()):
    kept = [(word, c) for word, c in counts.items() if word not in ignore]
    return sorted(kept, key=lambda pair: (-pair[1], pair[0]))[:n]      # most common, then a-z
def report(pairs):
    return "\n".join(f"   {word:<8} {'#' * c} {c}" for word, c in pairs)
print(report(top(count(words(TEXT)), 5, ignore={"the", "of", "it", "was"})))

# 2. Pure functions return a result; impure ones change something. Know which you're calling.
nums = [3, 1, 2]
result = sorted(nums)                    # pure: returns a new list, leaves nums alone
print(f"\nsorted(nums) = {result}, nums still {nums}")
result = nums.sort()                     # impure: sorts nums in place, and returns None
print(f"nums.sort() returned {result}; nums is now {nums}")

# 3. A default value is evaluated once, when the def runs. A mutable default is shared.
def add_tag(tag, tags=[]):
    tags.append(tag)
    return tags
print(f"\nadd_tag('a') = {add_tag('a')}, then add_tag('b') = {add_tag('b')}  (the same list!)")
def add_tag_fixed(tag, tags=None):
    tags = [] if tags is None else tags
    tags.append(tag)
    return tags
print(f"fixed: {add_tag_fixed('a')}, then {add_tag_fixed('b')}")

# 4. The ways to pass arguments
def describe(name, /, age, *hobbies, city="nowhere", **extra):
    return f"{name}, {age}, hobbies {hobbies}, city {city}, extra {extra}"
print("\n" + describe("Ada", 36, "maths", "poetry", city="London", title="Countess"))
for bad in ("describe(name='Ada', age=36)", "describe('Ada')"):
    try: eval(bad)
    except TypeError as e: print(f"{bad} -> TypeError: {e}")

# 5. Functions are values: store them, pass them, return them
def make_scaler(factor):
    def scale(x): return x * factor
    return scale
double, triple = make_scaler(2), make_scaler(3)
ops = {"double": double, "triple": triple, "negate": lambda x: -x}
print(f"\n{[(name, op(7)) for name, op in ops.items()]}")
print(f"sorted by length, then a-z: {sorted(['pear', 'fig', 'banana', 'kiwi'], key=lambda w: (len(w), w))}")

import sys
from functools import cache

# 1. Each call gets its own frame on the call stack. Watch the stack grow, then unwind.
def factorial(n, depth=0):
    pad = "   " * depth
    print(f"{pad}factorial({n}) called")
    if n <= 1:                                    # the base case: no further call
        print(f"{pad}factorial({n}) returns 1")
        return 1
    result = n * factorial(n - 1, depth + 1)      # the recursive case: a smaller problem
    print(f"{pad}factorial({n}) returns {n} * {result // n} = {result}")
    return result
factorial(4)

# 2. Recursive data invites recursive code: a list can contain lists
def total(item):
    if isinstance(item, list):
        return sum(total(x) for x in item)
    return item
def depth(item):
    if not isinstance(item, list): return 0
    return 1 + max((depth(x) for x in item), default=0)
nested = [1, [2, [3, 4], []], [[[5]]], 6]
print(f"\nnested = {nested}: total {total(nested)}, nesting depth {depth(nested)}")

# 3. The same subproblem solved again and again, unless you remember the answers
calls = 0
def fib(n):
    global calls; calls += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)
@cache
def fib_memo(n):
    global calls; calls += 1
    return n if n < 2 else fib_memo(n - 1) + fib_memo(n - 2)
for f in (fib, fib_memo):
    calls = 0
    print(f"{f.__name__}(25) = {f(25):,} after {calls:,} calls")

# 4. Every frame costs stack space, so Python stops runaway recursion
def sum_to(n):
    return 0 if n == 0 else n + sum_to(n - 1)
print(f"\nPython's recursion limit is {sys.getrecursionlimit()} frames")
for n in (500, 5000):
    try: print(f"sum_to({n}) = {sum_to(n):,}")
    except RecursionError: print(f"sum_to({n}): RecursionError, the stack would be {n:,} frames deep")

# 5. Any recursion can be turned into a loop with a stack you manage yourself
def flatten_recursive(item):
    if not isinstance(item, list): return [item]
    return [x for sub in item for x in flatten_recursive(sub)]
def flatten_iterative(item):
    out, stack = [], [item]
    while stack:
        top = stack.pop()
        if isinstance(top, list): stack.extend(reversed(top))   # reversed keeps left-to-right order
        else: out.append(top)
    return out
deep = 0
for _ in range(10_000): deep = [deep]                         # 10,000 lists, one inside the next
print(f"flatten(nested): recursive {flatten_recursive(nested)}, iterative {flatten_iterative(nested)}")
try: flatten_recursive(deep)
except RecursionError: print("10,000 levels deep: the recursive version overflows; "
                             f"the iterative one returns {flatten_iterative(deep)}")

# 6. Some problems are naturally recursive: the towers of Hanoi
def hanoi(n, source="A", spare="B", target="C"):
    if n == 0: return []
    return hanoi(n - 1, source, target, spare) + [(source, target)] + hanoi(n - 1, spare, source, target)
moves = hanoi(3)
print(f"\nHanoi with 3 discs: {len(moves)} moves: {' '.join(a + '>' + b for a, b in moves)}")
print("moves for 1 to 10 discs:", [len(hanoi(n)) for n in range(1, 11)])

from collections import Counter, defaultdict

# 1. A dict maps keys to values; a set holds unique keys. Both remember insertion order (dicts).
stock = {"apples": 12, "pears": 0}
stock["figs"] = 7
print(f"stock = {stock}; stock.get('kiwis', 0) = {stock.get('kiwis', 0)}")
try: stock["kiwis"]
except KeyError as e: print(f"stock['kiwis'] -> KeyError: {e}")
in_stock = {name for name, n in stock.items() if n > 0}
print(f"in stock: {sorted(in_stock)}; 'pears' in stock: {'pears' in stock} (the key exists, with 0)")

words = "the cat and the hat and the bat".split()
print(f"\nCounter: {Counter(words).most_common(2)}")
by_letter = defaultdict(list)
for w in words: by_letter[w[0]].append(w)
print(f"grouped by first letter: {dict(by_letter)}")
print(f"unique, in first-seen order: {list(dict.fromkeys(words))}")
a, b = set("listen"), set("silent")
print(f"set('listen') == set('silent'): {a == b}; "
      f"{{1, 2, 3}} & {{2, 3, 4}} = {({1, 2, 3} & {2, 3, 4})}, | = {({1, 2, 3} | {2, 3, 4})}, "
      f"- = {({1, 2, 3} - {2, 3, 4})}")

# 2. How a dict finds a key without searching: hash it to a slot, then probe a few slots
def weak_hash(s):                            # Python randomises str hashes per run; these are fixed
    h = 0
    for ch in s: h = (h * 31 + ord(ch)) % 2**32
    return h
def fnv_hash(s):                             # FNV-1a: mixes every character into every bit
    h = 2166136261
    for ch in s: h = ((h ^ ord(ch)) * 16777619) % 2**32
    return h
class HashTable:
    def __init__(self, hash_fn, size=8):
        self.hash, self.slots, self.count, self.probes = hash_fn, [None] * size, 0, 0
    def _find(self, key):
        i = self.hash(key) % len(self.slots)
        while True:
            self.probes += 1
            if self.slots[i] is None or self.slots[i][0] == key: return i
            i = (i + 1) % len(self.slots)    # occupied by another key: try the next slot
    def put(self, key, value):
        if (self.count + 1) * 3 > len(self.slots) * 2:      # keep it under two-thirds full
            old = [s for s in self.slots if s]
            self.slots, self.count = [None] * (len(self.slots) * 4), 0
            for k, v in old: self.put(k, v)
        i = self._find(key)
        if self.slots[i] is None: self.count += 1
        self.slots[i] = (key, value)
    def get(self, key):
        slot = self.slots[self._find(key)]
        return slot[1] if slot else None
names = [f"user{i}" for i in range(10_000)]
print()
for hash_fn in (weak_hash, fnv_hash):
    table = HashTable(hash_fn)
    for i, name in enumerate(names): table.put(name, i)
    table.probes = 0
    assert all(table.get(name) == i for i, name in enumerate(names))
    print(f"10,000 keys in {len(table.slots):,} slots with {hash_fn.__name__}: "
          f"{table.probes / len(names):.2f} probes per lookup")
print(f"the same lookups in a list would average {sum(range(1, 10_001)) / 10_000:,.1f} comparisons")

# 3. Keys must be hashable, and equal keys must hash equally
class Point:
    def __init__(self, x, y): self.x, self.y = x, y
    def __eq__(self, other): return (self.x, self.y) == (other.x, other.y)
try: {Point(1, 2): "a"}
except TypeError as e: print(f"\nPoint with __eq__ but no __hash__ -> TypeError: {e}")
class BadPoint(Point):
    def __hash__(self): return id(self)      # breaks the rule: equal points, different hashes
places = {BadPoint(1, 2): "home"}
print(f"BadPoint(1, 2) in places: {BadPoint(1, 2) in places}  (it's equal, but hashed elsewhere)")
class GoodPoint(Point):
    def __hash__(self): return hash((self.x, self.y))
places = {GoodPoint(1, 2): "home"}
print(f"GoodPoint(1, 2) in places: {GoodPoint(1, 2) in places}")

import traceback

# 1. An exception unwinds the call stack until something catches it. The traceback is the path.
def load(settings): return parse_port(settings["port"])
def parse_port(text): return int(text)
try: load({"port": "80a"})
except ValueError as e:
    frames = traceback.extract_tb(e.__traceback__)
    print(f"{type(e).__name__}: {e}")
    print("   raised through: " + " -> ".join(f"{fr.name} (line {fr.lineno})" for fr in frames))

# 2. Catch narrowly. A bare except swallows the bug you didn't know you had.
def average_bad(xs):
    try: return sum(xs) / len(xss)                 # a typo: xss
    except: return 0                               # hides the NameError, and every other bug
def average(xs):
    try: return sum(xs) / len(xss)
    except ZeroDivisionError: return 0             # only the case we meant to handle
print(f"\naverage_bad([2, 4]) = {average_bad([2, 4])}  (wrong, and silent)")
try: average([2, 4])
except NameError as e: print(f"average([2, 4]) -> NameError: {e}  (loud, and fixable)")

# 3. The order: try, then except if it failed, else if it didn't, finally always
def attempt(x):
    steps = []
    try:
        steps.append("try"); 10 / x
    except ZeroDivisionError:
        steps.append("except")
    else:
        steps.append("else")
    finally:
        steps.append("finally")
    return steps
print(f"\nattempt(5): {attempt(5)}; attempt(0): {attempt(0)}")

# 4. Raise your own exceptions, with a message that says what and where, at the boundary
class ConfigError(Exception):
    """Something is wrong with the configuration a user gave us."""
def read_config(raw):
    port = raw.get("port")
    if port is None: raise ConfigError("missing 'port'")
    try: port = int(port)
    except ValueError as e: raise ConfigError(f"'port' must be a whole number, got {port!r}") from e
    if not 1 <= port <= 65535: raise ConfigError(f"'port' must be 1 to 65535, got {port}")
    return {"port": port, "host": raw.get("host", "localhost")}
for raw in ({"port": "8080"}, {}, {"port": "80a"}, {"port": 70000}):
    try: print(f"{raw} -> {read_config(raw)}")
    except ConfigError as e:
        cause = f"  (caused by {type(e.__cause__).__name__})" if e.__cause__ else ""
        print(f"{raw} -> ConfigError: {e}{cause}")

# 5. Returning None for failure moves the crash somewhere else
def find_price_quiet(prices, item): return prices.get(item)       # None if missing
prices = {"tea": 2.5, "cake": 3.0}
order = ["tea", "scone", "cake"]
try: total = sum(find_price_quiet(prices, item) for item in order)
except TypeError as e: print(f"\nquiet failure, found later: TypeError: {e}")
def find_price(prices, item):
    try: return prices[item]
    except KeyError: raise KeyError(f"no price for {item!r}") from None
try: total = sum(find_price(prices, item) for item in order)
except KeyError as e: print(f"loud failure, found at the cause: KeyError: {e.args[0]}")

import random, re, unittest

# The code under test: durations like "1h 30m 5s" to seconds and back. Version 1 has bugs.
def format_v1(seconds):
    h, rest = seconds // 3600 % 24, seconds % 3600      # a clock's hours, not a duration's
    m, s = divmod(rest, 60)
    return " ".join(f"{n}{unit}" for n, unit in ((h, "h"), (m, "m"), (s, "s")) if n)
def parse_v1(text):
    total = 0
    for number, unit in re.findall(r"(\d+)([hms])", text):
        total += int(number) * {"h": 3600, "m": 60, "s": 1}[unit]
    return total

def format_v2(seconds):
    if seconds < 0: raise ValueError("a duration can't be negative")
    h, rest = divmod(seconds, 3600)
    m, s = divmod(rest, 60)
    return " ".join(f"{n}{unit}" for n, unit in ((h, "h"), (m, "m"), (s, "s")) if n) or "0s"
def parse_v2(text):
    if not re.fullmatch(r"\s*(\d+[hms]\s*)+", text): raise ValueError(f"not a duration: {text!r}")
    return sum(int(n) * {"h": 3600, "m": 60, "s": 1}[u] for n, u in re.findall(r"(\d+)([hms])", text))

def make_tests(fmt, parse):
    class DurationTests(unittest.TestCase):
        def test_formats_hours_minutes_seconds(self): self.assertEqual(fmt(5405), "1h 30m 5s")
        def test_skips_zero_parts(self): self.assertEqual(fmt(3600), "1h")
        def test_zero_is_written_as_0s(self): self.assertEqual(fmt(0), "0s")
        def test_parses_what_it_formats(self): self.assertEqual(parse("1h 30m 5s"), 5405)
        def test_rejects_garbage(self):
            with self.assertRaises(ValueError): parse("ninety minutes")
        def test_rejects_negative(self):
            with self.assertRaises(ValueError): fmt(-5)
    return DurationTests

class Recorder(unittest.TestResult):              # collects results; no timings, so output is stable
    def __init__(self): super().__init__(); self.passed = []
    def addSuccess(self, test): self.passed.append(test)
def run(fmt, parse, label):
    result = Recorder()
    unittest.defaultTestLoader.loadTestsFromTestCase(make_tests(fmt, parse)).run(result)
    print(f"{label}: {len(result.passed)} passed, {len(result.failures)} failed")
    for test, tb in result.failures:
        why = next(line for line in tb.splitlines() if line.startswith("AssertionError"))
        print(f"   FAIL {test._testMethodName}: {why}")
