# A property check: for many random inputs, parsing what we formatted gives back the input
def round_trip_failures(fmt, parse, trials=2000):
    rng = random.Random(7)                        # seeded, so a failure can be reproduced
    bad = [s for s in (rng.randrange(0, 200_000) for _ in range(trials)) if parse(fmt(s)) != s]
    edges = (0, 59, 60, 3599, 3600, 86_399, 86_400)
    bad += [s for s in edges if parse(fmt(s)) != s]                     # and the edges, always
    return sorted(bad), trials + len(edges)
print()
for label, fmt, parse in (("version 1", format_v1, parse_v1), ("version 2", format_v2, parse_v2)):
    bad, tried = round_trip_failures(fmt, parse)
    if not bad: print(f"round trip, {label}: all {tried:,} inputs survive")
    else: print(f"round trip, {label}: {len(bad):,} of {tried:,} inputs fail; the smallest is "
                f"{bad[0]:,}, formatted as {fmt(bad[0])!r}, parsed back as {parse(fmt(bad[0])):,}")

from dataclasses import dataclass, FrozenInstanceError

# 1. A class bundles data with the operations that keep it valid
class Booking:
    """A room booked from start to end, in minutes since midnight."""
    def __init__(self, room, start, end):
        if not 0 <= start < end <= 24 * 60:                  # the invariant every Booking keeps
            raise ValueError(f"bad times {start}-{end}")
        self.room, self.start, self.end = room, start, end
    @property
    def minutes(self):                                       # computed, so it can't go stale
        return self.end - self.start
    def overlaps(self, other):
        return self.room == other.room and self.start < other.end and other.start < self.end
    def __repr__(self):
        fmt = lambda m: f"{m // 60:02d}:{m % 60:02d}"
        return f"Booking({self.room!r}, {fmt(self.start)}-{fmt(self.end)})"

class Calendar:
    def __init__(self): self._bookings = []                  # the underscore: "don't touch this"
    def book(self, room, start, end):
        new = Booking(room, start, end)
        clash = next((b for b in self._bookings if b.overlaps(new)), None)
        if clash: raise ValueError(f"{new} clashes with {clash}")
        self._bookings.append(new)
        return new
    def busiest(self):
        totals = {}
        for b in self._bookings: totals[b.room] = totals.get(b.room, 0) + b.minutes
        return max(totals.items(), key=lambda kv: kv[1])

cal = Calendar()
requests = [("Oak", 9 * 60, 10 * 60), ("Oak", 10 * 60, 11 * 60 + 30), ("Elm", 9 * 60 + 30, 11 * 60),
            ("Oak", 11 * 60, 12 * 60), ("Elm", 13 * 60, 12 * 60)]
for room, start, end in requests:
    try: print(f"booked {cal.book(room, start, end)}")
    except ValueError as e: print(f"refused: {e}")
print(f"busiest room: {cal.busiest()}")

# 2. A method call is a function call with the object passed as self
b = Booking("Ash", 600, 660)
print(f"\nb.minutes = {b.minutes}; b.overlaps(b) = {b.overlaps(b)}, "
      f"and Booking.overlaps(b, b) = {Booking.overlaps(b, b)}: the same call")

# 3. Attributes set on the class are shared by every instance
class Team:
    members = []                                             # one list, on the class
    def __init__(self, name): self.name = name
    def add(self, person): self.members.append(person)
red, blue = Team("red"), Team("blue")
red.add("Ana")
print(f"\nafter red.add('Ana'): blue.members = {blue.members}  (shared!)")
class FixedTeam:
    def __init__(self, name): self.name, self.members = name, []     # one list per instance
red, blue = FixedTeam("red"), FixedTeam("blue")
red.members.append("Ana")
print(f"with members set in __init__: blue.members = {blue.members}")

# 4. For classes that are mostly data, a dataclass writes __init__, __repr__ and __eq__ for you
@dataclass(frozen=True, order=True)
class Version:
    major: int
    minor: int = 0
    patch: int = 0
releases = [Version(1, 10), Version(1, 2, 3), Version(2), Version(1, 2)]
print(f"\n{sorted(releases)}")
