from abc import ABC, abstractmethod
from typing import Protocol, runtime_checkable

# 1. Inheritance ties a subclass to how its parent works inside, not just to what it does
class Bag:
    def __init__(self): self.items = []
    def add(self, x): self.items.append(x)
    def add_all(self, xs):
        for x in xs: self.add(x)                     # an implementation detail: it calls add
class CountingBag(Bag):
    """Counts how many items were ever added, by overriding both methods."""
    def __init__(self): super().__init__(); self.added = 0
    def add(self, x): self.added += 1; super().add(x)
    def add_all(self, xs): self.added += len(xs); super().add_all(xs)
bag = CountingBag()
bag.add_all(["a", "b", "c"])
print(f"inherited: added 3 items, counter says {bag.added}")   # add_all counted, then add counted again

class CountingBagComposed:
    """The same feature by holding a Bag instead of being one."""
    def __init__(self): self.bag, self.added = Bag(), 0
    def add(self, x): self.added += 1; self.bag.add(x)
    def add_all(self, xs): self.added += len(xs); self.bag.add_all(xs)
    @property
    def items(self): return self.bag.items
bag = CountingBagComposed()
bag.add_all(["a", "b", "c"])
print(f"composed:  added 3 items, counter says {bag.added}")

# 2. A subclass must work wherever its parent does. A Square is not a substitutable Rectangle.
class Rectangle:
    def __init__(self, w, h): self.w, self.h = w, h
    def set_width(self, w): self.w = w
    def area(self): return self.w * self.h
class Square(Rectangle):
    def __init__(self, side): super().__init__(side, side)
    def set_width(self, w): self.w = self.h = w      # keeps it square, breaks the parent's promise
def stretch(rect):
    rect.set_width(rect.w * 2)                       # code written for Rectangle expects this
    return rect.area()
print(f"\nstretch(Rectangle(2, 3)) = {stretch(Rectangle(2, 3))} (expected 12); "
      f"stretch(Square(3)) = {stretch(Square(3))} (expected 18)")

# 3. An interface is what callers rely on. In Python it can be just a shape, checked by a Protocol.
@runtime_checkable
class HasArea(Protocol):
    def area(self) -> float: ...
class Circle:                                        # not related to Rectangle at all
    def __init__(self, r): self.r = r
    def area(self): return round(3.14159 * self.r ** 2, 2)
shapes = [Rectangle(2, 3), Circle(1), Square(2)]
print(f"\ntotal area: {sum(s.area() for s in shapes)}; "
      f"all satisfy HasArea: {all(isinstance(s, HasArea) for s in shapes)}; "
      f"a str does: {isinstance('x', HasArea)}")

# 4. When you do inherit, an abstract base class makes the contract explicit
class Exporter(ABC):
    @abstractmethod
    def write(self, rows): ...
    def export(self, rows): return self.write(sorted(rows))       # shared logic, once
class CsvExporter(Exporter):
    def write(self, rows): return "\n".join(",".join(map(str, r)) for r in rows)
class BrokenExporter(Exporter): pass
print(f"\n{CsvExporter().export([(2, 'b'), (1, 'a')])!r}")
try: BrokenExporter()
except TypeError as e: print(f"BrokenExporter() -> TypeError: {e}")

# 5. Often the thing that varies is one behaviour: pass a function instead of making subclasses
def price(items, rule=lambda total: total):
    return rule(sum(items))
rules = {"none": lambda t: t, "10% off": lambda t: round(t * 0.9, 2),
         "5 off over 50": lambda t: t - 5 if t > 50 else t}
print(f"\n{[(name, price([20, 35], rule)) for name, rule in rules.items()]}")

