    calls = sorted({c.func.id for c in ast.walk(fn)
                    if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)})
    used = sorted({n.id for n in ast.walk(fn) if isinstance(n, ast.Name)} & top_names)
    mutated = sorted({c.func.value.id for c in ast.walk(fn) if isinstance(c, ast.Call)
                      and isinstance(c.func, ast.Attribute) and isinstance(c.func.value, ast.Name)
                      and c.func.value.id in top_names})
