import hashlib, json, pathlib, tempfile, threading, time, urllib.error, urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

# A small API running on this machine, so the example behaves the same everywhere
DATA = {"/cities/oslo": {"city": "Oslo", "temp_c": 4}, "/cities/lima": {"city": "Lima", "temp_c": 19},
        "/slow": {"slow": "but finished"}}
log, flaky = [], {"/cities/lima": 2}                   # lima fails twice with 503, then works
slow_done = threading.Event()
class API(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/slow": time.sleep(0.5)            # longer than the client will wait
        if self.path == "/busy" and sum(p == "/busy" for _, p, _ in log) == 0:
            return self.reply(429, {"error": "slow down"}, {"Retry-After": "2"})
        if flaky.get(self.path, 0) > 0:
            flaky[self.path] -= 1
            return self.reply(503, {"error": "try again"})
        body = DATA.get(self.path, {"busy": "ok"} if self.path == "/busy" else None)
        if body is None: return self.reply(404, {"error": f"no such city: {self.path}"})
        tag = '"' + hashlib.sha256(json.dumps(body).encode()).hexdigest()[:12] + '"'
        if self.headers.get("If-None-Match") == tag: return self.reply(304, None, {"ETag": tag})
        self.reply(200, body, {"ETag": tag})
    def reply(self, status, body, headers=None):
        log.append((self.command, self.path, status))
        data = json.dumps(body).encode() if body is not None else b""
        try:
            self.send_response(status)
            for k, v in (headers or {}).items(): self.send_header(k, v)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers(); self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError): pass     # the client gave up waiting
        if self.path == "/slow": slow_done.set()
    def log_message(self, *args): pass                  # keep the server quiet
server = ThreadingHTTPServer(("127.0.0.1", 0), API)     # port 0: let the system pick a free one
threading.Thread(target=server.serve_forever, daemon=True).start()
BASE = f"http://127.0.0.1:{server.server_address[1]}"

class Client:
    """Fetches JSON with a timeout, retries with backoff, honours Retry-After, and caches on disk."""
    def __init__(self, cache_file, clock, sleep, max_age=60):
        self.cache_file, self.clock, self.sleep, self.max_age = cache_file, clock, sleep, max_age
        self.cache = json.loads(cache_file.read_text()) if cache_file.exists() else {}
    def get(self, path, timeout=2.0):
        entry = self.cache.get(path)
        if entry and self.clock() - entry["at"] < self.max_age:
            return entry["body"], "cache, fresh"
        headers = {"If-None-Match": entry["etag"]} if entry else {}
        for attempt in range(4):
            try:
                req = urllib.request.Request(BASE + path, headers=headers)
                with urllib.request.urlopen(req, timeout=timeout) as r:
                    body, etag, how = json.load(r), r.headers["ETag"], "network"
                break
            except urllib.error.HTTPError as e:
                if e.code == 304:                                   # not modified: reuse ours
                    body, etag, how = entry["body"], entry["etag"], "cache, revalidated"; break
                if e.code == 429: self.sleep(float(e.headers["Retry-After"])); continue
                if e.code >= 500 and attempt < 3: self.sleep(0.5 * 2 ** attempt); continue
                raise RuntimeError(f"{path}: HTTP {e.code} {json.load(e).get('error')}") from e
        self.cache[path] = {"at": self.clock(), "etag": etag, "body": body}
        self.cache_file.write_text(json.dumps(self.cache))
        return body, how

