class DynamicArray:
    """A growable array on top of fixed-size storage: when it's full, allocate more and copy."""
    def __init__(self, grow=lambda cap: cap * 2, shrink_at=4):
        self.cap, self.n, self.slots = 1, 0, [None]
        self.grow, self.shrink_at, self.copies, self.resizes = grow, shrink_at, 0, 0
    def _resize(self, new_cap):
        slots = [None] * new_cap
        for i in range(self.n):                    # the expensive part: copy every element
            slots[i] = self.slots[i]
            self.copies += 1
        self.slots, self.cap, self.resizes = slots, new_cap, self.resizes + 1
    def append(self, x):
        if self.n == self.cap:
            self._resize(max(self.cap + 1, self.grow(self.cap)))
        self.slots[self.n] = x
        self.n += 1
    def pop(self):
        self.n -= 1
        x, self.slots[self.n] = self.slots[self.n], None
        if self.cap > 1 and self.n <= self.cap // self.shrink_at:
            self._resize(max(1, self.cap // 2))    # give memory back, but not too eagerly
        return x
    def __getitem__(self, i):
        if not 0 <= i < self.n:
            raise IndexError(i)
        return self.slots[i]

N = 50_000
print(f"appending {N:,} items:")
