class RingBuffer:
    """A fixed-capacity queue: head and tail indices chase each other around one array."""
    def __init__(self, capacity):
        self.slots, self.head, self.size = [None] * capacity, 0, 0
    def push(self, x):
        if self.size == len(self.slots):
            raise OverflowError("full")
        self.slots[(self.head + self.size) % len(self.slots)] = x
        self.size += 1
    def pop(self):
        x = self.slots[self.head]
        self.head, self.size = (self.head + 1) % len(self.slots), self.size - 1
        return x

q, moved, out_ring, out_list, lst = RingBuffer(1000), 0, [], [], []
for i in range(1000):
    q.push(i); lst.append(i)
for i in range(1000, 6000):                        # a queue under steady load: one in, one out
    out_ring.append(q.pop()); q.push(i)
    moved += len(lst) - 1                          # list.pop(0) shifts every remaining element left
    out_list.append(lst.pop(0)); lst.append(i)
print(f"queue of 1,000 under 5,000 push/pop pairs: ring buffer moved 0 elements, "
      f"list.pop(0) moved {moved:,}; same order out: {out_ring == out_list}")

import random

MASK64 = (1 << 64) - 1
def mix(k):
    """A deterministic integer hash (splitmix64's finaliser): nearby keys land far apart."""
    k = (k + 0x9E3779B97F4A7C15) & MASK64
    k = ((k ^ (k >> 30)) * 0xBF58476D1CE4E5B9) & MASK64
    k = ((k ^ (k >> 27)) * 0x94D049BB133111EB) & MASK64
    return k ^ (k >> 31)

class ChainedMap:
    def __init__(self, hash_fn=mix, buckets=8):
        self.h, self.buckets, self.n, self.compares = hash_fn, [[] for _ in range(buckets)], 0, 0
    def _bucket(self, key):
        return self.buckets[self.h(key) % len(self.buckets)]
    def put(self, key, value):
        b = self._bucket(key)
        for pair in b:
            if pair[0] == key:
                pair[1] = value; return
        b.append([key, value]); self.n += 1
        if self.n > 0.75 * len(self.buckets):                  # keep chains short: double and rehash
            old, self.buckets = self.buckets, [[] for _ in range(2 * len(self.buckets))]
            for chain in old:
                for k, v in chain:
                    self._bucket(k).append([k, v])
    def get(self, key):
        for k, v in self._bucket(key):
            self.compares += 1
            if k == key: return v
        return None

class ProbingMap:
    """Open addressing with linear probing: on a collision, try the next slot."""
    EMPTY, GONE = object(), object()
    def __init__(self, capacity):
        self.slots, self.probes = [self.EMPTY] * capacity, 0
    def put(self, key, value):
        i = mix(key) % len(self.slots)
        while self.slots[i] is not self.EMPTY and self.slots[i] is not self.GONE and self.slots[i][0] != key:
            i = (i + 1) % len(self.slots)
        self.slots[i] = (key, value)
    def get(self, key):
        i = mix(key) % len(self.slots)
        while True:
            self.probes += 1
            s = self.slots[i]
            if s is self.EMPTY: return None
            if s is not self.GONE and s[0] == key: return s[1]
            i = (i + 1) % len(self.slots)
    def delete(self, key):
        i = mix(key) % len(self.slots)
        while self.slots[i] is not self.EMPTY:
            if self.slots[i] is not self.GONE and self.slots[i][0] == key:
                self.slots[i] = self.GONE; return            # a tombstone keeps later probe chains intact
            i = (i + 1) % len(self.slots)

random.seed(2)
CAP = 20_000
print("linear probing: average probes per lookup (Knuth's formulas in brackets)")
for alpha in (0.25, 0.5, 0.75, 0.9):
    m, keys = ProbingMap(CAP), random.sample(range(10**9), int(CAP * alpha))
    for k in keys: m.put(k, k)
    m.probes = 0
    for k in keys: m.get(k)
    hit = m.probes / len(keys)
    m.probes = 0
    for k in random.sample(range(10**9, 2 * 10**9), 5000): m.get(k)
    miss = m.probes / 5000
    print(f"   load {alpha:4}: hit {hit:5.2f} [{(1 + 1 / (1 - alpha)) / 2:5.2f}]   "
          f"miss {miss:6.2f} [{(1 + 1 / (1 - alpha) ** 2) / 2:6.2f}]")

m, keys = ProbingMap(CAP), random.sample(range(10**9), CAP // 2)
for k in keys: m.put(k, k)
for k in keys[: CAP // 4]: m.delete(k)                        # delete half; the slots become tombstones
m.probes = 0
for k in random.sample(range(10**9, 2 * 10**9), 5000): m.get(k)
print(f"after deleting half the keys, a miss still costs {m.probes / 5000:.2f} probes: "
      "tombstones count as occupied until a rebuild")

chains = {}
for name, fn in (("good hash (mix)", mix), ("weak hash (k mod 1024)", lambda k: k % 1024)):
    hm = ChainedMap(fn, buckets=1024)
    hm.buckets = [[] for _ in range(1024)]
    attack = [i * 1024 for i in range(2000)]                   # keys chosen so k mod 1024 == 0
    for k in attack:
        b = hm.buckets[fn(k) % 1024]; b.append([k, k])         # insert without resizing, to show the shape
    for k in attack: hm.get(k)
    chains[name] = max(len(b) for b in hm.buckets)
    print(f"{name:24} 2,000 crafted keys: longest chain {chains[name]:5,}, "
          f"{hm.compares / len(attack):7.1f} comparisons per lookup")

import random

class MinHeap:
    """A binary heap stored in a list: the children of index i live at 2i+1 and 2i+2."""
    def __init__(self, items=()):
        self.a, self.compares = list(items), 0
        for i in range(len(self.a) // 2 - 1, -1, -1):      # bottom-up heapify: O(n), not O(n log n)
            self._down(i)
    def _less(self, i, j):
        self.compares += 1
        return self.a[i] < self.a[j]
    def _up(self, i):
        while i > 0 and self._less(i, (i - 1) // 2):
            p = (i - 1) // 2
            self.a[i], self.a[p] = self.a[p], self.a[i]
            i = p
    def _down(self, i):
        n = len(self.a)
        while True:
            l, r, small = 2 * i + 1, 2 * i + 2, i
            if l < n and self._less(l, small): small = l
            if r < n and self._less(r, small): small = r
            if small == i: return
            self.a[i], self.a[small] = self.a[small], self.a[i]
            i = small
    def push(self, x):
        self.a.append(x); self._up(len(self.a) - 1)
    def pop(self):
        last = self.a.pop()
        if not self.a: return last
        top, self.a[0] = self.a[0], last
        self._down(0)
        return top
    def __len__(self):
        return len(self.a)

random.seed(3)
N = 100_000
print(f"building a heap of {N:,} items, counting comparisons:")
for label, data in (("random order", [random.random() for _ in range(N)]),
                    ("descending order", list(range(N, 0, -1)))):       # every push climbs to the root
    one_by_one = MinHeap()
    for x in data: one_by_one.push(x)
    bottom_up = MinHeap(data)
    print(f"   {label:17} one push at a time {one_by_one.compares:>9,}   bottom-up heapify {bottom_up.compares:>9,}")
print("heapsort matches sorted():", [bottom_up.pop() for _ in range(len(bottom_up))] == sorted(data))

# The same heap drives shortest-path search. A* adds a guess of the remaining distance.
W = H = 60
def search(heuristic, walls):
    start, goal = (0, 0), (W - 1, H - 1)
    best, frontier, expanded = {start: 0}, MinHeap([(heuristic(start), 0, start)]), 0
    while frontier:
        _, neg_g, (x, y) = frontier.pop()
        g = -neg_g
        if g > best.get((x, y), float("inf")): continue     # a stale entry: a shorter way was found
        expanded += 1
        if (x, y) == goal: return g, expanded
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 0 <= nx < W and 0 <= ny < H and (nx, ny) not in walls and g + 1 < best.get((nx, ny), float("inf")):
                best[(nx, ny)] = g + 1
                frontier.push((g + 1 + heuristic((nx, ny)), -(g + 1), (nx, ny)))   # ties go to the deeper cell
    return None, expanded

def manhattan(p): return (W - 1 - p[0]) + (H - 1 - p[1])  # never overestimates on a 4-connected grid
for seed in range(100):                                    # the first maze, in a fixed order, with a way through
    random.seed(seed)
    maze = {(x, y) for x in range(W) for y in range(H) if random.random() < 0.3} - {(0, 0), (W - 1, H - 1)}
    if search(lambda p: 0, maze)[0] is not None:
        break
print(f"shortest path across a {W}x{H} grid, cells expanded:")
for label, walls in (("open ground", set()), ("maze, 30% walls", maze)):
    (d_len, d_exp), (a_len, a_exp) = search(lambda p: 0, walls), search(manhattan, walls)
    print(f"   {label:16} Dijkstra {d_exp:5,} cells, A* {a_exp:5,} cells, same length: {d_len == a_len} ({a_len} steps)")

import random

class BST:
    """A plain binary search tree: fine on random input, a linked list on sorted input."""
    def __init__(self):
        self.root = None                                   # nodes are [key, left, right]
    def insert(self, key):
        if self.root is None:
            self.root = [key, None, None]; return
        node = self.root
        while True:                                        # iterative: a degenerate tree is very deep
            side = 1 if key < node[0] else 2
            if node[side] is None:
                node[side] = [key, None, None]; return
            node = node[side]
    def height(self):
        h, level = 0, [self.root] if self.root else []
        while level:
            h, level = h + 1, [c for n in level for c in (n[1], n[2]) if c]
        return h

class AVL:
    """Keeps every node's two subtree heights within one of each other, by rotating."""
    class Node:
        __slots__ = ("key", "left", "right", "h")
        def __init__(self, key): self.key, self.left, self.right, self.h = key, None, None, 1
    def __init__(self):
        self.root, self.rotations = None, 0
    @staticmethod
    def _h(n): return n.h if n else 0
    def _fix(self, n): n.h = 1 + max(self._h(n.left), self._h(n.right))
    def _rotate_right(self, y):
        x = y.left
        y.left, x.right = x.right, y
        self._fix(y); self._fix(x); self.rotations += 1
        return x
    def _rotate_left(self, x):
        y = x.right
        x.right, y.left = y.left, x
        self._fix(x); self._fix(y); self.rotations += 1
        return y
    def _insert(self, n, key):
        if n is None: return self.Node(key)
        if key < n.key: n.left = self._insert(n.left, key)
        else: n.right = self._insert(n.right, key)
        self._fix(n)
        balance = self._h(n.left) - self._h(n.right)
        if balance > 1:                                    # left-heavy
            if key >= n.left.key: n.left = self._rotate_left(n.left)    # left-right case
            return self._rotate_right(n)
        if balance < -1:                                   # right-heavy
            if key < n.right.key: n.right = self._rotate_right(n.right) # right-left case
            return self._rotate_left(n)
        return n
    def insert(self, key):
        self.root = self._insert(self.root, key)
    def inorder(self):
        out, stack, n = [], [], self.root
        while stack or n:
            while n: stack.append(n); n = n.left
            n = stack.pop(); out.append(n.key); n = n.right
        return out

N = 4095                                                   # 2^12 - 1: a perfect tree would have height 12
random.seed(4)
heights = {}
for label, keys in (("sorted keys", list(range(N))), ("random keys", random.sample(range(10**6), N))):
    plain, avl = BST(), AVL()
    for k in keys:
        plain.insert(k); avl.insert(k)
    heights[label] = (plain.height(), avl.root.h)
    print(f"{label:12} {N:,} inserts: plain BST height {plain.height():5}   "
          f"AVL height {avl.root.h:3} ({avl.rotations:,} rotations)   AVL in order: {avl.inorder() == sorted(keys)}")
worst_plain, worst_avl = heights["sorted keys"]
print(f"a search walks one root-to-leaf path, so on sorted input it costs up to {worst_plain:,} steps "
      f"in the plain tree and {worst_avl} in the AVL tree")

import hashlib, math, random

def h128(item):
    d = hashlib.blake2b(str(item).encode(), digest_size=16).digest()
    return int.from_bytes(d[:8], "little"), int.from_bytes(d[8:], "little") | 1

class BloomFilter:
    """m bits and k hash functions: 'definitely not present' or 'probably present'."""
    def __init__(self, m, k):
        self.m, self.k, self.bits = m, k, bytearray((m + 7) // 8)
    def _positions(self, item):
        a, b = h128(item)
        return [(a + i * b) % self.m for i in range(self.k)]   # k hashes from two (Kirsch-Mitzenmacher)
    def add(self, item):
        for p in self._positions(item): self.bits[p // 8] |= 1 << (p % 8)
    def __contains__(self, item):
        return all(self.bits[p // 8] >> (p % 8) & 1 for p in self._positions(item))

class CountMin:
    """d rows of w counters; an item's estimate is its smallest counter, never an undercount."""
    def __init__(self, eps, delta):
        self.w, self.d = math.ceil(math.e / eps), math.ceil(math.log(1 / delta))
        self.rows = [[0] * self.w for _ in range(self.d)]
    def _cols(self, item):
        a, b = h128(item)
        return [(a + r * b) % self.w for r in range(self.d)]
    def add(self, item):
        for r, c in enumerate(self._cols(item)): self.rows[r][c] += 1
    def estimate(self, item):
        return min(self.rows[r][c] for r, c in enumerate(self._cols(item)))

class HyperLogLog:
    """Estimates how many distinct items it has seen from the longest runs of zero bits in their hashes."""
    def __init__(self, p):
        self.p, self.m, self.reg = p, 1 << p, bytearray(1 << p)
    def add_hash(self, x):
        j = x >> (64 - self.p)                                  # the first p bits pick a register
        rest = (x << self.p) & ((1 << 64) - 1)
        rank = 64 - self.p + 1 if rest == 0 else (64 - rest.bit_length()) + 1   # leading zeros + 1
        self.reg[j] = max(self.reg[j], rank)
    def count(self):
        alpha = 0.7213 / (1 + 1.079 / self.m)
        raw = alpha * self.m * self.m / sum(2.0 ** -r for r in self.reg)
        zeros = self.reg.count(0)
        if raw <= 2.5 * self.m and zeros:                      # small-range correction: linear counting
            return self.m * math.log(self.m / zeros)
        return raw

random.seed(7)
members = [f"user-{i}" for i in range(10_000)]
others = [f"visitor-{i}" for i in range(100_000)]
print("Bloom filter, 10,000 members, 100,000 non-members tested:")
for bits_per_key in (8, 12):
    m = bits_per_key * len(members)
    k = round(bits_per_key * math.log(2))                       # the k that minimises false positives
    bf = BloomFilter(m, k)
    for x in members: bf.add(x)
    assert all(x in bf for x in members)                        # no false negatives, ever
    fp = sum(x in bf for x in others) / len(others)
    theory = (1 - math.exp(-k * len(members) / m)) ** k
    print(f"   {bits_per_key:2} bits per key, k={k}: false positives {fp:.2%} (formula {theory:.2%}), "
          f"{m // 8:,} bytes")

