def euler_circuit(edge_list, start):
    adj = {}
    for i, (a, b) in enumerate(edge_list):
        adj.setdefault(a, []).append((b, i)); adj.setdefault(b, []).append((a, i))
    used, stack, circuit = set(), [start], []
    while stack:                                # Hierholzer: walk until stuck, then splice in detours
        v = stack[-1]
        while adj[v] and adj[v][-1][1] in used: adj[v].pop()
        if adj[v]:
            w, i = adj[v].pop(); used.add(i); stack.append(w)
        else:
            circuit.append(stack.pop())
    return circuit[::-1]
