# 3. Trees: count the spanning trees of K_n by brute force, against Cayley's formula n^(n-2)
def is_tree(n, es):
    parent = list(range(n))
    def find(x):
        while parent[x] != x: parent[x] = parent[parent[x]]; x = parent[x]
        return x
    for a, b in es:
        ra, rb = find(a), find(b)
        if ra == rb: return False               # this edge would close a cycle
        parent[ra] = rb
    return True                                 # n - 1 edges and no cycle: connected, a tree
