def two_colour(adj):
    colour = {}
    for s in adj:
        if s in colour: continue
        colour[s] = 0; q = deque([s])
        while q:
            v = q.popleft()
            for w in adj[v]:
                if w not in colour: colour[w] = 1 - colour[v]; q.append(w)
                elif colour[w] == colour[v]: return False
    return True
