# A slice of RISC-V (RV32I): every instruction is 32 bits, in one of six formats
REG = {f"x{i}": i for i in range(32)}
def bits(v, hi, lo): return (v >> lo) & ((1 << (hi - lo + 1)) - 1)
def R(f7, rs2, rs1, f3, rd, op): return f7 << 25 | rs2 << 20 | rs1 << 15 | f3 << 12 | rd << 7 | op
def I(imm, rs1, f3, rd, op): return (imm & 0xFFF) << 20 | rs1 << 15 | f3 << 12 | rd << 7 | op
def S(imm, rs2, rs1, f3, op): return bits(imm, 11, 5) << 25 | rs2 << 20 | rs1 << 15 | f3 << 12 | bits(imm, 4, 0) << 7 | op
def B(imm, rs2, rs1, f3, op):
    return (bits(imm, 12, 12) << 31 | bits(imm, 10, 5) << 25 | rs2 << 20 | rs1 << 15 | f3 << 12
            | bits(imm, 4, 1) << 8 | bits(imm, 11, 11) << 7 | op)
def U(imm, rd, op): return (imm & 0xFFFFF) << 12 | rd << 7 | op

def assemble(line):
    op, args = line.split(None, 1)
    a = [x.strip() for x in args.replace("(", ",").replace(")", "").split(",")]
    if op == "add":  return R(0, REG[a[2]], REG[a[1]], 0, REG[a[0]], 0x33)
    if op == "sub":  return R(0x20, REG[a[2]], REG[a[1]], 0, REG[a[0]], 0x33)
    if op == "addi": return I(int(a[2]), REG[a[1]], 0, REG[a[0]], 0x13)
    if op == "lw":   return I(int(a[1]), REG[a[2]], 2, REG[a[0]], 0x03)
    if op == "sw":   return S(int(a[1]), REG[a[0]], REG[a[2]], 2, 0x23)
    if op == "beq":  return B(int(a[2]), REG[a[1]], REG[a[0]], 0, 0x63)
    if op == "bne":  return B(int(a[2]), REG[a[1]], REG[a[0]], 1, 0x63)
    if op == "lui":  return U(int(a[1], 0), REG[a[0]], 0x37)
    raise ValueError(op)

def sext(v, width): return v - (1 << width) if v >> (width - 1) else v
def disassemble(w):
    op, rd, f3, rs1, rs2, f7 = bits(w, 6, 0), bits(w, 11, 7), bits(w, 14, 12), bits(w, 19, 15), bits(w, 24, 20), bits(w, 31, 25)
    if op == 0x33: return f"{'sub' if f7 == 0x20 else 'add'} x{rd}, x{rs1}, x{rs2}"
    if op == 0x13: return f"addi x{rd}, x{rs1}, {sext(bits(w, 31, 20), 12)}"
    if op == 0x03: return f"lw x{rd}, {sext(bits(w, 31, 20), 12)}(x{rs1})"
    if op == 0x23: return f"sw x{rs2}, {sext(f7 << 5 | rd, 12)}(x{rs1})"
    if op == 0x63:
        imm = bits(w, 31, 31) << 12 | bits(w, 7, 7) << 11 | bits(w, 30, 25) << 5 | bits(w, 11, 8) << 1
        return f"{'bne' if f3 == 1 else 'beq'} x{rs1}, x{rs2}, {sext(imm, 13)}"
    if op == 0x37: return f"lui x{rd}, 0x{bits(w, 31, 12):x}"
    return "?"

