DEST = {"": "000", "M": "001", "D": "010", "A": "100", "AM": "101"}
JUMP = {"": "000", "JGT": "001", "JEQ": "010", "JMP": "111"}
def hack(line):
    if line.startswith("@"): return f"0{int(line[1:]):015b}"            # A-instruction: load a constant
    dest, rest = line.split("=") if "=" in line else ("", line)
