from collections import OrderedDict

class Cache:
    """A set-associative cache with LRU replacement. It counts misses and sorts them into the 3 Cs."""
    def __init__(self, size, line=64, ways=8):
        self.line, self.ways, self.sets = line, ways, size // (line * ways)
        self.data = [OrderedDict() for _ in range(self.sets)]
        self.full = OrderedDict(); self.capacity = size // line      # a fully associative twin, same size
        self.seen = set()
        self.hits = self.compulsory = self.capacity_misses = self.conflict = 0
    def access(self, addr):
        block = addr // self.line
        s, tag = self.data[block % self.sets], block // self.sets
        in_full = block in self.full                           # would a perfect-placement cache have hit?
        if in_full: self.full.move_to_end(block)
        else:
            self.full[block] = True
            if len(self.full) > self.capacity: self.full.popitem(last=False)
        if tag in s: s.move_to_end(tag); self.hits += 1; return
        if block not in self.seen: self.compulsory += 1        # first touch ever
        elif not in_full: self.capacity_misses += 1            # even full associativity would miss
        else: self.conflict += 1                               # only placement caused it
        self.seen.add(block)
        s[tag] = True
        if len(s) > self.ways: s.popitem(last=False)           # evict the least recently used line
    def report(self, name):
        n = self.hits + self.compulsory + self.capacity_misses + self.conflict
        m = n - self.hits
        print(f"{name:44} {n:>9,} accesses  miss rate {m / n:6.1%}  "
              f"(compulsory {self.compulsory:,}, capacity {self.capacity_misses:,}, conflict {self.conflict:,})")

