import random
from collections import OrderedDict

class Cache:                                                   # chapter 10's cache, without the 3C bookkeeping
    def __init__(self, size, line=64, ways=8):
        self.line, self.ways, self.sets = line, ways, size // (line * ways)
        self.data = [OrderedDict() for _ in range(self.sets)]; self.hits = self.misses = 0
    def access(self, addr):
        block = addr // self.line; s, tag = self.data[block % self.sets], block // self.sets
        if tag in s: s.move_to_end(tag); self.hits += 1
        else:
            self.misses += 1; s[tag] = True
            if len(s) > self.ways: s.popitem(last=False)
def amat_ns(c, hit_ns=1, miss_ns=100):                         # average memory access time model
    return (c.hits * hit_ns + c.misses * miss_ns) / (c.hits + c.misses)
KB = 1024

# 1. Matrix multiplication C = A B, n x n doubles: three loop orders and a blocked version
n, BS = 96, 16
A, B, C = 0, 8 * n * n, 16 * n * n                             # base addresses of the three matrices
def run(order):
    c = Cache(8 * KB)                                          # a small cache keeps the simulation quick
    if order == "blocked":
        for ii in range(0, n, BS):
            for kk in range(0, n, BS):
                for jj in range(0, n, BS):
                    for i in range(ii, ii + BS):
                        for k in range(kk, kk + BS):
                            c.access(A + 8 * (i * n + k))
                            for j in range(jj, jj + BS):
                                c.access(B + 8 * (k * n + j)); c.access(C + 8 * (i * n + j))
        return c
    for x in range(n):
        for y in range(n):
            if order == "i-j-k":
                i, j = x, y; c.access(C + 8 * (i * n + j))
                for k in range(n): c.access(A + 8 * (i * n + k)); c.access(B + 8 * (k * n + j))
            else:                                              # i-k-j: the inner loop walks rows of B and C
                i, k = x, y; c.access(A + 8 * (i * n + k))
                for j in range(n): c.access(B + 8 * (k * n + j)); c.access(C + 8 * (i * n + j))
    return c
print(f"multiplying two {n}x{n} matrices of doubles ({3 * 8 * n * n // KB} KiB in all) through an 8 KiB cache:")
base = None
for order in ("i-j-k", "i-k-j", "blocked"):
    c = run(order); t = amat_ns(c)
    base = base or t
    print(f"   {order:8} {c.misses:>9,} misses of {c.hits + c.misses:,}   average access {t:5.2f} ns   speed-up {base / t:4.1f}x")

