import re

# 1. Lexing: characters become tokens
def lex(src):
    return re.findall(r"\d+|[A-Za-z_]\w*|<=|[-+*/()=<{};]", src)

# 2. Parsing: tokens become a tree, by recursive descent with one function per precedence level
class Parser:
    def __init__(self, tokens): self.t, self.i = tokens, 0
    def peek(self): return self.t[self.i] if self.i < len(self.t) else None
    def eat(self, tok=None):
        x = self.t[self.i]; self.i += 1
        assert tok is None or x == tok, f"expected {tok}, got {x}"
        return x
    def program(self):
        stmts = []
        while self.peek() not in (None, "}"): stmts.append(self.statement())
        return stmts
    def statement(self):
        if self.peek() == "while":
            self.eat(); cond = self.comparison(); self.eat("{"); body = self.program(); self.eat("}")
            return ("while", cond, body)
        name = self.eat(); self.eat("="); value = self.expr(); self.eat(";")
        return ("let", name, value)
    def comparison(self):
        left = self.expr()
        if self.peek() in ("<", "<="): op = self.eat(); return (op, left, self.expr())
        return left
    def expr(self):                                            # + and - bind loosest
        node = self.term()
        while self.peek() in ("+", "-"): op = self.eat(); node = (op, node, self.term())
        return node
    def term(self):                                            # * and / bind tighter
        node = self.factor()
        while self.peek() in ("*", "/"): op = self.eat(); node = (op, node, self.factor())
        return node
    def factor(self):
        tok = self.eat()
        if tok == "(": node = self.expr(); self.eat(")"); return node
        return int(tok) if tok.isdigit() else tok

# 3. An optimisation pass: fold operations on constants at compile time
def fold(n):
    if not isinstance(n, tuple): return n
    if n[0] == "let": return ("let", n[1], fold(n[2]))
    if n[0] == "while": return ("while", fold(n[1]), [fold(s) for s in n[2]])
    op, a, b = n[0], fold(n[1]), fold(n[2])
    if isinstance(a, int) and isinstance(b, int) and op in "+-*":
        return {"+": a + b, "-": a - b, "*": a * b}[op]
    return (op, a, b)

# 4. Code generation: walk the tree, children first, emitting stack-VM commands
def gen(n, out, slots, labels):
    if isinstance(n, int): out.append(f"push constant {n}")
    elif isinstance(n, str): out.append(f"push local {slots.setdefault(n, len(slots))}")
    elif n[0] == "let":
        gen(n[2], out, slots, labels); out.append(f"pop local {slots.setdefault(n[1], len(slots))}")
    elif n[0] == "while":
        k = len(labels); labels.append(k)
        out.append(f"label TOP{k}"); gen(n[1], out, slots, labels)
        out.append("not"); out.append(f"if-goto END{k}")
        for s in n[2]: gen(s, out, slots, labels)
        out.append(f"goto TOP{k}"); out.append(f"label END{k}")
    else:
        gen(n[1], out, slots, labels); gen(n[2], out, slots, labels)
        out.append({"+": "add", "-": "sub", "*": "mul", "/": "div", "<": "lt", "<=": "le"}[n[0]])

def run_vm(code, nlocals):
    labels = {c.split()[1]: i for i, c in enumerate(code) if c.startswith("label")}
    stack, local, pc, steps = [], [0] * nlocals, 0, 0
    ops = {"add": lambda a, b: a + b, "sub": lambda a, b: a - b, "mul": lambda a, b: a * b,
           "div": lambda a, b: a // b, "lt": lambda a, b: int(a < b), "le": lambda a, b: int(a <= b)}
    while pc < len(code):
        c = code[pc].split(); pc += 1; steps += 1
        if c[0] == "push": stack.append(int(c[2]) if c[1] == "constant" else local[int(c[2])])
        elif c[0] == "pop": local[int(c[2])] = stack.pop()
        elif c[0] in ops: b, a = stack.pop(), stack.pop(); stack.append(ops[c[0]](a, b))
        elif c[0] == "not": stack.append(int(not stack.pop()))
        elif c[0] == "if-goto":
            if stack.pop(): pc = labels[c[1]]
        elif c[0] == "goto": pc = labels[c[1]]
    return local, steps

src = "x = (2 + 3) * y - 4 * 2;"
print("tokens:", lex(src))
tree = Parser(lex(src)).program()
print("tree:  ", tree[0])
print("folded:", fold(tree[0]))
for label, t in (("unoptimised", tree), ("folded", [fold(s) for s in tree])):
    code = []; gen(t[0], code, {"y": 0}, [])
    print(f"{label:12} {len(code)} VM commands: {'; '.join(code)}")

program = """
sum = 0;
i = 1;
while i <= 100 {
    sum = sum + i;
    i = i + 1;
}
"""
ast = Parser(lex(program)).program()
code, slots = [], {}
for s in ast: gen(s, code, slots, [])
local, steps = run_vm(code, len(slots))
print(f"\nthe loop compiles to {len(code)} VM commands; running them leaves sum = {local[slots['sum']]} "
      f"after {steps:,} commands")
