# 2. What creating each costs
def timed(fn, n):
    t0 = time.perf_counter(); fn(n); return (time.perf_counter() - t0) / n * 1e6
def make_threads(n):
    for _ in range(n):
        t = threading.Thread(target=lambda: None); t.start(); t.join()
def make_processes(n):
    for _ in range(n):
        pid = os.fork()
        if pid == 0: os._exit(0)
        os.waitpid(pid, 0)
print(f"\nstart and join a thread:      {timed(make_threads, 2000):6.1f} µs")
print(f"fork and wait for a process:  {timed(make_processes, 500):6.1f} µs")

# 3. A context switch, measured by ping-pong: each side blocks until the other answers
def ping_pong(n, use_threads):
    a_r, a_w = os.pipe(); b_r, b_w = os.pipe()
    def echo():
        for _ in range(n): os.write(b_w, os.read(a_r, 1))
    if use_threads:
        other = threading.Thread(target=echo); other.start()
    else:
        sys.stdout.flush()
        pid = os.fork()
        if pid == 0: echo(); os._exit(0)
    t0 = time.perf_counter()
    for _ in range(n):
        os.write(a_w, b"x"); os.read(b_r, 1)     # hand over, then wait to be handed back
    elapsed = time.perf_counter() - t0
    other.join() if use_threads else os.waitpid(pid, 0)
    for fd in (a_r, a_w, b_r, b_w): os.close(fd)
    return elapsed / n / 2 * 1e6                 # two handovers per round trip
N = 20_000
print(f"\none handover between two processes: {ping_pong(N, False):5.1f} µs")
print(f"one handover between two threads:   {ping_pong(N, True):5.1f} µs")
print(f"(this machine has {os.cpu_count()} cores; a handover includes a wake-up, a switch and a pipe)")

import textwrap, threading
from collections import deque

# A bounded buffer holding one item: one producer puts 2 items, two consumers take one each.
# The checker models a mutex and condition variables with the semantics real systems use
# (Mesa semantics): signal() only wakes a waiter, which must then win the lock again.
def program(role, check, cvs):
    full, empty = ("cv", "cv") if cvs == 1 else ("fill", "space")
    if role == "producer":
        one = [("lock",), (check, lambda n: n == 1, empty), ("put",), ("signal", full), ("unlock",)]
        return one * 2
    return [("lock",), (check, lambda n: n == 0, full), ("get",), ("signal", empty), ("unlock",)]

def explore(check, cvs):
    label = f"{check:5} with {cvs} condition variable{'s' if cvs > 1 else ''}"
    def show(steps): print(textwrap.indent(textwrap.fill("; ".join(steps), 92), "   "))
    progs = [program(role, check, cvs) for role in ("producer", "consumer", "consumer")]
    names = ["P", "C1", "C2"]
    # state: (pcs, status per thread, item count, lock holder, waiters per condition variable)
    start = ((0, 0, 0), ("run",) * 3, 0, None, ())
    parent, todo = {start: None}, deque([start])
    def trace(s):
        path = []
        while parent[s]: s, step = parent[s]; path.append(step)
        return list(reversed(path))
    while todo:
        s = todo.popleft()
        pcs, status, count, holder, waiters = s
        moves = []
        for i, prog in enumerate(progs):
            if pcs[i] == len(prog): continue
            op, st = prog[pcs[i]], status[i]
            def go(pc=pcs[i] + 1, stat="run", cnt=count, hold=holder, wait=waiters, note=""):
                p = list(pcs); p[i] = pc; t = list(status); t[i] = stat
                moves.append(((tuple(p), tuple(t), cnt, hold, wait), f"{names[i]} {note or op[0]}"))
            if st.startswith("waiting"): continue                              # asleep until signalled
            if st == "woken":                                                  # must win the lock back
                if holder is None:
                    again = pcs[i] if op[0] == "while" else pcs[i] + 1         # while: re-check; if: go on
                    go(pc=again, hold=i, note="wakes and takes the lock")
                continue
            if op[0] == "lock" and holder is None: go(hold=i, note="takes the lock")
            elif op[0] == "unlock": go(hold=None, note="releases the lock")
            elif op[0] in ("if", "while"):
                if op[1](count): go(pc=pcs[i], stat="waiting", hold=None,
                                    wait=tuple(sorted(waiters + ((op[2], i),))), note=f"waits on {op[2]}")
                else: go(note="can go ahead")
            elif op[0] == "put": go(cnt=count + 1, note="puts an item")
            elif op[0] == "get":
                if count == 0:
                    print(f"{label}: BUG, a consumer took from an empty buffer")
                    show(trace(s) + [f"{names[i]} takes from the empty buffer"])
                    return
                go(cnt=count - 1, note="takes the item")
            elif op[0] == "signal":
                sleepers = [w for w in waiters if w[0] == op[1]]
                if not sleepers: go(note=f"signals {op[1]} (no one waiting)")
                for w in sleepers:                                             # the system picks any waiter
                    t = list(status); t[w[1]] = "woken"
                    p = list(pcs); p[i] += 1
                    moves.append(((tuple(p), tuple(t), count, holder, tuple(x for x in waiters if x != w)),
                                  f"{names[i]} signals {op[1]}, waking {names[w[1]]}"))
        if not moves and any(pc < len(pr) for pc, pr in zip(pcs, progs)):
            print(f"{label}: DEADLOCK, everyone left is asleep")
            show(trace(s))
            return
        for n, step in moves:
            if n not in parent: parent[n] = (s, step); todo.append(n)
    print(f"{label}: correct in all {len(parent):,} reachable states")

explore("if", 1)
explore("while", 1)
explore("while", 2)

