buf, CAP = deque(), 4
lock = threading.Lock(); has_item = threading.Condition(lock); has_space = threading.Condition(lock)
def producer(items):
    for x in items:
        with lock:
            while len(buf) == CAP: has_space.wait()
            buf.append(x); has_item.notify()
totals = [0, 0, 0]
def consumer(k, n):
    for _ in range(n):
        with lock:
            while not buf: has_item.wait()
            totals[k] += buf.popleft(); has_space.notify()
threads = [threading.Thread(target=producer, args=(range(1, 30_001),))] + \
          [threading.Thread(target=consumer, args=(k, 10_000)) for k in range(3)]
for t in threads: t.start()
