print(f"\nreal threads, 3 consumers sharing 30,000 items through a 4-slot buffer: sum {sum(totals):,} "
      f"(expected {30_000 * 30_001 // 2:,})")

import random, threading
from collections import deque

# 1. Dining philosophers: each picks up one fork, then the other, eats, and puts both down.
def dine(n, ordered):
    def forks(p):                                            # left fork p, right fork p+1 (mod n)
        a, b = p, (p + 1) % n
        return (min(a, b), max(a, b)) if ordered else (a, b) # ordered: always the lower number first
    start = ((0,) * n, (None,) * n)                          # (step of each philosopher, fork owners)
    seen, todo = {start}, deque([start])
    while todo:
        steps, owner = todo.popleft()
        moves = []
        for p in range(n):
            first, second = forks(p)
            o = list(owner); s = list(steps)
            if steps[p] == 0 and owner[first] is None: o[first] = p; s[p] = 1        # pick up first fork
            elif steps[p] == 1 and owner[second] is None: o[second] = p; s[p] = 2    # pick up second
            elif steps[p] == 2: o[first] = o[second] = None; s[p] = 0                # eat, put both down
            else: continue
            moves.append((tuple(s), tuple(o)))
        if not moves:
            return f"DEADLOCK, found after {len(seen)} states: everyone holds one fork, waiting for another"
        for m in moves:
            if m not in seen: seen.add(m); todo.append(m)
    return f"no deadlock in any of the {len(seen)} reachable states"
for n in (3, 5):
    print(f"{n} philosophers, left fork first:   {dine(n, ordered=False)}")
    print(f"{n} philosophers, lower fork first:  {dine(n, ordered=True)}")

# 2. Detecting a deadlock after the fact: a cycle in the graph of who waits for whom
holds = {"L1": "T1", "L2": "T2", "L3": "T3", "L4": "T4"}
waits = {"T1": "L2", "T2": "L3", "T3": "L1", "T4": "L1"}
def find_cycle(start):
    path, t = [], start
    while t in waits and t not in path:
        path.append(t); t = holds[waits[t]]
    return path[path.index(t):] if t in path else None
cycle = next(c for c in (find_cycle(t) for t in waits) if c)
print("\nwait-for cycle: " + " -> ".join(f"{t} waits for {waits[t]} (held by {holds[waits[t]]})"
                                        for t in cycle))
print("T4 is stuck too, but only because it waits on the cycle; breaking the cycle frees it")

# 3. Real threads, real locks, opposite order. A barrier makes both take their first lock first.
A, B = threading.Lock(), threading.Lock()
both_hold_one, both_tried = threading.Barrier(2), threading.Barrier(2)
report = {}
def worker(name, first, second, align):
    with first:
        if align: both_hold_one.wait()                       # make the bad timing certain
        got = second.acquire(timeout=0.5)                    # give up after half a second
        report[name] = "got both locks" if got else "timed out waiting: deadlock"
        if got: second.release()
        if align: both_tried.wait()                          # neither lets go before both have tried
for label, orders, align in (("opposite order", ((A, B), (B, A)), True),
                             ("same order", ((A, B), (A, B)), False)):
    ts = [threading.Thread(target=worker, args=(f"T{k + 1}", *orders[k], align)) for k in range(2)]
    for t in ts: t.start()
    for t in ts: t.join()
    print(f"\n{label}: " + "; ".join(f"{k} {v}" for k, v in sorted(report.items())))

# 4. Livelock: on a conflict each thread politely lets go and retries. In lockstep, forever.
def polite(backoff, rounds=50):
    random.seed(10)
    delay = [0, 0]
    for r in range(rounds):
        trying = [t for t in (0, 1) if delay[t] == 0]
        if len(trying) == 1: return f"thread {trying[0] + 1} got both locks in round {r + 1}"
        for t in (0, 1): delay[t] = max(0, delay[t] - 1)
        if len(trying) == 2 and backoff:                     # both collided: each waits a random time
            for t in trying: delay[t] = random.randint(0, 3)
    return f"no one finished in {rounds} rounds: both busy, no progress"
print(f"\nlivelock, retrying at once:      {polite(False)}")
print(f"livelock, with random backoff:   {polite(True)}")

# Protocol Buffers encode a message by FIELD NUMBER, not field name. That one fact is why
# services that deploy independently can evolve their schemas without breaking each other.
def varint(n):
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        out.append(b | (0x80 if n else 0))
        if not n:
            return bytes(out)


def read_varint(data, i):
    result = shift = 0
    while True:
        b = data[i]; i += 1
        result |= (b & 0x7F) << shift
        if not (b & 0x80):
            return result, i
        shift += 7


def encode(fields):
    """fields: {field_number: value}. int -> varint (wire type 0), str -> length-delimited (2)."""
    out = bytearray()
    for num, value in fields.items():
        if isinstance(value, int):
            out += varint((num << 3) | 0) + varint(value)
        else:
            raw = value.encode()
            out += varint((num << 3) | 2) + varint(len(raw)) + raw
    return bytes(out)


def decode(data, schema):
    """schema: {field_number: (name, type)}. Unknown fields are kept but skipped, forward-compat."""
    out, i = {}, 0
    while i < len(data):
        tag, i = read_varint(data, i)
        num, wire = tag >> 3, tag & 0x7
        if wire == 0:
            value, i = read_varint(data, i)
        else:
            length, i = read_varint(data, i)
            value, i = data[i:i + length], i + length
        if num in schema:
            name, typ = schema[num]
            out[name] = value.decode() if typ == "str" else value
        else:
            out[f"<unknown field {num}>"] = value       # old code tolerates new fields
    return out


if __name__ == "__main__":
    wire = encode({1: 42, 2: "widget"})                  # id=42, name="widget"
    print("on the wire:", wire.hex(), f"({len(wire)} bytes)")

    v1 = {1: ("id", "int"), 2: ("name", "str")}
    print("v1 schema decodes:  ", decode(wire, v1))

    # Rename field 2 "name" -> "label": safe, because the wire uses the NUMBER, not the name.
    v2_rename = {1: ("id", "int"), 2: ("label", "str")}
    print("after renaming f2:  ", decode(wire, v2_rename))

    # A new field 3 added by a newer sender; the old decoder keeps it as unknown, no crash.
    newer = encode({1: 42, 2: "widget", 3: 7})
    print("old code, new data: ", decode(newer, v1))

    # DANGER: reusing field number 2 for a new meaning silently corrupts old data.
    v_bad = {1: ("id", "int"), 2: ("price_cents", "int")}
    print("reused number 2:    ", decode(wire, v_bad), "<- price_cents is garbage, not a price")

# TCP can't be told how fast to send, so it probes: ramp up, and back off when loss appears.
# This is the "AIMD sawtooth" of classic congestion control (Reno-style).
def simulate(rounds, ssthresh=16, loss_rounds=()):
    cwnd = 1                     # congestion window, in segments; grows per round-trip
    history = []
    for r in range(rounds):
        phase = "slow-start" if cwnd < ssthresh else "avoidance"
        history.append((r, cwnd, phase))
        if r in loss_rounds:
            ssthresh = max(1, cwnd // 2)     # multiplicative decrease: halve the target
            cwnd = ssthresh                  # (a timeout would reset cwnd to 1 instead)
        elif cwnd < ssthresh:
            cwnd *= 2                         # slow start: double each round (exponential)
        else:
            cwnd += 1                         # congestion avoidance: additive increase (+1/RTT)
    return history


def bdp(bandwidth_mbps, rtt_ms):
    """Bandwidth-delay product: bytes in flight needed to keep the pipe full."""
    return bandwidth_mbps * 1_000_000 / 8 * (rtt_ms / 1000)


if __name__ == "__main__":
    print("round  cwnd  phase          (one '#' per segment)")
    for r, cwnd, phase in simulate(16, ssthresh=16, loss_rounds={6, 12}):
        bar = "#" * cwnd
        print(f"{r:4}  {cwnd:4}  {phase:13}  {bar}")
    print("\nnote the sawtooth: exponential ramp, then +1/round, halve on loss, repeat.")

    need = bdp(100, 80)                        # 100 Mbps link, 80ms RTT
    print(f"\nto fill a 100 Mbps link at 80ms RTT you need {need/1024:.0f} KB in flight.")
    print(f"a default 64 KB window would cap you at {64*1024*8 / (80/1000) / 1e6:.0f} Mbps"
          f" -- far below the link. This is why TCP window scaling exists.")

import ipaddress

# An IP address plus a prefix length (CIDR) splits into a network part and a host part.
# The /N means "the first N bits identify the network"; the rest identify the host.
def describe(cidr):
    net = ipaddress.ip_network(cidr, strict=False)
    hosts = list(net.hosts())
    return {
        "network": str(net.network_address),
        "prefix": net.prefixlen,
        "total_addresses": net.num_addresses,
        "usable_hosts": len(hosts),
        "first_host": str(hosts[0]) if hosts else None,
        "last_host": str(hosts[-1]) if hosts else None,
        "broadcast": str(net.broadcast_address) if net.version == 4 else "(none in IPv6)",
    }


def in_network(ip, cidr):
    return ipaddress.ip_address(ip) in ipaddress.ip_network(cidr)


