import re

source = "2 * (3 + 4) - 10 / 5"

# 1. Lexing: characters -> tokens
def lex(text):
    tokens = []
    for number, symbol in re.findall(r"\s*(?:(\d+)|(\S))", text):
        tokens.append(("NUM", int(number)) if number else ("OP", symbol))
    return tokens + [("END", None)]

# 2. Parsing: tokens -> a tree. One function per grammar rule (recursive descent):
#    expr = term (("+" | "-") term)* ;  term = factor (("*" | "/") factor)* ;  factor = NUM | "(" expr ")"
def parse(tokens):
    pos = 0
    def peek(): return tokens[pos][1]
    def take():
        nonlocal pos; pos += 1; return tokens[pos - 1]
    def expr():
        node = term()
        while peek() in ("+", "-"): node = (take()[1], node, term())
        return node
    def term():
        node = factor()
        while peek() in ("*", "/"): node = (take()[1], node, factor())
        return node
    def factor():
        kind, value = take()
        if kind == "NUM": return ("num", value)
        if value == "(":
            node = expr(); take(); return node              # skip the ")"
        raise SyntaxError(f"unexpected {value!r}")
    return expr()

def show(node):
    return str(node[1]) if node[0] == "num" else f"({node[0]} {show(node[1])} {show(node[2])})"

OPS = {"+": lambda a, b: a + b, "-": lambda a, b: a - b, "*": lambda a, b: a * b, "/": lambda a, b: a / b}

# 3a. A tree-walking interpreter: evaluate the tree directly
visits = 0
def evaluate(node):
    global visits; visits += 1
    if node[0] == "num": return node[1]
    return OPS[node[0]](evaluate(node[1]), evaluate(node[2]))

# 3b. Or compile the tree to instructions for a stack machine, then run those
def compile_(node, code):
    if node[0] == "num": code.append(("PUSH", node[1]))
    else:
        compile_(node[1], code); compile_(node[2], code)
        code.append(({"+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV"}[node[0]], None))
    return code
def run(code):
    stack = []
    for op, arg in code:
        if op == "PUSH": stack.append(arg)
        else:
            b, a = stack.pop(), stack.pop()
            stack.append(OPS[{"ADD": "+", "SUB": "-", "MUL": "*", "DIV": "/"}[op]](a, b))
    return stack.pop()

