KEYWORDS = {"let", "fun", "return", "if", "else", "while", "print", "true", "false", "nil", "and", "or"}
TWO_CHAR = {"==", "!=", "<=", ">="}
ONE_CHAR = set("+-*/%=<>!(){},;")

class LexError(Exception): pass

def scan(src):
    """A hand-written scanner: one pass over the characters, tracking line and column."""
    tokens, i, line, col = [], 0, 1, 1
    def error(msg, at_col):
        text = src.splitlines()[line - 1]
        raise LexError(f"line {line}, column {at_col}: {msg}\n    {text}\n    {' ' * (at_col - 1)}^")
    while i < len(src):
        c, start, start_col = src[i], i, col
        if c == "\n": i += 1; line += 1; col = 1; continue
        if c in " \t\r": i += 1; col += 1; continue
        if src.startswith("//", i):                              # a comment runs to the end of the line
            while i < len(src) and src[i] != "\n": i += 1
            continue
        if c.isdigit():                                          # 12, 3.5, 1e9, 2.5e-3
            while i < len(src) and src[i].isdigit(): i += 1
            if src[i:i + 1] == "." and src[i + 1:i + 2].isdigit():
                i += 1
                while i < len(src) and src[i].isdigit(): i += 1
            if src[i:i + 1] in ("e", "E"):
                j = i + 1 + (src[i + 1:i + 2] in ("+", "-"))
                if src[j:j + 1].isdigit():
                    i = j
                    while i < len(src) and src[i].isdigit(): i += 1
            tokens.append(("NUM", float(src[start:i]), line))
        elif c.isalpha() or c == "_":                            # identifiers, and keywords among them
            while i < len(src) and (src[i].isalnum() or src[i] == "_"): i += 1
            word = src[start:i]
            tokens.append((word.upper(), None, line) if word in KEYWORDS else ("IDENT", word, line))
        elif c == '"':
            i += 1; chars = []
            while i < len(src) and src[i] != '"':
                if src[i] == "\n": error("unterminated string", start_col)
                if src[i] == "\\":
                    i += 1
                    chars.append({"n": "\n", "t": "\t", '"': '"', "\\": "\\"}.get(src[i:i + 1]) or
                                 error(f"unknown escape \\{src[i:i + 1]}", col + i - start))
                else: chars.append(src[i])
                i += 1
            if i >= len(src): error("unterminated string", start_col)
            i += 1
            tokens.append(("STR", "".join(chars), line))
        elif src[i:i + 2] in TWO_CHAR:                           # maximal munch: the longest match wins
            i += 2; tokens.append((src[start:i], None, line))
        elif c in ONE_CHAR:
            i += 1; tokens.append((c, None, line))
        else:
            error(f"unexpected character {c!r}", start_col)
        col += i - start
    return tokens + [("EOF", None, line)]

