from functools import lru_cache

# 1. An ambiguous grammar:  E -> E + E | E - E | E * E | num.  Every way of splitting is a parse tree.
def trees(tokens):
    @lru_cache(maxsize=None)
    def span(i, j):                                    # all trees for tokens[i..j]
        if i == j: return [tokens[i]]
        out = []
        for k in range(i + 1, j, 2):                   # pick the operator at the root
            for left in span(i, k - 1):
                for right in span(k + 1, j): out.append((tokens[k], left, right))
        return out
    return span(0, len(tokens) - 1)
def value(t):
    if isinstance(t, int): return t
    a, b = value(t[1]), value(t[2])
    return a + b if t[0] == "+" else a - b if t[0] == "-" else a * b
def show(t): return str(t) if isinstance(t, int) else f"({t[0]} {show(t[1])} {show(t[2])})"

