# 2. The dangling else:  S -> if c then S | if c then S else S | s
def parses(tokens):
    @lru_cache(maxsize=None)
    def S(i, j):
        if j - i == 1 and tokens[i] == "s": return 1
        if j - i < 4 or tokens[i:i + 3] != ("if", "c", "then"): return 0
        n = S(i + 3, j)                                              # if c then S
        for k in range(i + 4, j - 1):
            if tokens[k] == "else": n += S(i + 3, k) * S(k + 1, j)   # if c then S else S
        return n
    return S(0, len(tokens))
