# 3. An LL(1) grammar for expressions, with precedence built in and no left recursion
G = {"E": [["T", "E'"]], "E'": [["+", "T", "E'"], []], "T": [["F", "T'"]],
     "T'": [["*", "F", "T'"], []], "F": [["(", "E", ")"], ["id"]]}
FIRST = {n: set() for n in G}; FOLLOW = {n: set() for n in G}; FOLLOW["E"].add("$")
def first_of(seq):
    out = set()
    for sym in seq:
        f = FIRST[sym] if sym in G else {sym}
        out |= f - {"ε"}
        if "ε" not in f: return out
    return out | {"ε"}
changed = True
while changed:                                         # iterate to a fixed point
    changed = False
    for n, rules in G.items():
        for rule in rules:
            f = first_of(rule)
            if not f <= FIRST[n]: FIRST[n] |= f; changed = True
            for i, sym in enumerate(rule):
                if sym in G:
                    rest = first_of(rule[i + 1:])
                    new = (rest - {"ε"}) | (FOLLOW[n] if "ε" in rest else set())
                    if not new <= FOLLOW[sym]: FOLLOW[sym] |= new; changed = True
print("\nFIRST and FOLLOW sets:")
for n in G: print(f"   {n:3} FIRST {sorted(FIRST[n])!s:20} FOLLOW {sorted(FOLLOW[n])}")
table = {}
for n, rules in G.items():
    for rule in rules:
        f = first_of(rule)
        for t in (f - {"ε"}) | (FOLLOW[n] if "ε" in f else set()):
            assert (n, t) not in table, "not LL(1)"           # two rules for one cell: a conflict
            table[n, t] = rule
def ll1(tokens):
    stack, tokens, steps = ["$", "E"], tokens + ["$"], 0
    while stack:
        top, steps = stack.pop(), steps + 1
        if top == tokens[0]: tokens.pop(0); continue
        if (top, tokens[0]) not in table: return f"syntax error at {tokens[0]!r} after {steps} steps"
        stack.extend(reversed(table[top, tokens[0]]))
    return f"accepted in {steps} steps"
print(f"LL(1) table: {len(table)} cells, no conflicts")
