import re

def lex(src):
    toks = []
    for line_no, line in enumerate(src.splitlines(), 1):
        for m in re.finditer(r"\s*(\d+|[A-Za-z_]\w*|==|!=|<=|>=|\S)", line):
            toks.append((m.group(1), line_no))
    return toks + [("<eof>", line_no)]

# Binding powers: how tightly each infix operator holds its operands. (left, right) power:
# right > left makes it left-associative; right < left makes it right-associative.
INFIX = {"or": (1, 2), "and": (3, 4), "==": (5, 6), "!=": (5, 6), "<": (7, 8), "<=": (7, 8), ">": (7, 8),
         ">=": (7, 8), "+": (9, 10), "-": (9, 10), "*": (11, 12), "/": (11, 12), "%": (11, 12),
         "^": (14, 13), "(": (15, None)}
PREFIX_POWER = 13                                         # unary - and ! bind tighter than * but not ^

class ParseError(Exception): pass

class Parser:
    def __init__(self, src): self.toks, self.i, self.errors = lex(src), 0, []
    def peek(self): return self.toks[self.i][0]
    def next(self): self.i += 1; return self.toks[self.i - 1][0]
    def expect(self, t):
        if self.peek() != t: self.fail(f"expected {t!r} but found {self.peek()!r}")
        self.next()
    def fail(self, msg): raise ParseError(f"line {self.toks[self.i][1]}: {msg}")

    def expr(self, min_power=0):                          # Pratt's algorithm
        t = self.next()
        if t.isdigit() or (t[0].isalpha() and t not in INFIX): left = t
        elif t == "(": left = self.expr(); self.expect(")")
        elif t in ("-", "!"): left = f"({t} {self.expr(PREFIX_POWER)})"
        else: self.i -= 1; self.fail(f"expected an expression but found {t!r}")
        while self.peek() in INFIX:
            op = self.peek(); lp, rp = INFIX[op]
            if lp < min_power: break                      # the operator belongs to an outer call
            self.next()
            if op == "(":                                 # a call: f(a, b)
                args = []
                while self.peek() != ")":
                    args.append(self.expr())
                    if self.peek() != ")": self.expect(",")
                self.next(); left = f"(call {left}{''.join(' ' + a for a in args)})"
            else:
                left = f"({op} {left} {self.expr(rp)})"
        return left

    def statement(self):
        if self.peek() == "let":
            self.next(); name = self.next()
            if not name[0].isalpha(): self.i -= 1; self.fail(f"expected a variable name but found {name!r}")
            self.expect("="); value = self.expr(); self.expect(";")
            return f"(let {name} {value})"
        if self.peek() == "print":
            self.next(); value = self.expr(); self.expect(";"); return f"(print {value})"
        value = self.expr(); self.expect(";"); return value

    def program(self):
        out = []
        while self.peek() != "<eof>":
            try: out.append(self.statement())
            except ParseError as e:
                self.errors.append(str(e))                # record it, then resynchronise:
                while self.peek() not in (";", "<eof>", "let", "print"): self.next()
                if self.peek() == ";": self.next()        # skip to the end of the broken statement
        return out

