# A resolver walks the syntax tree once, before the program runs, and works out which declaration
# every name refers to. Programs are given as the tree a parser would produce, with line numbers.

class Resolver:
    def __init__(self):
        self.scopes, self.in_function, self.notes, self.errors = [], 0, [], []
        self.globals, self.global_uses = {"get"}, []          # get is a built-in function
    def declare(self, name, line):
        if not self.scopes: self.globals.add(name); return   # globals are looked up by name at run time
        scope = self.scopes[-1]
        if name in scope: self.errors.append(f"line {line}: '{name}' is already declared in this scope")
        scope[name] = {"slot": len(scope), "ready": False, "used": False, "line": line}
    def define(self, name):
        if self.scopes: self.scopes[-1][name]["ready"] = True
    def lookup(self, name, line, what="read"):
        for hops, scope in enumerate(reversed(self.scopes)):
            if name in scope:
                v = scope[name]
                if not v["ready"]:
                    self.errors.append(f"line {line}: can't read '{name}' in its own initializer")
                v["used"] = True
                where = f"local, {hops} scope{'s' if hops != 1 else ''} up, slot {v['slot']}"
                self.notes.append(f"line {line}: {what:5} {name:6} -> {where}")
                return
        self.notes.append(f"line {line}: {what:5} {name:6} -> global, found by name at run time")
        self.global_uses.append((name, line))
    def begin(self): self.scopes.append({})
    def end(self):
        for name, v in self.scopes.pop().items():
            if not v["used"]: self.errors.append(f"line {v['line']}: warning: '{name}' is never used")
    def resolve(self, node):
        kind = node[0]
        if kind == "block":
            self.begin()
            for s in node[1]: self.resolve(s)
            self.end()
        elif kind == "let":
            _, name, init, line = node
            self.declare(name, line); self.resolve(init); self.define(name)
        elif kind == "fun":
            _, name, params, body, line = node
            self.declare(name, line); self.define(name)       # defined first, so it can call itself
            self.in_function += 1; self.begin()
            for p in params: self.declare(p, line); self.define(p); self.scopes[-1][p]["used"] = True
            for s in body: self.resolve(s)
            self.end(); self.in_function -= 1
        elif kind == "var": self.lookup(node[1], node[2])
        elif kind == "assign": self.resolve(node[2]); self.lookup(node[1], node[3], "write")
        elif kind == "return":
            if not self.in_function: self.errors.append(f"line {node[2]}: 'return' outside a function")
            self.resolve(node[1])
        elif kind in ("print", "expr"): self.resolve(node[1])
        elif kind == "while": self.resolve(node[1]); self.resolve(node[2])
        elif kind == "binop": self.resolve(node[2]); self.resolve(node[3])
        elif kind == "call": self.resolve(node[1]); [self.resolve(a) for a in node[2]]
        # "num" needs nothing

def run(title, program):
    r = Resolver()
    for stmt in program: r.resolve(stmt)
    for name, line in r.global_uses:                         # globals may be declared later in the file,
        if name not in r.globals:                            # so check them once everything is seen
            r.errors.append(f"line {line}: '{name}' is not declared anywhere")
    print(title)
    for n in r.notes: print(f"   {n}")
    for e in r.errors: print(f"   {e}")
    if not r.errors: print("   no errors")

