import re

def read(src):
    """Read an S-expression: (f a (g b)) becomes ['f', 'a', ['g', 'b']]."""
    tokens = re.findall(r'\(|\)|"[^"]*"|[^\s()]+', src)
    def form():
        t = tokens.pop(0)
        if t != "(": return int(t) if t.lstrip("-").isdigit() else t
        out = []
        while tokens[0] != ")": out.append(form())
        tokens.pop(0); return out
    return form()

class TypeError_(Exception): pass

def show(t): return t if isinstance(t, str) else f"fn({', '.join(map(show, t[0]))}) -> {show(t[1])}"

def check(e, env):
    """Return the type of expression e, or raise. Types: 'int', 'bool', 'str', or (params, result)."""
    if isinstance(e, int): return "int"
    if isinstance(e, str):
        if e.startswith('"'): return "str"
        if e in ("true", "false"): return "bool"
        if e not in env: raise TypeError_(f"unknown variable '{e}'")
        return env[e]
    op, *args = e
    if op in ("+", "-", "*", "<"):
        for a in args:
            if (t := check(a, env)) != "int": raise TypeError_(f"'{op}' needs int operands, got {show(t)}")
        return "bool" if op == "<" else "int"
    if op == "++":
        for a in args:
            if (t := check(a, env)) != "str": raise TypeError_(f"'++' joins strings, got {show(t)}")
        return "str"
    if op == "if":
        if (c := check(args[0], env)) != "bool":
            raise TypeError_(f"'if' needs a bool condition, got {show(c)}")
        a, b = check(args[1], env), check(args[2], env)
        if a != b: raise TypeError_(f"the branches of 'if' have different types: {show(a)} and {show(b)}")
        return a
    if op == "let":                                       # (let (name value) body)
        (name, value), body = args
        return check(body, {**env, name: check(value, env)})
    if op == "fn":                                        # (fn ((x int) ...) result body)
        params, result, body = args
        got = check(body, {**env, **{p: t for p, t in params}})
        if got != result: raise TypeError_(f"function declared to return {result} returns {show(got)}")
        return ([t for _, t in params], result)
    f = check(op, env)                                    # a call
    if isinstance(f, str): raise TypeError_(f"{show(f)} is not a function")
    if len(args) != len(f[0]): raise TypeError_(f"expected {len(f[0])} arguments, got {len(args)}")
    for i, (a, want) in enumerate(zip(args, f[0]), 1):
        if (got := check(a, env)) != want:
            raise TypeError_(f"argument {i} should be {want}, got {show(got)}")
    return f[1]

def evaluate(e, env):                                    # the same language, run without checking
    if isinstance(e, int): return e
    if isinstance(e, str):
        if e.startswith('"'): return e.strip('"')
        return {"true": True, "false": False}.get(e, env.get(e))
    op, *args = e
    if op == "if": return evaluate(args[1] if evaluate(args[0], env) else args[2], env)
    if op == "let": (name, value), body = args; return evaluate(body, {**env, name: evaluate(value, env)})
    if op == "fn":
        params, _, body = args
        names = [p for p, _ in params]
        return lambda *vs: evaluate(body, {**env, **dict(zip(names, vs))})
    vals = [evaluate(a, env) for a in args]
    if op == "+": return vals[0] + vals[1]
    if op == "-": return vals[0] - vals[1]
    if op == "*": return vals[0] * vals[1]
    if op == "<": return vals[0] < vals[1]
    if op == "++": return "".join(vals)                  # fails if a value isn't a string
    return evaluate(op, env)(*vals)

