import re

def read(src):
    tokens = re.findall(r"\(|\)|[^\s()]+", src)
    def form():
        t = tokens.pop(0)
        if t != "(": return int(t) if t.isdigit() else t
        out = []
        while tokens[0] != ")": out.append(form())
        tokens.pop(0); return out
    return form()

# Types are type variables, which unification may later bind, or constructors such as int, ->, list.
class TVar:
    count = 0
    def __init__(self): self.ref = None; TVar.count += 1; self.id = TVar.count
class TCon:
    def __init__(self, name, *args): self.name, self.args = name, list(args)
def fn(a, b): return TCon("->", a, b)
INT, BOOL = TCon("int"), TCon("bool")

def prune(t):                                         # follow a chain of bound variables to its end
    while isinstance(t, TVar) and t.ref is not None: t = t.ref
    return t
def occurs(v, t):
    t = prune(t)
    return t is v or (isinstance(t, TCon) and any(occurs(v, a) for a in t.args))
def unify(a, b):
    a, b = prune(a), prune(b)
    if isinstance(a, TVar):
        if a is b: return
        if occurs(a, b): raise TypeError(f"infinite type: {show(a)} = {show(b)}")
        a.ref = b
    elif isinstance(b, TVar): unify(b, a)
    elif a.name != b.name or len(a.args) != len(b.args):
        raise TypeError(f"can't match {show(a)} with {show(b)}")
    else:
        for x, y in zip(a.args, b.args): unify(x, y)

def free(t):
    t = prune(t)
    return {t} if isinstance(t, TVar) else set().union(*(free(a) for a in t.args)) if t.args else set()
def generalize(t, env):                               # quantify the variables the environment doesn't pin
    pinned = set().union(*(free(ty) - set(vs) for vs, ty in env.values())) if env else set()
    return (list(free(t) - pinned), t)
def instantiate(scheme):
    vs, t = scheme
    fresh = {v: TVar() for v in vs}
    def copy(t):
        t = prune(t)
        if isinstance(t, TVar): return fresh.get(t, t)
        return TCon(t.name, *[copy(a) for a in t.args])
    return copy(t)

def infer(e, env):
    if isinstance(e, int): return INT
    if e in ("true", "false"): return BOOL
    if isinstance(e, str):
        if e not in env: raise TypeError(f"unknown variable {e}")
        return instantiate(env[e])
    head = e[0]
    if head == "fn":                                  # (fn x body)
        v = TVar()
        return fn(v, infer(e[2], {**env, e[1]: ([], v)}))
    if head == "let":                                 # (let (x value) body): x is generalised
        (x, value), body = e[1], e[2]
        return infer(body, {**env, x: generalize(infer(value, env), env)})
    if head == "letrec":                              # like let, but the value may refer to x
        (x, value), body = e[1], e[2]
        v = TVar(); unify(v, infer(value, {**env, x: ([], v)}))
        return infer(body, {**env, x: generalize(v, env)})
    if head == "if":
        unify(infer(e[1], env), BOOL)
        then = infer(e[2], env); unify(then, infer(e[3], env)); return then
    f = infer(head, env)                              # application, one argument at a time
    for arg in e[1:]:
        result = TVar(); unify(f, fn(infer(arg, env), result)); f = result
    return f

def show(t, names=None):
    names = {} if names is None else names
    t = prune(t)
    if isinstance(t, TVar): return names.setdefault(t, "'" + "abcdefgh"[len(names)])
    if t.name == "->":                                # arrows group to the right: a -> b -> c
        arg, a = prune(t.args[0]), show(t.args[0], names)
        if isinstance(arg, TCon) and arg.name in ("->", "*"): a = f"({a})"
        return f"{a} -> {show(t.args[1], names)}"
    if t.name == "*": return f"{show(t.args[0], names)} * {show(t.args[1], names)}"
    return t.name if not t.args else f"{t.name} {show(t.args[0], names)}"

def scheme(build):                                    # a built-in with fresh, fully general variables
    a, b = TVar(), TVar()
    t = build(a, b)
    return (list(free(t)), t)
BUILTINS = {
