class Compiler:
    """Turns the tree into a flat list of instructions for a stack machine."""
    def __init__(self): self.code, self.consts, self.slots = [], [], {}
    def emit(self, op, arg=None): self.code.append([op, arg]); return len(self.code) - 1
    def patch(self, at): self.code[at][1] = len(self.code)       # fill in a forward jump's target
    def expr(self, x):
        if isinstance(x, int):
            if x not in self.consts: self.consts.append(x)
            self.emit("CONST", self.consts.index(x))
        elif isinstance(x, str): self.emit("LOAD", self.slots[x])
        else:
            self.expr(x[1]); self.expr(x[2])
            self.emit({"+": "ADD", "-": "SUB", "*": "MUL", "<": "LESS"}[x[0]])
    def stmt(self, x):
        op = x[0]
        if op == "begin":
            for s in x[1:]: self.stmt(s)
        elif op == "set":
            self.expr(x[2]); self.emit("STORE", self.slots.setdefault(x[1], len(self.slots)))
        elif op == "print": self.expr(x[1]); self.emit("PRINT")
        elif op == "if":
            self.expr(x[1])
            to_else = self.emit("JUMP_IF_FALSE")                     # target not known yet
            self.stmt(x[2])
            to_end = self.emit("JUMP")
            self.patch(to_else)                                      # backpatch: else starts here
            self.stmt(x[3])
            self.patch(to_end)
        elif op == "while":
            top = len(self.code)
            self.expr(x[1])
            to_exit = self.emit("JUMP_IF_FALSE")
            self.stmt(x[2])
            self.emit("JUMP", top)                                   # backwards: target already known
            self.patch(to_exit)

