def run(code, consts):
    stack, slots, pc, executed, out = [], [0] * len(c.slots), 0, 0, []
    while True:
        op, arg = code[pc]; pc += 1; executed += 1
        if op == "CONST": stack.append(consts[arg])
        elif op == "LOAD": stack.append(slots[arg])
        elif op == "STORE": slots[arg] = stack.pop()
        elif op in ("ADD", "SUB", "MUL", "LESS"):
            b, a = stack.pop(), stack.pop()
            stack.append({"ADD": a + b, "SUB": a - b, "MUL": a * b, "LESS": a < b}[op])
        elif op == "JUMP": pc = arg
        elif op == "JUMP_IF_FALSE":
            if not stack.pop(): pc = arg
        elif op == "PRINT": out.append(stack.pop())
        elif op == "HALT": return out, executed

