def walk(x, env):                                                   # the same program, tree-walked
    global steps; steps += 1
    if isinstance(x, int): return x
    if isinstance(x, str): return env[x]
    op = x[0]
    if op == "begin":
        for s in x[1:]: walk(s, env)
    elif op == "set": env[x[1]] = walk(x[2], env)
    elif op == "print": print(f"tree-walker printed {walk(x[1], env)} after", end=" ")
    elif op == "if": walk(x[2] if walk(x[1], env) else x[3], env)
    elif op == "while":
        while walk(x[1], env): walk(x[2], env)
    else:
        a, b = walk(x[1], env), walk(x[2], env)
        return a + b if op == "+" else a - b if op == "-" else a * b if op == "*" else a < b
