import re, textwrap

def read(src):
    tokens = re.findall(r"\(|\)|[^\s()]+", src)
    def form():
        t = tokens.pop(0)
        if t != "(": return int(t) if t.lstrip("-").isdigit() else t
        out = []
        while tokens[0] != ")": out.append(form())
        tokens.pop(0); return out
    return form()

ARITH = {"+": "ADD", "-": "SUB", "<": "LESS"}
def compile_fn(params, body, fused):
    """Compile one function. Parameters live in slots counted from the frame's base."""
    code = []
    def expr(x):
        if isinstance(x, int): code.append(("CONST", x))
        elif isinstance(x, str): code.append(("LOAD", params.index(x)))
        elif x[0] == "if":
            expr(x[1]); jf = len(code); code.append(None)
            expr(x[2]); j = len(code); code.append(None)
            code[jf] = ("JUMP_IF_FALSE", len(code)); expr(x[3]); code[j] = ("JUMP", len(code))
        elif x[0] in ARITH:
            expr(x[1])
            if fused and isinstance(x[2], int):               # one instruction: operator and constant
                code.append((ARITH[x[0]] + "_K", x[2]))
            else: expr(x[2]); code.append((ARITH[x[0]], None))
        else:                                                 # a call: push the arguments, then CALL
            for a in x[1:]: expr(a)
            code.append(("CALL", (x[0], len(x) - 1)))
    expr(body); code.append(("RET", None))
    return code

def run(functions, entry, args):
    stack = list(args)
    frames = [(functions[entry], 0, 0)]                       # (code, instruction pointer, base of locals)
    executed, deepest = 0, 1
    code, ip, base = frames[-1]
    while True:
        op, arg = code[ip]; ip += 1; executed += 1
        if op == "CONST": stack.append(arg)
        elif op == "LOAD": stack.append(stack[base + arg])
        elif op in ("ADD", "SUB", "LESS"):
            b = stack.pop(); a = stack.pop()
            stack.append(a + b if op == "ADD" else a - b if op == "SUB" else a < b)
        elif op in ("ADD_K", "SUB_K", "LESS_K"):
            a = stack.pop()
            stack.append(a + arg if op == "ADD_K" else a - arg if op == "SUB_K" else a < arg)
        elif op == "JUMP": ip = arg
        elif op == "JUMP_IF_FALSE":
            if not stack.pop(): ip = arg
        elif op == "CALL":
            name, nargs = arg
            frames[-1] = (code, ip, base)                     # save where to come back to
            code, ip, base = functions[name], 0, len(stack) - nargs
            frames.append((code, ip, base)); deepest = max(deepest, len(frames))
        elif op == "RET":
            result = stack.pop(); del stack[base:]
            frames.pop()
            if not frames: return result, executed, deepest
            stack.append(result)
            code, ip, base = frames[-1]

