# A simulated heap. The program reaches objects only through `roots`, as compiled code reaches them
# through registers and stack slots, so the collector can move objects and fix the roots.
class Obj:
    def __init__(self, fields, young=True):
        self.fields, self.forward, self.young, self.dead = fields, None, young, False

def forwarded(fields):                                   # after a collection, follow forwarding pointers
    return [f.forward if isinstance(f, Obj) and f.forward else f for f in fields]

class Copying:
    """Cheney's semispace collector: copy everything reachable into an empty space, abandon the rest."""
    def __init__(self, capacity): self.cap, self.space, self.copied, self.gcs = capacity, [], 0, 0
    def alloc(self, fields, roots):
        if len(self.space) >= self.cap: self.collect(roots); fields = forwarded(fields)
        obj = Obj(fields); self.space.append(obj); return obj
    def write(self, obj, i, value): obj.fields[i] = value
    def collect(self, roots):
        self.gcs += 1; to = []
        def copy(o):
            if not isinstance(o, Obj): return o
            if o.forward is None:
                o.forward = Obj(list(o.fields)); to.append(o.forward); self.copied += 1
            return o.forward
        roots[:] = [copy(r) for r in roots]
        scan = 0
        while scan < len(to):                            # the to-space itself is the work queue
            to[scan].fields = [copy(f) for f in to[scan].fields]; scan += 1
        for o in self.space:
            if o.forward is None: o.dead = True
        self.space = to

class Generational:
    """A nursery for new objects; survivors are promoted to an old space that's rarely collected."""
    def __init__(self, nursery, barrier=True):
        self.cap, self.barrier, self.nursery, self.old = nursery, barrier, [], []
        self.remembered, self.copied, self.gcs = set(), 0, 0
    def alloc(self, fields, roots):
        if len(self.nursery) >= self.cap: self.minor(roots); fields = forwarded(fields)
        obj = Obj(fields); self.nursery.append(obj); return obj
    def write(self, obj, i, value):
        obj.fields[i] = value
        if self.barrier and not obj.young and isinstance(value, Obj) and value.young:
            self.remembered.add(obj)                     # the write barrier: an old -> young pointer
    def minor(self, roots):
        self.gcs += 1; queue = []
        def promote(o):
            if not (isinstance(o, Obj) and o.young): return o
            if o.forward is None:
                o.forward = Obj(list(o.fields), young=False); self.old.append(o.forward)
                queue.append(o.forward); self.copied += 1
            return o.forward
        roots[:] = [promote(r) for r in roots]
        for o in self.remembered: o.fields = [promote(f) for f in o.fields]   # extra roots
        while queue:
            o = queue.pop(); o.fields = [promote(f) for f in o.fields]
        for o in self.nursery:
            if o.forward is None: o.dead = True
        self.nursery, self.remembered = [], set()
    collect = minor

def workload(heap):
    roots = [None] * 11                                  # [0]: a long-lived list; [1:]: recent temporaries
    for k in range(2000):
        roots[0] = heap.alloc([k, roots[0], None], roots)
    for i in range(30000):
        t = heap.alloc([i, None], roots)
        roots[1 + i % 10] = t
        if i % 1000 == 0: heap.write(roots[0], 2, t)     # the old list's head points at a new object
    heap.collect(roots)                                  # one last collection, then check the heap
    dangling, seen, todo = 0, set(), [r for r in roots if r]
    while todo:
        o = todo.pop()
        if id(o) in seen: continue
        seen.add(id(o))
        for f in o.fields:
            if isinstance(f, Obj):
                if f.dead: dangling += 1
                else: todo.append(f)
    return len(seen), dangling

allocations = 32000
for name, heap in (("semispace copying, 6,000-object spaces", Copying(6000)),
                   ("generational, 1,000-object nursery", Generational(1000)),
                   ("generational, without the write barrier", Generational(1000, barrier=False))):
    live, dangling = workload(heap)
    print(f"{name}:")
    print(f"   {heap.gcs} collections, {heap.copied:,} objects copied, "
          f"{heap.copied / allocations:.2f} per allocation; {live:,} objects reachable at the end")
    if dangling:
        print(f"   BROKEN: a live object points at {dangling} freed object{'s' if dangling > 1 else ''}")

