    except RecursionError: print(f"total({n}): RecursionError, {n} frames for a loop in disguise")

# 2. A trampoline: return "what to call next" instead of calling it, and let a loop make the calls
def total_t(n, acc=0):
    return acc if n == 0 else (lambda: total_t(n - 1, acc + n))
def trampoline(result):
    bounces = 0
    while callable(result): result = result(); bounces += 1
    return result, bounces
