# 3. Tail-call elimination in an interpreter: evaluate a call in tail position by looping, not recursing
depth = max_depth = 0
def evaluate(x, env, tco):
    global depth, max_depth
    depth += 1; max_depth = max(max_depth, depth)
    try:
        while True:
            if isinstance(x, int): return x
            if isinstance(x, str): return env[x]
            if x[0] == "if":
                x = x[2] if evaluate(x[1], env, tco) else x[3]    # the chosen branch is in tail position
                continue
            if x[0] in ("+", "-", "="):
                a, b = evaluate(x[1], env, tco), evaluate(x[2], env, tco)
                return a + b if x[0] == "+" else a - b if x[0] == "-" else a == b
            params, body = env[x[0]]                               # a call to a user function
            args = [evaluate(a, env, tco) for a in x[1:]]
            new_env = {**env, **dict(zip(params, args))}
            if tco: x, env = body, new_env; continue               # reuse this Python frame
            return evaluate(body, new_env, tco)
    finally: depth -= 1
