# 4. Continuation-passing style: every call gets a function, k, that says what to do with its result
def fact_cps(n, k):
    return k(1) if n == 0 else fact_cps(n - 1, lambda v: k(n * v))
print(f"\nfactorial(10) in CPS = {fact_cps(10, lambda v: v)}")
def to_cps(x, k):
    """Rewrite (f (g a) (h b)) so every intermediate result is named and passed on explicitly."""
    counter = [0]
    def walk(x, k):
        if not isinstance(x, list): return k(x)
        def with_args(args, done):
            if not args: return done([])
            return walk(args[0], lambda a: with_args(args[1:], lambda rest: done([a] + rest)))
        def call(parts):
            counter[0] += 1; v = f"v{counter[0]}"
            return f"({' '.join(parts)} (lambda ({v}) {k(v)}))"
        return with_args(x, call)
    return walk(x, k)
