# 5. A generator is a function whose continuation is saved at each yield. Written out by hand:
def countdown(n):
    while n > 0:
        yield n
        n -= 1
    yield "liftoff"
class Countdown:                                           # the state machine a compiler makes of it
    def __init__(self, n): self.n, self.state = n, 0
    def __next__(self):
        if self.state == 0:
            if self.n > 0: self.state = 1; return self.n
            self.state = 2; return "liftoff"
        if self.state == 1:
            self.n -= 1; self.state = 0; return self.__next__()
        raise StopIteration
    def __iter__(self): return self
print(f"\ngenerator:     {list(countdown(3))}")
print(f"state machine: {list(Countdown(3))}")

import re

def read(src):
    tokens = re.findall(r"\(|\)|[^\s()]+", src)
    def form():
        t = tokens.pop(0)
        if t != "(": return int(t) if t.lstrip("-").isdigit() else t
        out = []
        while tokens[0] != ")": out.append(form())
        tokens.pop(0); return out
    return form()

