def fold(code):                                          # constant propagation and folding
    known, out = {}, []
    for dst, op, a, b in code:
        a, b = known.get(a, a), known.get(b, b)
        if op == "const" or (op != "copy" and isinstance(a, int) and isinstance(b, int)):
            v = a if op == "const" else a + b if op == "+" else a - b if op == "-" else a * b
            known[dst] = v; out.append((dst, "const", v, None))
        else: out.append((dst, op, a, b))
    return out
def simplify(code):                                      # algebra and strength reduction
    out = []
    for dst, op, a, b in code:
        if op == "*" and b == 1: out.append((dst, "copy", a, None))
        elif op == "*" and 0 in (a, b): out.append((dst, "const", 0, None))
        elif op == "+" and b == 0: out.append((dst, "copy", a, None))
        elif op == "+" and a == 0: out.append((dst, "copy", b, None))
        elif op == "-" and a == b: out.append((dst, "const", 0, None))
        elif op == "*" and b == 2: out.append((dst, "+", a, a))           # a multiply becomes an add
        else: out.append((dst, op, a, b))
    return out
