def run_loop(pre, body, n, a=6, b=7):
    env, muls = {"a": a, "b": b, "s": 0, "i": 0}, 0
    def step(ins):
        nonlocal muls
        dst, op, x, y = ins
        vx, vy = (env[v] if isinstance(v, str) else v for v in (x, y))
        muls += op == "*"
        env[dst] = vx + vy if op == "+" else vx * vy
    for ins in pre: step(ins)
    while env["i"] < n:
        for ins in body: step(ins)
    return env["s"], muls
