def intervals(code):
    """A value is live from the instruction that defines it to the last instruction that uses it."""
    start, end = {}, {}
    for n, (dst, op, *args) in enumerate(code):
        for a in args:
            if a in start: end[a] = n
        if dst: start[dst] = n; end.setdefault(dst, n)
    return {v: (start[v], end[v]) for v in start}
def interfere(iv):
    vs = sorted(iv)
    return {v: {w for w in vs if w != v and iv[v][0] < iv[w][1] and iv[w][0] < iv[v][1]} for v in vs}

def color(graph, k):
    """Chaitin's method: remove nodes with fewer than k neighbours; if none is left, pick one to spill."""
    g = {v: set(n) for v, n in graph.items()}
    stack, spilled = [], []
    while g:
        easy = [v for v in sorted(g) if len(g[v]) < k]
        v = easy[0] if easy else max(sorted(g), key=lambda v: len(g[v]))   # spill the most connected
        (stack if easy else spilled).append(v)
        for n in g.pop(v): g[n].discard(v)
    regs = {}
    for v in reversed(stack):                            # put them back, each taking a free register
        regs[v] = min(set(range(k)) - {regs[n] for n in graph[v] if n in regs})
    return regs, spilled

def spill(code, var):
    """Keep var in a stack slot: store it after its definition, reload it before each use."""
    out, n = [], 0
    for dst, op, *args in code:
        if var in args:
            n += 1; tmp = f"{var}{n}"
            out.append((tmp, "load", f"[{var}]")); args = [tmp if a == var else a for a in args]
        out.append((dst, op, *args))
        if dst == var: out.append((None, "store", var, f"[{var}]"))
    return out

