# Linear scan: walk the live ranges in order of start; when registers run out, spill the one that ends last
def linear_scan(iv, k):
    active, regs, spilled, free = [], {}, [], list(range(k))
    for v, (s, e) in sorted(iv.items(), key=lambda kv: kv[1][0]):
        for w in [w for w in active if iv[w][1] <= s]: active.remove(w); free.append(regs[w])
        if free: regs[v] = free.pop(0); active.append(v)
        else:
            victim = max(active + [v], key=lambda w: iv[w][1])
            spilled.append(victim)
            if victim != v: regs[v] = regs.pop(victim); active.remove(victim); active.append(v)
    return regs, spilled
