import time

# 1. Shapes (hidden classes): objects built the same way share one map from field name to slot
class Shape:
    def __init__(self, fields=()): self.fields, self.next = fields, {}
    def add(self, name):                                 # a transition: this shape plus one more field
        if name not in self.next: self.next[name] = Shape(self.fields + (name,))
        return self.next[name]
    def slot(self, name): return self.fields.index(name)
EMPTY = Shape()
class Obj:
    def __init__(self): self.shape, self.slots = EMPTY, []
    def set(self, name, value):
        if name in self.shape.fields: self.slots[self.shape.slot(name)] = value
        else: self.shape = self.shape.add(name); self.slots.append(value)

def point(x, y, order="xy"):
    o = Obj()
    for f in order: o.set(f, x if f == "x" else y)
    return o
