# 2. An inline cache: each property-access site remembers the shapes it has seen and their slots
class Site:
    def __init__(self, limit=4): self.cache, self.limit, self.hits, self.misses = {}, limit, 0, 0
    def get(self, obj, name):
        slot = self.cache.get(obj.shape)
        if slot is None:
            self.misses += 1; slot = obj.shape.slot(name)           # the slow, general lookup
            if len(self.cache) < self.limit: self.cache[obj.shape] = slot
        else: self.hits += 1
        return obj.slots[slot]
    def state(self):
        n = len(self.cache)
        return ("monomorphic" if n == 1 else f"polymorphic ({n} shapes)" if self.misses < 2 * self.limit
                else "megamorphic")

def shapes(k):                                           # k different field orders, each with an x
    names = ["x"] + [f"f{i}" for i in range(k - 1)]
    out = []
    for i in range(k):
        o = Obj(); o.set(f"f{i}" if i else "x", 0)
        for n in names:
            if n not in o.shape.fields: o.set(n, 0)
        o.set("x", i); out.append(o)
    return out
