# 3. A JIT for a bytecode loop. s = 0; i = 0; while i < n: s = s + xs[i] * 2; i = i + 1
LOOP = [("CONST", 0), ("STORE", "s"), ("CONST", 0), ("STORE", "i"),
        ("LOAD", "i"), ("LOAD", "n"), ("LESS", None), ("JUMP_IF_FALSE", 21),          # 4: the loop test
        ("LOAD", "s"), ("LOAD", "xs"), ("LOAD", "i"), ("INDEX", None), ("CONST", 2), ("MUL", None),
        ("ADD", None), ("STORE", "s"),
        ("LOAD", "i"), ("CONST", 1), ("ADD", None), ("STORE", "i"), ("JUMP", 4),     # 20: back to the test
        ("RETURN", "s")]
BINARY = {"ADD": "+", "MUL": "*", "LESS": "<"}

def jit(code, top, seen):
    """Translate the loop at `top` to Python by running its bytecode on a stack of expressions."""
    exit_ip = code[top + 3][1]                           # where JUMP_IF_FALSE leaves the loop
    names = sorted({arg for op, arg in code[top:exit_ip] if op == "LOAD"})
    stored = ", ".join(sorted({arg for op, arg in code[top:exit_ip] if op == "STORE"}))
    def translate(start, stop):
        stack, lines = [], []
        for op, arg in code[start:stop]:
            if op == "CONST": stack.append(repr(arg))
            elif op == "LOAD": stack.append(arg)
            elif op == "STORE": lines.append(f"{arg} = {stack.pop()}")
            elif op in BINARY: b = stack.pop(); stack.append(f"{stack.pop()} {BINARY[op]} {b}")
            elif op == "INDEX":                          # specialise on the element type seen so far
                index, seq = stack.pop(), stack.pop()
                lines += [f"v = {seq}[{index}]",
                          f"if type(v) is not {seen}: return {top + 4}, {stored}    # guard: deoptimise"]
                stack.append("v")
        return stack, lines
    (test,), _ = translate(top, top + 3)                 # the condition, as one expression
    _, body = translate(top + 4, exit_ip - 1)            # the body, up to the backward jump
    src = (f"def loop({', '.join(names)}):\n    while {test}:\n" + "".join(f"        {b}\n" for b in body)
           + f"    return {exit_ip}, {stored}\n")
    return src, names, stored.split(", ")

def vm(code, env, hot=None):
    """Interpret; if `hot` is set, compile a loop once its backward jump has run that many times."""
    env, stack, ip, executed, counts, compiled = dict(env), [], 0, 0, {}, None
    while True:
        op, arg = code[ip]; ip += 1; executed += 1
        if op == "CONST": stack.append(arg)
        elif op == "LOAD": stack.append(env[arg])
        elif op == "STORE": env[arg] = stack.pop()
        elif op == "INDEX": i = stack.pop(); stack.append(stack.pop()[i])
        elif op in BINARY:
            b = stack.pop(); a = stack.pop()
            stack.append(a + b if op == "ADD" else a * b if op == "MUL" else a < b)
        elif op == "JUMP_IF_FALSE":
            if not stack.pop(): ip = arg
        elif op == "RETURN": return env[arg], executed, compiled
        elif op == "JUMP":
            ip = arg; counts[ip] = counts.get(ip, 0) + 1
            if hot and counts[ip] == hot and compiled is None:
                compiled, names, stored = jit(code, ip, type(env["xs"][env["i"]]).__name__)
                ns = {}; exec(compiled, ns)
                ip, *values = ns["loop"](*(env[v] for v in names))       # run the machine code
                env.update(zip(stored, values))
                if ip == arg + 4:
                    bad = env["xs"][env["i"]]
                    print(f"   guard failed at element {env['i']:,} ({type(bad).__name__} {bad}): "
                          f"back to the interpreter at instruction {ip}")

n = 200_000
ints = list(range(n))
