from itertools import combinations

def closure(attrs, fds):
    """Everything the attributes determine, following dependencies until nothing changes."""
    result, changed = set(attrs), True
    while changed:
        changed = False
        for lhs, rhs in fds:
            if lhs <= result and not rhs <= result:
                result |= rhs; changed = True
    return result

def candidate_keys(attrs, fds):
    keys = []
    for size in range(1, len(attrs) + 1):
        for combo in combinations(sorted(attrs), size):
            c = set(combo)
            if closure(c, fds) == attrs and not any(k <= c for k in keys):
                keys.append(c)
    return keys

def bcnf_violations(attrs, fds):
    """A dependency whose left side is not a key means one fact is stored many times."""
    return [(lhs, rhs) for lhs, rhs in fds if closure(lhs, fds) != attrs]

# One wide table, as spreadsheets and first drafts love to do it.
