F = [({"order_id", "product_id"}, {"qty"}),
     ({"order_id"}, {"customer_id"}),
     ({"customer_id"}, {"customer_email"}),
     ({"product_id"}, {"product_name", "unit_price"})]

print("candidate keys:", [sorted(k) for k in candidate_keys(A, F)])
for lhs, rhs in bcnf_violations(A, F):
    print(f"  {', '.join(sorted(lhs)):11} -> {', '.join(sorted(rhs)):26} repeats on every row that shares {', '.join(sorted(lhs))}")
print("split each violation into its own table:")
for lhs, rhs in F:
    print(f"  table keyed by ({', '.join(sorted(lhs))}) holding {', '.join(sorted(rhs))}")

import sqlite3

class Connection:
    """Wraps a database connection: counts round trips and charges each one network latency."""
    def __init__(self, conn, rtt_ms=1.0):
        self.conn, self.rtt_ms, self.queries = conn, rtt_ms, 0
    def query(self, sql, params=()):
        self.queries += 1
        return self.conn.execute(sql, params).fetchall()
    def latency_ms(self):
        return self.queries * self.rtt_ms

raw = sqlite3.connect(":memory:")
raw.execute("CREATE TABLE author(id INTEGER PRIMARY KEY, name TEXT)")
raw.execute("CREATE TABLE book(id INTEGER PRIMARY KEY, author_id INTEGER, title TEXT)")
raw.execute("CREATE INDEX book_author ON book(author_id)")
for a in range(1, 101):
    raw.execute("INSERT INTO author VALUES (?, ?)", (a, f"Author {a}"))
    raw.executemany("INSERT INTO book(author_id, title) VALUES (?, ?)",
                    [(a, f"Book {a}.{i}") for i in range(3)])

class Author:
    """What a lazy-loading ORM gives you: an object whose books load on first access."""
    def __init__(self, conn, row):
        self._conn, (self.id, self.name), self._books = conn, row, None
    @property
    def books(self):
        if self._books is None:                   # looks like an attribute, is a query
            self._books = self._conn.query("SELECT title FROM book WHERE author_id = ?", (self.id,))
        return self._books

def page_lazy(c):        # the innocent-looking loop in a template
    authors = [Author(c, r) for r in c.query("SELECT id, name FROM author")]
    return {a.name: len(a.books) for a in authors}

def page_join(c):        # ask for exactly what the page shows, in one query
    return dict(c.query("""SELECT a.name, COUNT(b.id) FROM author a
                           LEFT JOIN book b ON b.author_id = a.id GROUP BY a.id"""))

def page_prefetch(c):    # the ORM's "eager loading": one query for parents, one for all children
    authors = c.query("SELECT id, name FROM author")
    ids = [a for a, _ in authors]
    books = c.query(f"SELECT author_id FROM book WHERE author_id IN ({','.join('?' * len(ids))})", ids)
    counts = {}
    for (author_id,) in books:
        counts[author_id] = counts.get(author_id, 0) + 1
    return {name: counts.get(i, 0) for i, name in authors}

results = []
for fn in (page_lazy, page_join, page_prefetch):
    c = Connection(raw, rtt_ms=1.0)
    results.append(fn(c))
    print(f"{fn.__name__:14} {c.queries:4} queries  ~{c.latency_ms():5.0f} ms of round trips at 1 ms each")
print("same page every time:", results[0] == results[1] == results[2])

import struct

PAGE_SIZE = 4096
HEADER = struct.Struct("<HH")    # number of slots, offset where the record area begins
SLOT = struct.Struct("<HH")      # record offset, record length (length 0 means deleted)

class SlottedPage:
    """A fixed-size page. The slot directory grows from the front, records grow from the back,
    and free space is the gap between them."""
    def __init__(self):
        self.buf = bytearray(PAGE_SIZE)
        HEADER.pack_into(self.buf, 0, 0, PAGE_SIZE)
    def _slot_at(self, s):
        return HEADER.size + s * SLOT.size
    def free_space(self):
        n, start = HEADER.unpack_from(self.buf, 0)
        return start - self._slot_at(n)
    def insert(self, record):
        n, start = HEADER.unpack_from(self.buf, 0)
        if len(record) + SLOT.size > self.free_space():
            return None                                    # full: the caller tries another page
        start -= len(record)
        self.buf[start:start + len(record)] = record
        SLOT.pack_into(self.buf, self._slot_at(n), start, len(record))
        HEADER.pack_into(self.buf, 0, n + 1, start)
        return n                                           # the record id is (page, slot)
    def read(self, s):
        off, length = SLOT.unpack_from(self.buf, self._slot_at(s))
        return None if length == 0 else bytes(self.buf[off:off + length])
    def delete(self, s):
        off, _ = SLOT.unpack_from(self.buf, self._slot_at(s))
        SLOT.pack_into(self.buf, self._slot_at(s), off, 0)  # the bytes stay until compaction
    def compact(self):
        n, _ = HEADER.unpack_from(self.buf, 0)
        live = [(s, self.read(s)) for s in range(n)]
        start = PAGE_SIZE
        for s, rec in live:
            if rec is not None:
                start -= len(rec)
                self.buf[start:start + len(rec)] = rec
                SLOT.pack_into(self.buf, self._slot_at(s), start, len(rec))
        HEADER.pack_into(self.buf, 0, n, start)            # slots keep their numbers

page = SlottedPage()
slots = []
while (s := page.insert(f"order {len(slots):04d} ".encode().ljust(100, b"."))) is not None:
    slots.append(s)
print(f"a {PAGE_SIZE}-byte page holds {len(slots)} records of 100 bytes; {page.free_space()} bytes left over")
before = page.read(1)
for s in slots[::2]:
    page.delete(s)
print("deleted every other record; free space before compaction:", page.free_space())
page.compact()
print("free space after compaction:", page.free_space())
print("record in slot 1 unchanged after compaction:", page.read(1) == before, "->", page.read(1)[:10])

import random
from collections import OrderedDict

class BufferPool:
    """Caches pages in memory. On a miss it 'reads from disk' and evicts the least recently used page.
    With a scan ring, large sequential scans reuse a few private buffers instead of the shared cache."""
    def __init__(self, capacity, scan_ring=0):
        self.capacity, self.cache, self.ring, self.ring_size = capacity, OrderedDict(), OrderedDict(), scan_ring
        self.disk_reads = 0
    def get(self, page_id, scan=False):
        if page_id in self.cache:
            self.cache.move_to_end(page_id)
            return
        self.disk_reads += 1
        if scan and self.ring_size:
            self.ring[page_id] = True
            if len(self.ring) > self.ring_size:
                self.ring.popitem(last=False)
            return
        self.cache[page_id] = True
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

random.seed(5)
hot = list(range(80))                       # an index and a few busy tables: the working set
for name, pool in (("plain LRU", BufferPool(100)), ("LRU + scan ring", BufferPool(100, scan_ring=8))):
    for _ in range(2000):
        pool.get(random.choice(hot))        # warm up: the hot pages settle into the cache
    for p in range(1000, 11000):
        pool.get(p, scan=True)              # someone runs a report that scans a 10,000-page table
    still = sum(p in pool.cache for p in hot)
    before = pool.disk_reads
    for _ in range(1000):
        pool.get(random.choice(hot))
    print(f"{name:16} hot pages still cached after the scan: {still:2}/80 | "
          f"disk reads for the next 1000 hot lookups: {pool.disk_reads - before}")

import bisect, hashlib, random

TOMBSTONE = "<deleted>"

class Bloom:
    """Answers 'definitely not here' or 'maybe here' using a few bits per key."""
    def __init__(self, keys, bits_per_key=10, k=7):
        self.m, self.k = max(64, len(keys) * bits_per_key), k
        self.bits = bytearray(self.m // 8 + 1)
        for key in keys:
            for h in self._hashes(key):
                self.bits[h // 8] |= 1 << (h % 8)
    def _hashes(self, key):
        d = hashlib.blake2b(str(key).encode(), digest_size=16).digest()
        a, b = int.from_bytes(d[:8], "little"), int.from_bytes(d[8:], "little")
        return [(a + i * b) % self.m for i in range(self.k)]
    def might_contain(self, key):
        return all(self.bits[h // 8] >> (h % 8) & 1 for h in self._hashes(key))

class SSTable:
    """A sorted run written once and never modified."""
    def __init__(self, items, bloom):
        self.keys, self.vals = [k for k, _ in items], [v for _, v in items]
        self.bloom = Bloom(self.keys) if bloom else None
    def find(self, key):
        i = bisect.bisect_left(self.keys, key)
        return (True, self.vals[i]) if i < len(self.keys) and self.keys[i] == key else (False, None)

class LSMTree:
    def __init__(self, memtable_size=100, compact_at=None, bloom=False):
        self.mem, self.runs = {}, []                       # runs: newest first
        self.memtable_size, self.compact_at, self.bloom = memtable_size, compact_at, bloom
        self.user_writes = self.disk_writes = self.probes = 0
    def put(self, key, value):
        self.user_writes += 1
        self.mem[key] = value                              # writes only ever touch memory...
        if len(self.mem) >= self.memtable_size:
            self._flush()
    def delete(self, key):
        self.put(key, TOMBSTONE)                           # ...even deletes, which are writes
    def _flush(self):
        items = sorted(self.mem.items())
        self.mem = {}
        self.runs.insert(0, SSTable(items, self.bloom))    # ...then go to disk as one sorted run
        self.disk_writes += len(items)
        if self.compact_at and len(self.runs) >= self.compact_at:
            self._compact()
    def _compact(self):
        merged = {}
        for run in reversed(self.runs):                    # oldest first, so newer values win
            merged.update(zip(run.keys, run.vals))
        items = [(k, v) for k, v in sorted(merged.items()) if v != TOMBSTONE]
        self.runs = [SSTable(items, self.bloom)]           # rewrite everything as one run
        self.disk_writes += len(items)
    def get(self, key):
        if key in self.mem:
            return None if self.mem[key] == TOMBSTONE else self.mem[key]
        for run in self.runs:
            if run.bloom and not run.bloom.might_contain(key):
                continue                                   # skipped without reading it
            self.probes += 1
            found, value = run.find(key)
            if found:
                return None if value == TOMBSTONE else value
        return None
    def stored(self):
        return sum(len(r.keys) for r in self.runs) + len(self.mem)

random.seed(7)
writes = [(random.randrange(5000), i) for i in range(20_000)]      # 5,000 keys, each updated ~4 times
