import bisect, functools, random

random.seed(3)
customers = [(cid, random.choice(["EU", "US", "APAC"])) for cid in range(1, 1001)]
orders = [(oid, random.randint(1, 1000), random.randint(100, 50_000)) for oid in range(1, 20_001)]

def nested_loop(outer, inner):
    """For every outer row, scan every inner row."""
    out, work = [], 0
    for o in outer:
        for c in inner:
            work += 1
            if o[1] == c[0]:
                out.append(o + c)
    return out, work

def index_nested_loop(outer, inner):
    """For every outer row, look the key up in a sorted index (a stand-in for a B-tree)."""
    keys = sorted(c[0] for c in inner)
    by_key = {c[0]: c for c in inner}
    out, work = [], 0
    for o in outer:
        lo, hi = 0, len(keys)
        while lo < hi:                                   # binary search, counting each step
            work += 1
            mid = (lo + hi) // 2
            if keys[mid] < o[1]: lo = mid + 1
            else: hi = mid
        if lo < len(keys) and keys[lo] == o[1]:
            out.append(o + by_key[o[1]])
    return out, work

def hash_join(probe, build):
    """Build a hash table on the smaller input, then stream the larger one past it."""
    table, work = {}, 0
    for c in build:
        work += 1
        table.setdefault(c[0], []).append(c)
    out = []
    for o in probe:
        work += 1
        for c in table.get(o[1], ()):
            out.append(o + c)
    return out, work

def merge_join(left, right):
    """Sort both inputs on the key, then walk them together once."""
    comparisons = 0
    def counted(key):
        def cmp(a, b):
            nonlocal comparisons
            comparisons += 1
            return (key(a) > key(b)) - (key(a) < key(b))
        return functools.cmp_to_key(cmp)
    L = sorted(left, key=counted(lambda o: o[1]))
    R = sorted(right, key=counted(lambda c: c[0]))
    out, i, j, steps = [], 0, 0, 0
    while i < len(L) and j < len(R):
        steps += 1
        if L[i][1] < R[j][0]: i += 1
        elif L[i][1] > R[j][0]: j += 1
        else:
            out.append(L[i] + R[j]); i += 1               # customer ids are unique on the right
    return out, comparisons + steps

results = {}
for name, fn in (("nested loop", nested_loop), ("index nested loop", index_nested_loop),
                 ("hash join", hash_join), ("sort-merge join", merge_join)):
