# The iterator model: each operator pulls rows from the one below, one at a time.
def scan(rows, stats):
    for r in rows:
        stats["read"] += 1
        yield r
def where(rows, predicate):
    return (r for r in rows if predicate(r))
def limit(rows, n):
    for i, r in enumerate(rows):
        if i == n:
            return
        yield r

