class Database:
    """A tiny multi-version store: every committed write adds a version stamped with a commit time."""
    def __init__(self, data):
        self.versions = {k: [(0, v)] for k, v in data.items()}
        self.clock = 0
    def value(self, key, as_of):
        return [v for ts, v in self.versions[key] if ts <= as_of][-1]
    def begin(self, level):
        return Transaction(self, level)

class Transaction:
    def __init__(self, db, level):
        self.db, self.level, self.start = db, level, db.clock
        self.reads, self.writes, self.status = set(), {}, "active"
    def read(self, key):
        self.reads.add(key)
        if key in self.writes:
            return self.writes[key]
        # read committed sees the latest commit; the other two levels read from their start snapshot
        return self.db.value(key, self.db.clock if self.level == "read committed" else self.start)
    def write(self, key, value):
        self.writes[key] = value
    def commit(self):
        changed = {k for k, vs in self.db.versions.items() if vs[-1][0] > self.start}
        if self.level != "read committed" and changed & set(self.writes):
            self.status = "aborted: someone else wrote that row first"
            return
        if self.level == "serializable" and self.writes and changed & self.reads:
            self.status = "aborted: data it read has changed"
            return
        self.db.clock += 1
        for k, v in self.writes.items():
            self.db.versions[k].append((self.db.clock, v))
        self.status = "committed"

def lost_update(level):
    db = Database({"counter": 0})
    a, b = db.begin(level), db.begin(level)
    x, y = a.read("counter"), b.read("counter")            # both read 0
    a.write("counter", x + 1); b.write("counter", y + 1)
    a.commit(); b.commit()
    if b.status == "committed":
        note = " (both committed: one increment lost)"
    else:
        note = f" (B {b.status}; it can retry)"
    return f"counter = {db.value('counter', db.clock)}{note}"

def write_skew(level):
    db = Database({"alice": 1, "bob": 1})                  # rule: at least one doctor on call
    a, b = db.begin(level), db.begin(level)
    if a.read("alice") + a.read("bob") >= 2: a.write("alice", 0)
    if b.read("alice") + b.read("bob") >= 2: b.write("bob", 0)
    a.commit(); b.commit()
    on_call = db.value("alice", db.clock) + db.value("bob", db.clock)
    note = " (both committed: the rule is broken)" if b.status == "committed" else f" (B {b.status})"
    return f"{on_call} doctor(s) on call{note}"

def non_repeatable(level):
    db = Database({"price": 100})
    t1 = db.begin(level)
    first = t1.read("price")
    t2 = db.begin(level); t2.write("price", 70); t2.commit()
    second = t1.read("price"); t1.commit()
    return f"T1 read {first}, then {second}"

for name, scenario in (("lost update: two increments", lost_update),
                       ("write skew: both go off call", write_skew),
                       ("non-repeatable read", non_repeatable)):
    print(name)
    for level in ("read committed", "snapshot", "serializable"):
        print(f"   {level:15} {scenario(level)}")

class Version:
    def __init__(self, value, xmin):
        self.value, self.xmin, self.xmax = value, xmin, None   # created by xmin, ended by xmax

class Store:
    """Row versions with PostgreSQL-style visibility: no reader ever waits for a writer."""
    def __init__(self):
        self.next_xid, self.active, self.committed, self.chain = 1, set(), set(), []
    def begin(self):
        xid = self.next_xid; self.next_xid += 1; self.active.add(xid)
        return xid, (xid, frozenset(self.active - {xid}))     # snapshot: my id, who was in flight
    def commit(self, xid):
        self.active.discard(xid); self.committed.add(xid)
    def _done_before(self, xid, snap):
        me, in_flight = snap
        return xid == me or (xid in self.committed and xid < me and xid not in in_flight)
    def read(self, snap):
        for v in self.chain:
            if self._done_before(v.xmin, snap) and not (v.xmax and self._done_before(v.xmax, snap)):
                return v.value
    def write(self, xid, value):
        for v in self.chain:
            if v.xmax is None:
                v.xmax = xid                                   # the old version is ended, not erased
        self.chain.append(Version(value, xid))
    def vacuum(self):
        oldest = min(self.active, default=self.next_xid)
        before = len(self.chain)
        self.chain = [v for v in self.chain if not (v.xmax in self.committed and v.xmax < oldest)]
        return before - len(self.chain)

s = Store()
t1, snap1 = s.begin(); s.write(t1, "balance 100"); s.commit(t1)
reader, rsnap = s.begin()                                      # a long report starts
writer, wsnap = s.begin(); s.write(writer, "balance 70")       # an update, not yet committed
print("writer sees its own change:     ", s.read(wsnap))
print("reader sees the committed value:", s.read(rsnap), "(and did not wait)")
s.commit(writer)
print("after the writer commits:")
print("   reader, same snapshot:        ", s.read(rsnap))
late, lsnap = s.begin()
print("   a transaction that starts now:", s.read(lsnap))
print("versions:", [(v.value, f"xmin={v.xmin}", f"xmax={v.xmax}") for v in s.chain])
print("vacuum while the report still runs removes", s.vacuum(), "versions")
s.commit(reader); s.commit(late)
print("vacuum after it finishes removes", s.vacuum(), "->", [v.value for v in s.chain])

# Deadlocks: who waits for whom, and a cycle means nobody can ever proceed.
class LockManager:
    def __init__(self):
        self.owner, self.waits_for = {}, {}
    def lock(self, txn, row):
        holder = self.owner.get(row)
        if holder in (None, txn):
            self.owner[row] = txn
            return f"T{txn} locks {row}"
        self.waits_for[txn] = holder
        cycle = self._cycle(txn)
        if cycle:
            victim = max(cycle)                                # abort the youngest transaction
            self.abort(victim)
            return f"T{txn} waits for T{holder} -> deadlock {' -> '.join(f'T{t}' for t in cycle + [cycle[0]])}; abort T{victim}"
        return f"T{txn} waits for T{holder} (holds {row})"
    def _cycle(self, start):
        path, t = [start], self.waits_for.get(start)
        while t is not None and t not in path:
            path.append(t); t = self.waits_for.get(t)
        return path if t == start else None
    def abort(self, txn):
        self.waits_for.pop(txn, None)
        for row, holder in list(self.owner.items()):
            if holder == txn:
                del self.owner[row]
        for t, h in list(self.waits_for.items()):              # waiters on the victim may now proceed
            if h == txn:
                del self.waits_for[t]

