class Primary:
    """Every change is a numbered log record (its LSN); replicas replay the same log."""
    def __init__(self):
        self.log, self.data = [], {}
    def write(self, key, value):
        self.log.append((key, value))
        self._apply(self.data, key, value)
        return len(self.log)                               # the LSN of this change
    @staticmethod
    def _apply(data, key, value):
        if value is None: data.pop(key, None)
        else: data[key] = value

class Replica:
    def __init__(self, primary):
        self.primary, self.applied, self.data = primary, 0, {}
    def catch_up(self, records=None):
        end = len(self.primary.log) if records is None else min(len(self.primary.log), self.applied + records)
        for key, value in self.primary.log[self.applied:end]:
            Primary._apply(self.data, key, value)
        self.applied = end

p = Primary(); r1, r2 = Replica(p), Replica(p)
for i in range(100):
    p.write(f"user{i}", f"name {i}")
r1.catch_up(); r2.catch_up()

print("1. read your own writes")
lsn = p.write("user7", "Ana Lima")                         # the user saves a new display name...
print("   read from a lagging replica:   ", r1.data["user7"], "<- the save looks lost")
def read(key, replica, token):
    """Serve from the replica only if it has replayed the client's last write."""
    return (replica.data[key], "replica") if replica.applied >= token else (p.data[key], "primary")
print("   with the client's LSN token:   ", read("user7", r1, lsn))

print("2. monotonic reads")
r1.catch_up()                                              # r1 is now current, r2 still lags
print(f"   first read from r1: {r1.data['user7']!r}, next read from r2: {r2.data['user7']!r} <- time went backwards")

print("3. failover with asynchronous replication")
for i in range(5):
    p.write(f"order{i}", "paid")                           # acknowledged to customers
r1.catch_up(records=2)                                     # then the primary's disk dies
lost = len(p.log) - r1.applied
print(f"   promoted replica is {lost} records behind: {lost} acknowledged orders are gone (RPO > 0)")
print("   synchronous replication would have made each commit wait for the replica: no loss, slower commits")

print("4. a replica is not a backup")
r1.catch_up(); r2.catch_up()
backup_lsn, backup = len(p.log), dict(p.data)              # last night's base backup
p.write("user42", "renamed")
bad = p.write("user7", None)                               # someone runs DELETE with the wrong WHERE
r1.catch_up()
print("   replica after the DELETE:      ", r1.data.get("user7"), "<- replicated faithfully")
restored = dict(backup)
for key, value in p.log[backup_lsn:bad - 1]:              # replay the archived log up to just before it
    Primary._apply(restored, key, value)
