def relational(sql, params):
    """Run the query, and describe its cost from SQLite's own plan."""
    plan = [r[-1] for r in db.execute("EXPLAIN QUERY PLAN " + sql, params)]
    searches = sum(line.startswith("SEARCH") for line in plan)
    scans = sum(line.startswith("SCAN") for line in plan)
    label = f"{searches} index search" + ("es" if searches > 1 else "") if not scans else f"{scans} table scan"
    return db.execute(sql, params).fetchall(), label

