import json


def with_idempotency(db, key: str, request_body: dict, handler):
    fingerprint = hashlib.sha256(
        json.dumps(request_body, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    try:
        db.execute(
            "INSERT INTO idempotency_keys (key, fingerprint, status) "
            "VALUES (%s, %s, 'started')", (key, fingerprint))
    except UniqueViolation:
        record = db.fetch_one(
            "SELECT fingerprint, status, response_code, response_body "
            "FROM idempotency_keys WHERE key = %s", (key,))
        if record.fingerprint != fingerprint:
            return 422, problem("idempotency-key-reused",
                                "This key was already used for a different request.")
        if record.status == "started":
            return 409, problem("request-in-progress",
                                "The original request is still being processed.")
        return record.response_code, json.loads(record.response_body)   # replay

    code, body = handler()
    db.execute(
        "UPDATE idempotency_keys SET status = 'done', response_code = %s, "
        "response_body = %s WHERE key = %s", (code, json.dumps(body), key))
    return code, body

