def can(user, action: str, invoice=None) -> bool:
    if invoice is not None and invoice.team_id != user.team_id:
        return False                                    # tenancy first, always
    if action not in ROLE_PERMISSIONS.get(user.role, set()):
        return False                                    # unknown roles get nothing
    if action == "invoice:write" and invoice is not None and invoice.status != "draft":
        return user.role in ("owner", "admin")          # sent invoices: admins only
    return True


