import hashlib


def in_rollout(flag: str, subject_id: str, percent: float) -> bool:
    """Stable per subject, independent between flags, and monotonic in percent."""
    digest = hashlib.sha256(f"{flag}:{subject_id}".encode()).digest()
    position = int.from_bytes(digest[:8], "big") / 2**64 * 100     # 0 <= position < 100
    return position < percent


