from enum import Enum


class Outcome(Enum):
    SUCCEEDED = "succeeded"
    FAILED = "failed"        # the server definitely refused: report it, or fix and retry
    UNKNOWN = "unknown"      # it may or may not have happened: find out, don't guess


def charge(client, request, timeout_s: float):
    try:
        response = client.post("/charges", json=request, timeout=timeout_s,
                               headers={"Idempotency-Key": request["idempotency_key"]})
    except (Timeout, ConnectionLost):
        return Outcome.UNKNOWN, None
    if response.status_code >= 500:
        return Outcome.UNKNOWN, None     # the server may have failed after committing
    if response.status_code >= 400:
        return Outcome.FAILED, response.json()
    return Outcome.SUCCEEDED, response.json()

class LamportClock:
    def __init__(self):
        self.time = 0

    def tick(self) -> int:
        """A local event, including sending a message."""
        self.time += 1
        return self.time

    def receive(self, sent_time: int) -> int:
        """Receiving a message stamped with the sender's clock."""
        self.time = max(self.time, sent_time) + 1
        return self.time

def increment(clock: dict[str, int], node: str) -> dict[str, int]:
    updated = dict(clock)
    updated[node] = updated.get(node, 0) + 1
    return updated


def merge(a: dict[str, int], b: dict[str, int]) -> dict[str, int]:
    return {n: max(a.get(n, 0), b.get(n, 0)) for n in a.keys() | b.keys()}


def compare(a: dict[str, int], b: dict[str, int]) -> str:
    nodes = a.keys() | b.keys()
    a_le_b = all(a.get(n, 0) <= b.get(n, 0) for n in nodes)
    b_le_a = all(b.get(n, 0) <= a.get(n, 0) for n in nodes)
    if a_le_b and b_le_a:
        return "equal"
    if a_le_b:
        return "before"
    if b_le_a:
        return "after"
    return "concurrent"          # a genuine conflict: keep both, and merge

