class GCounter:
    """A grow-only counter. Each replica increments only its own slot."""

    def __init__(self, replica_id: str):
        self.replica_id = replica_id
        self.counts: dict[str, int] = {}

    def increment(self, amount: int = 1) -> None:
        self.counts[self.replica_id] = self.counts.get(self.replica_id, 0) + amount

    def value(self) -> int:
        return sum(self.counts.values())

    def merge(self, other: "GCounter") -> None:
        for replica, count in other.counts.items():
            self.counts[replica] = max(self.counts.get(replica, 0), count)

import bisect
import hashlib


def _hash(value: str) -> int:
    return int.from_bytes(hashlib.sha256(value.encode()).digest()[:8], "big")


class HashRing:
    def __init__(self, nodes=(), vnodes: int = 100):
        self.vnodes = vnodes
        self._ring: list[tuple[int, str]] = []          # sorted (position, node) pairs
        for node in nodes:
            self.add(node)

    def add(self, node: str) -> None:
        for i in range(self.vnodes):
            bisect.insort(self._ring, (_hash(f"{node}#{i}"), node))

    def remove(self, node: str) -> None:
        self._ring = [(position, n) for position, n in self._ring if n != node]

    def node_for(self, key: str) -> str:
        index = bisect.bisect(self._ring, (_hash(key),))  # first point clockwise
        return self._ring[index % len(self._ring)][1]

def log_is_up_to_date(cand_last_term, cand_last_index, my_last_term, my_last_index):
    if cand_last_term != my_last_term:
        return cand_last_term > my_last_term      # a later term wins, whatever the length
    return cand_last_index >= my_last_index       # same term: the longer log wins


def handle_request_vote(state, req):
    if req.term < state.current_term:
        return VoteReply(term=state.current_term, granted=False)   # a stale candidate
    if req.term > state.current_term:
        state.current_term, state.voted_for = req.term, None       # a new term: step down
        state.role = "follower"
    already_voted = state.voted_for not in (None, req.candidate_id)
    if not already_voted and log_is_up_to_date(
            req.last_log_term, req.last_log_index,
            state.last_log_term(), state.last_log_index()):
        state.voted_for = req.candidate_id
        state.persist()                  # the vote must survive a crash before we reply
        state.reset_election_timer()
        return VoteReply(term=state.current_term, granted=True)
    return VoteReply(term=state.current_term, granted=False)

