from dataclasses import dataclass
from typing import Callable


@dataclass
class Step:
    name: str
    action: Callable[[dict], None]
    compensate: Callable[[dict], None]


def run_saga(steps: list[Step], context: dict) -> bool:
    completed: list[Step] = []
    for step in steps:
        try:
            step.action(context)
            completed.append(step)
        except PermanentFailure:
            for done in reversed(completed):
                done.compensate(context)     # must be idempotent, and retried until it works
            return False
    return True


