from collections import defaultdict


class TumblingCounter:
    """Counts events per window of event time, tolerating stragglers."""

    def __init__(self, window: int = 60, allowed_lateness: int = 30):
        self.window, self.lateness = window, allowed_lateness
        self.open = defaultdict(int)       # window start -> running count
        self.newest = 0                    # highest event time seen so far
        self.late = []                     # events that arrived after their window closed

    def watermark(self) -> int:
        return self.newest - self.lateness     # we expect nothing older than this

    def add(self, event_time: int) -> list[tuple[int, int]]:
        start = event_time - event_time % self.window
        if start + self.window <= self.watermark():
            self.late.append(event_time)       # its window has already been emitted
            return []
        self.open[start] += 1
        self.newest = max(self.newest, event_time)
        return self._emit_closed()

    def _emit_closed(self) -> list[tuple[int, int]]:
        closed = sorted(s for s in self.open if s + self.window <= self.watermark())
        return [(s, self.open.pop(s)) for s in closed]

import time


class CircuitOpen(Exception):
    pass


class CircuitBreaker:
    def __init__(self, failure_threshold=5, cooldown_s=30.0, clock=time.monotonic):
        self.failure_threshold, self.cooldown_s, self.clock = failure_threshold, cooldown_s, clock
        self.failures = 0
        self.opened_at = None                       # None means the circuit is closed

    def call(self, fn, *args, **kwargs):
        if self.opened_at is not None and self.clock() - self.opened_at < self.cooldown_s:
            raise CircuitOpen()                     # fail fast; don't pile on
        # Closed, or cooling down is over (half-open): let this call through.
        # A production breaker admits one probe at a time while half-open.
        try:
            result = fn(*args, **kwargs)
        except Exception:
            self.failures += 1
            if self.opened_at is not None or self.failures >= self.failure_threshold:
                self.opened_at = self.clock()       # trip, or re-trip after a failed probe
            raise
        self.failures, self.opened_at = 0, None     # success closes the circuit
        return result

import random


def max_load(servers: int, requests: int, choose, rng) -> int:
    load = [0] * servers
    for _ in range(requests):
        load[choose(load, rng)] += 1
    return max(load)


def pick_random(load, rng):
    return rng.randrange(len(load))


def pick_two(load, rng):
    a, b = rng.randrange(len(load)), rng.randrange(len(load))
    return a if load[a] <= load[b] else b


rng = random.Random(1)
max_load(100, 10_000, pick_random, rng)   # typically 120 to 135: some servers 30% over the mean
max_load(100, 10_000, pick_two, rng)      # typically 101 or 102: almost perfectly even

