import ast
import pathlib
import sys

# Each package under app/ is a module. This lists which others each may use.
ALLOWED = {
    "billing": {"customers"},
    "customers": set(),
    "notifications": {"billing", "customers"},
}


def imports(path: pathlib.Path):
    tree = ast.parse(path.read_text(), filename=str(path))
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                yield alias.name, node.lineno
        elif isinstance(node, ast.ImportFrom) and node.module and node.level == 0:
            for alias in node.names:
                yield f"{node.module}.{alias.name}", node.lineno


def violations(root: pathlib.Path):
    for path in sorted(root.rglob("*.py")):
        rel = path.relative_to(root).parts
        if len(rel) < 2:
            continue
        owner = rel[0]
        for name, line in imports(path):
            parts = name.split(".")
            if parts[0] != root.name or len(parts) < 2 or parts[1] == owner:
                continue
            target = parts[1]
            if target not in ALLOWED.get(owner, set()):
                yield f"{path}:{line}: {owner} may not depend on {target}"
            elif len(parts) > 2 and parts[2] != "api":
                yield f"{path}:{line}: {owner} imports {name}; use {target}.api"


if __name__ == "__main__":
    found = list(violations(pathlib.Path("app")))
    print("\n".join(found) or "module boundaries respected")
    sys.exit(1 if found else 0)

