from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class Money:                              # value object: immutable, equal by value
    amount: Decimal
    currency: str

    def __add__(self, other: "Money") -> "Money":
        if other.currency != self.currency:
            raise ValueError("cannot add different currencies")
        return Money(self.amount + other.amount, self.currency)

    def times(self, n: int) -> "Money":
        return Money(self.amount * n, self.currency)


@dataclass(frozen=True)
class OrderPlaced:                        # domain event, named in the past tense
    order_id: str
    total: Money


class Order:                              # aggregate root: every change goes through it
    MAX_LINES = 50

    def __init__(self, order_id: str, currency: str):
        self.id, self.currency = order_id, currency
        self.lines: list[tuple[str, int, Money]] = []
        self.status = "draft"
        self.events: list[OrderPlaced] = []

    def add_line(self, sku: str, qty: int, unit_price: Money) -> None:
        if self.status != "draft":
            raise ValueError("order can no longer be changed")
        if qty <= 0 or len(self.lines) >= self.MAX_LINES:
            raise ValueError("invalid line")
        self.lines.append((sku, qty, unit_price))

    def total(self) -> Money:
        total = Money(Decimal("0"), self.currency)
        for _, qty, price in self.lines:
            total = total + price.times(qty)
        return total

    def place(self) -> None:
        if self.status != "draft" or not self.lines:
            raise ValueError("only a draft with lines can be placed")
        self.status = "placed"
        self.events.append(OrderPlaced(self.id, self.total()))

# The repository saves the order and its new events in one transaction (the outbox of
# chapter 10). Payment and stock are separate aggregates, which react to OrderPlaced.

import random
import time

import requests


def send_with_retry(url, payload):
    for attempt in range(5):
        try:
            return requests.post(url, json=payload, timeout=2)
        except requests.RequestException:
            time.sleep(min(30, 2 ** attempt) * random.random())
    raise RuntimeError("gave up")

def send_with_retry(url, payload, post=requests.post, sleep=time.sleep,
                    rand=random.random, attempts=5):
    for attempt in range(attempts):
        try:
            return post(url, json=payload, timeout=2)
        except OSError:                  # requests' exceptions are OSErrors too
            if attempt == attempts - 1:
                raise
            sleep(min(30, 2 ** attempt) * rand())


def test_gives_up_after_five_attempts():
    calls, sleeps = [], []

    def failing_post(url, **kwargs):
        calls.append(url)
        raise ConnectionError("down")

    with pytest.raises(ConnectionError):
        send_with_retry("https://example.test", {}, post=failing_post,
                        sleep=sleeps.append, rand=lambda: 1.0)
    assert len(calls) == 5
    assert sleeps == [1, 2, 4, 8]

def closed_loop(port, seconds):
    lat, end = [], time.monotonic() + seconds
    while time.monotonic() < end:
        t0 = time.monotonic(); one_request(port); lat.append(time.monotonic() - t0)
    return lat


def open_loop(port, seconds, rate):
    lat, lock, threads = [], threading.Lock(), []
    start = time.monotonic()
    def fire(intended):
        try:
            one_request(port)
        except Exception:
            return
        with lock:
            lat.append(time.monotonic() - intended)     # measured from when it SHOULD have been sent
    for i in range(int(seconds * rate)):
        intended = start + i / rate
        delay = intended - time.monotonic()
        if delay > 0:
            time.sleep(delay)
        t = threading.Thread(target=fire, args=(intended,), daemon=True)
        t.start(); threads.append(t)
    for t in threads:
        t.join(timeout=10)
    return lat

