import re
import sys

SECRETISH = re.compile(r"(SECRET|TOKEN|PASSWORD|PASSWD|API_?KEY)\s*=", re.I)


def instructions(text):
    """(line number, instruction, argument), with continuations joined."""
    out, buf, start = [], "", 0
    for n, raw in enumerate(text.splitlines(), 1):
        line = raw.split("#")[0].rstrip() if not raw.lstrip().startswith("#") else ""
        if not line.strip():
            continue
        if not buf:
            start = n
        buf += line.rstrip("\\")
        if line.endswith("\\"):
            continue
        verb, _, arg = buf.strip().partition(" ")
        out.append((start, verb.upper(), arg.strip()))
        buf = ""
    return out


def check(text):
    ins = instructions(text)
    froms = [(n, a) for n, v, a in ins if v == "FROM"]
    last_from = froms[-1][0] if froms else 0
    problems = []
    for n, image in froms:
        if "@sha256:" not in image:
            problems.append(f"{n}: pin the base image by digest, not by tag: {image.split()[0]}")
    users = [a for n, v, a in ins if v == "USER" and n > last_from]
    if not users or users[-1] in ("root", "0"):
        problems.append(f"{last_from}: the final stage runs as root; add a USER")
    for n, v, a in ins:
        if v in ("ENTRYPOINT", "CMD") and not a.startswith("["):
            problems.append(f"{n}: use the exec form of {v} so the process receives SIGTERM")
        if v == "ADD" and not a.startswith(("http://", "https://")):
            problems.append(f"{n}: use COPY unless you need ADD's URL or archive handling")
        if v in ("ENV", "ARG") and SECRETISH.search(a):
            problems.append(f"{n}: secrets do not belong in an image layer")
        if v == "RUN" and "apt-get install" in a and "rm -rf /var/lib/apt/lists" not in a:
            problems.append(f"{n}: clean the package lists in the same RUN, or they stay in the layer")
    copies = [n for n, v, a in ins if v == "COPY" and a.split()[0] in (".", "./")]
    installs = [n for n, v, a in ins if v == "RUN" and re.search(r"\b(pip|npm|poetry|uv|go mod|bundle)\b", a)]
    if copies and installs and min(copies) < max(installs):
        problems.append(f"{min(copies)}: copy dependency manifests before the source, or every "
                        "code change rebuilds the dependency layer")
    return problems


if __name__ == "__main__":
    found = [p for path in sys.argv[1:] for p in check(open(path).read())]
    print("\n".join(found) or "Dockerfile looks fine")
    sys.exit(1 if found else 0)

import os
from dataclasses import MISSING, dataclass, fields


class ConfigError(Exception):
    """Raised once, listing everything that is wrong."""


def _parse(kind, raw):
    if kind is bool:
        if raw.lower() not in ("true", "false", "1", "0"):
            raise ValueError("expected true or false")
        return raw.lower() in ("true", "1")
    return kind(raw)


@dataclass(frozen=True)
class Config:
    database_url: str                        # no default: it must be supplied
    port: int = 8080
    workers: int = 4
    request_timeout_s: float = 5.0
    new_pdf_renderer: bool = False

    def redacted(self) -> dict:
        out = {}
        for f in fields(self):
            value = getattr(self, f.name)
            out[f.name] = "***" if any(w in f.name for w in ("url", "password", "token", "key")) else value
        return out


CHECKS = {
    "port": (lambda v: 1 <= v <= 65535, "must be between 1 and 65535"),
    "workers": (lambda v: v >= 1, "must be at least 1"),
    "request_timeout_s": (lambda v: v > 0, "must be positive"),
}


def load(env=None) -> Config:
    """Read the whole configuration, then report every problem at once and stop."""
    env = os.environ if env is None else env
    values, problems = {}, []
    for f in fields(Config):
        raw = env.get(f.name.upper())
        if raw is None or raw == "":
            if f.default is MISSING:
                problems.append(f"{f.name.upper()} is required")
            continue
        try:
            value = _parse(f.type, raw)
        except ValueError as exc:
            problems.append(f"{f.name.upper()}={raw!r}: {exc}")
            continue
        ok, why = CHECKS.get(f.name, (lambda v: True, ""))
        if not ok(value):
            problems.append(f"{f.name.upper()}={value}: {why}")
            continue
        values[f.name] = value
    if problems:
        raise ConfigError("bad configuration:\n  " + "\n  ".join(problems))
    return Config(**values)

