class JsonFormatter(logging.Formatter):
    def format(self, record):
        event = {
            "ts": time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(record.created)) + ".%03dZ" % (record.msecs),
            "level": record.levelname.lower(),
            "logger": record.name,
            "message": record.getMessage(),
        }
        event.update(context.get())
        event.update(getattr(record, "fields", {}))
        if record.exc_info:
            event["error_type"] = record.exc_info[0].__name__
            event["stack"] = self.formatException(record.exc_info)
        return json.dumps({k: _redact(k, v) for k, v in event.items()}, default=str)


