import logging

log = logging.getLogger(__name__)


class PolicyUnavailable(Exception):
    pass


# Fails open: an outage of the policy service grants everything to everyone.
def can_fail_open(policy, user_id, action, resource_id) -> bool:
    try:
        return policy.check(user_id, action, resource_id)
    except Exception:
        return True                     # "don't block users during an outage"


# Fails closed: only an explicit, successful yes allows the action.
def can(policy, user_id, action, resource_id) -> bool:
    try:
        decision = policy.check(user_id, action, resource_id)
    except PolicyUnavailable:
        log.warning("policy check unavailable; denying %s on %s", action, resource_id)
        return False
    return decision is True             # None, "yes" or 1 all mean deny

