from urllib.parse import urlsplit

SAFE_METHODS = {"GET", "HEAD", "OPTIONS"}


def allow_request(method: str, headers: dict[str, str], host: str) -> bool:
    """Reject cross-origin state-changing requests, like Go's http.CrossOriginProtection."""
    if method in SAFE_METHODS:
        return True                     # these must never change state anyway
    site = headers.get("Sec-Fetch-Site")
    if site is not None:
        return site in ("same-origin", "none")   # "none": typed URL or bookmark
    origin = headers.get("Origin")
    if origin is None:
        return True                     # not a browser request, so no ambient cookies
    return urlsplit(origin).netloc == host       # older browsers: compare Origin with Host

