        response.headers["Access-Control-Allow-Credentials"] = "true"

import ipaddress
import socket
from urllib.parse import urlsplit

ALLOWED_SCHEMES = {"http": 80, "https": 443}


def is_public(ip) -> bool:
    if ip.version == 6 and ip.ipv4_mapped:      # ::ffff:169.254.169.254 is still IPv4 inside
        ip = ip.ipv4_mapped
    return ip.is_global and not ip.is_multicast


def resolve_public(url: str) -> tuple[str, str, int]:
    """Check a URL a user gave us. Returns (host, ip, port): connect to `ip`, sending `host`."""
    parts = urlsplit(url)
    if parts.scheme not in ALLOWED_SCHEMES or not parts.hostname:
        raise ValueError("only http and https URLs with a host are allowed")
    if parts.username is not None or parts.password is not None:
        raise ValueError("credentials in URLs are not allowed")
    port = parts.port or ALLOWED_SCHEMES[parts.scheme]
    if port not in ALLOWED_SCHEMES.values():
        raise ValueError(f"port {port} is not allowed")
    try:
        infos = socket.getaddrinfo(parts.hostname, port, type=socket.SOCK_STREAM)
    except socket.gaierror:
        raise ValueError(f"cannot resolve {parts.hostname}") from None
    ips = {ipaddress.ip_address(info[4][0]) for info in infos}
    if not all(is_public(ip) for ip in ips):
        raise ValueError(f"{parts.hostname} resolves to a non-public address")
    ip = min(ips, key=lambda a: (a.version, int(a)))
    return parts.hostname, str(ip), port

