# Relationship tuples: (object, relation, subject).
# A subject is a user, or a set of users such as "group:finance#member".
TUPLES = {
    ("folder:acme-2026", "viewer", "group:finance#member"),
    ("folder:acme-2026", "editor", "user:maya"),
    ("doc:inv-1042", "parent", "folder:acme-2026"),
    ("doc:inv-1042", "owner", "user:sam"),
    ("group:finance", "member", "user:lee"),
}

IMPLIED = {"editor": ["owner"], "viewer": ["editor"]}    # owners can edit; editors can view
INHERITED = {"viewer": "parent", "editor": "parent"}     # rights on a folder apply to its docs


def check(obj: str, relation: str, user: str, depth: int = 0) -> bool:
    if depth > 10:                                       # guards against cycles in the data
        return False
    for o, r, subject in TUPLES:
        if (o, r) != (obj, relation):
            continue
        if subject == user:
            return True
        if "#" in subject:                               # expand a set: group:finance#member
            set_obj, set_rel = subject.split("#")
            if check(set_obj, set_rel, user, depth + 1):
                return True
    if any(check(obj, stronger, user, depth + 1) for stronger in IMPLIED.get(relation, [])):
        return True
    via = INHERITED.get(relation)
    return via is not None and any(
        check(parent, relation, user, depth + 1)
        for o, r, parent in TUPLES if (o, r) == (obj, via))


