check("doc:inv-1042", "editor", "user:lee")    # False
check("doc:inv-1042", "editor", "user:maya")   # True: Maya can edit the parent folder
check("doc:inv-1042", "viewer", "user:sam")    # True: owner implies editor implies viewer

