package main

import (
	"crypto/hpke"
	"fmt"
	"log"
)

func main() {
	// The recipient's key pair: post-quantum ML-KEM-768 combined with classical X25519.
	kem := hpke.MLKEM768X25519()
	recipient, err := kem.GenerateKey()
	if err != nil {
		log.Fatal(err)
	}

	// A sender needs only the public key. "info" binds the ciphertext to its purpose.
	info := []byte("acme invoices: bank details v1")
	sealed, err := hpke.Seal(recipient.PublicKey(), hpke.HKDFSHA256(), hpke.AES256GCM(), info,
		[]byte("account 12345678, sort code 00-00-00"))
	if err != nil {
		log.Fatal(err)
	}

	plain, err := hpke.Open(recipient, hpke.HKDFSHA256(), hpke.AES256GCM(), info, sealed)
	fmt.Printf("sealed: %d bytes; opened: %q, error: %v\n", len(sealed), plain, err)

	sealed[len(sealed)-1] ^= 1 // flip a single bit
	_, err = hpke.Open(recipient, hpke.HKDFSHA256(), hpke.AES256GCM(), info, sealed)
	fmt.Println("after tampering:", err)
}

import base64
import hashlib
import hmac
import json
import time


def _b64url(part: str) -> bytes:
    return base64.urlsafe_b64decode(part + "=" * (-len(part) % 4))


def verify_jwt(token: str, key: bytes, *, issuer: str, audience: str, leeway: int = 30) -> dict:
    """Verify an HS256 JWT. Raises ValueError unless every check passes."""
    try:
        header_b64, claims_b64, signature_b64 = token.split(".")
        header = json.loads(_b64url(header_b64))
    except ValueError:
        raise ValueError("malformed token") from None
    if header.get("alg") != "HS256":           # the server decides the algorithm, not the token
        raise ValueError("unexpected algorithm")
    expected = hmac.new(key, f"{header_b64}.{claims_b64}".encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, _b64url(signature_b64)):
        raise ValueError("bad signature")       # nothing in the claims is trusted before this
    claims = json.loads(_b64url(claims_b64))
    now = time.time()
    if claims.get("iss") != issuer:
        raise ValueError("wrong issuer")
    audiences = claims.get("aud")
    if audience != audiences and not (isinstance(audiences, list) and audience in audiences):
        raise ValueError("wrong audience")
    if not isinstance(claims.get("exp"), (int, float)) or now > claims["exp"] + leeway:
        raise ValueError("missing or past expiry")
    if isinstance(claims.get("nbf"), (int, float)) and now < claims["nbf"] - leeway:
        raise ValueError("not valid yet")
    return claims

package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"fmt"
)

// aead returns AES-256-GCM that chooses a random nonce itself and stores it with the ciphertext.
func aead(key []byte) cipher.AEAD {
	block, err := aes.NewCipher(key)
	if err != nil {
		panic(err)
	}
	gcm, err := cipher.NewGCMWithRandomNonce(block)
	if err != nil {
		panic(err)
	}
	return gcm
}

func newKey() []byte {
	key := make([]byte, 32)
	rand.Read(key)
	return key
}

// KMS stands in for a cloud key management service. Its key-encryption key never leaves it.
type KMS struct{ kek []byte }

func (k *KMS) Wrap(dek []byte) []byte { return aead(k.kek).Seal(nil, nil, dek, nil) }

func (k *KMS) Unwrap(wrapped []byte) ([]byte, error) { return aead(k.kek).Open(nil, nil, wrapped, nil) }

// Record is what the database stores: the wrapped data key beside the data it encrypted.
type Record struct{ WrappedKey, Ciphertext []byte }

func Encrypt(kms *KMS, plaintext, recordID []byte) Record {
	dek := newKey() // a fresh data key for every record, discarded after use
	return Record{
		WrappedKey: kms.Wrap(dek),
		Ciphertext: aead(dek).Seal(nil, nil, plaintext, recordID), // recordID binds it to its row
	}
}

func Decrypt(kms *KMS, r Record, recordID []byte) ([]byte, error) {
	dek, err := kms.Unwrap(r.WrappedKey)
	if err != nil {
		return nil, err
	}
	return aead(dek).Open(nil, nil, r.Ciphertext, recordID)
}

func main() {
	oldKMS := &KMS{kek: newKey()}
	rec := Encrypt(oldKMS, []byte("bank account 12345678"), []byte("customer:42"))

	// Rotating the KMS key re-wraps 32 bytes per record; the data itself is untouched.
	newKMS := &KMS{kek: newKey()}
	dek, _ := oldKMS.Unwrap(rec.WrappedKey)
	rec.WrappedKey = newKMS.Wrap(dek)

	plain, err := Decrypt(newKMS, rec, []byte("customer:42"))
	fmt.Printf("%q %v\n", plain, err)

	_, err = Decrypt(newKMS, rec, []byte("customer:43")) // the ciphertext copied into another row
	fmt.Println("in another row:", err)

	_, err = Decrypt(oldKMS, rec, []byte("customer:42")) // the retired key no longer works
	fmt.Println("with the old key:", err)
}

import hashlib


def leaf_hash(entry: bytes) -> bytes:
    return hashlib.sha256(b"\x00" + entry).digest()      # prefixes keep leaves and nodes distinct


def node_hash(left: bytes, right: bytes) -> bytes:
    return hashlib.sha256(b"\x01" + left + right).digest()


def root(entries: list[bytes]) -> bytes:
    if len(entries) == 1:
        return leaf_hash(entries[0])
    k = 1 << ((len(entries) - 1).bit_length() - 1)      # largest power of two below the size
    return node_hash(root(entries[:k]), root(entries[k:]))


def verify_inclusion(index: int, size: int, entry: bytes, proof: list[bytes], signed_root: bytes) -> bool:
    """RFC 9162, section 2.1.3.2: is `entry` at position `index` in the tree with this root?"""
    if index >= size:
        return False
    fn, sn, r = index, size - 1, leaf_hash(entry)
    for p in proof:
        if sn == 0:
            return False
        if fn & 1 or fn == sn:
            r = node_hash(p, r)
            while not fn & 1 and fn != 0:
                fn, sn = fn >> 1, sn >> 1
        else:
            r = node_hash(r, p)
        fn, sn = fn >> 1, sn >> 1
    return sn == 0 and r == signed_root

import math
import re
from collections import Counter

PATTERNS = {
    "AWS access key ID": re.compile(r"\b(?:AKIA|ASIA)[0-9A-Z]{16}\b"),
    "GitHub token": re.compile(r"\b(?:gh[pousr]_[A-Za-z0-9]{36,}|github_pat_\w{60,})\b"),
    "Stripe live key": re.compile(r"\b[rs]k_live_[A-Za-z0-9]{24,}\b"),
    "Private key": re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
}
ASSIGNED = re.compile(r"""(?i)(?:secret|token|passw(?:or)?d|api_?key)\w*["']?\s*[:=]\s*["']([^"'\s]{20,})["']""")
HEX = set("0123456789abcdefABCDEF")


def entropy(value: str) -> float:
    """Shannon entropy in bits per character: random keys score high, words score low."""
    counts = Counter(value)
    return -sum(n / len(value) * math.log2(n / len(value)) for n in counts.values())


def looks_random(value: str) -> bool:
    return entropy(value) > (3.0 if set(value) <= HEX else 4.0)


def scan(text: str, path: str):
    for lineno, line in enumerate(text.splitlines(), 1):
        for name, pattern in PATTERNS.items():
            if pattern.search(line):
                yield f"{path}:{lineno}: {name}"
        for match in ASSIGNED.finditer(line):
            if looks_random(match.group(1)):
                yield f"{path}:{lineno}: random-looking value assigned to a secret-like name"

