from fnmatch import fnmatchcase


def _list(value):
    return value if isinstance(value, list) else [value]


def matches(statement: dict, request: dict) -> bool:
    if not any(fnmatchcase(request["action"].lower(), a.lower()) for a in _list(statement["Action"])):
        return False
    if not any(fnmatchcase(request["resource"], r) for r in _list(statement["Resource"])):
        return False
    for _operator, conditions in statement.get("Condition", {}).items():   # StringEquals, Bool
        for key, expected in conditions.items():
            if request["context"].get(key) not in _list(expected):
                return False
    return True


def decide(request: dict, policies: list[dict], guardrails: list[dict] | None = None) -> str:
    hits = [s for policy in policies for s in policy["Statement"] if matches(s, request)]
    if any(s["Effect"] == "Deny" for s in hits):
        return "explicit deny"
    if not any(s["Effect"] == "Allow" for s in hits):
        return "implicit deny"
    if guardrails is not None and decide(request, guardrails) != "allow":
        return "denied by guardrail"
    return "allow"


