# A tiny coverage-guided-style search: find inputs that reach a buggy branch in a parser.
def parse_version(s: str) -> tuple[int, int, int]:
    """Parse "MAJOR.MINOR.PATCH". Contains a deliberate bug for the fuzzer to find."""
    parts = s.split(".")
    if len(parts) != 3:
        raise ValueError("need three parts")
    major, minor, patch = (int(p) for p in parts)   # int() raises on non-digits
    if major == 2 and minor == 26:
        return (major, minor, patch - 1)            # bug: underflows to -1 when patch == 0
    return (major, minor, patch)


def check(s: str) -> str | None:
    """A property: the patch number is never negative. Return a crash description or None."""
    try:
        result = parse_version(s)
    except (ValueError, Exception) as e:
        return None                                  # rejecting bad input is fine, not a crash
    if result[2] < 0:
        return f"property violated: {s!r} -> {result}"
    return None


if __name__ == "__main__":
    import random
    rng = random.Random(0)
    alphabet = "0123456789."
    corpus = ["1.0.0", "2.26.3"]                     # seeds
    findings = []
    for _ in range(200_000):
        base = rng.choice(corpus)
        chars = list(base)
        for _ in range(rng.randint(1, 3)):           # mutate: flip, insert or delete a character
            op = rng.randint(0, 2)
            i = rng.randrange(len(chars) + 1)
            if op == 0 and chars:
                chars[rng.randrange(len(chars))] = rng.choice(alphabet)
            elif op == 1:
                chars.insert(i, rng.choice(alphabet))
            elif op == 2 and chars:
                del chars[rng.randrange(len(chars))]
        candidate = "".join(chars)
        bug = check(candidate)
        if bug:
            findings.append(candidate)
            if candidate not in corpus and len(corpus) < 50:
                corpus.append(candidate)             # keep interesting inputs, as real fuzzers do
    uniq = sorted(set(findings), key=len)
    print("inputs tried: 200000, crashing inputs found:", len(findings))
    print("smallest crashing input:", uniq[0] if uniq else None, "->", parse_version(uniq[0]))

from dataclasses import dataclass


@dataclass
class Finding:
    id: str
    cvss: float          # 0-10 severity
    epss: float          # 0-1 probability of exploitation in the next 30 days
    in_kev: bool         # listed as exploited in the wild by CISA
    internet_facing: bool
    reachable: bool      # is the vulnerable code actually called?


def priority(f: Finding) -> tuple:
    # Sort key, highest first: known-exploited and reachable on an exposed service dominates.
    exposure = f.internet_facing and f.reachable
    return (f.in_kev and exposure, f.in_kev, exposure, round(f.epss, 2), f.cvss)


def order(findings: list[Finding]) -> list[Finding]:
    return sorted(findings, key=priority, reverse=True)


findings = [
    Finding("CVE-A", cvss=9.8, epss=0.02, in_kev=False, internet_facing=False, reachable=False),
    Finding("CVE-B", cvss=6.5, epss=0.80, in_kev=True, internet_facing=True, reachable=True),
    Finding("CVE-C", cvss=7.5, epss=0.10, in_kev=False, internet_facing=True, reachable=True),
    Finding("CVE-D", cvss=9.1, epss=0.90, in_kev=True, internet_facing=False, reachable=True),
]
[f.id for f in order(findings)]      # ['CVE-B', 'CVE-D', 'CVE-C', 'CVE-A']

from collections import Counter


def train_bpe(words, num_merges):
    """A toy byte-pair encoding: repeatedly merge the most frequent adjacent symbol pair."""
    vocab = {" ".join(list(w)) + " </w>": c for w, c in Counter(words).items()}
    merges = []
    for _ in range(num_merges):
        pairs = Counter()
        for word, freq in vocab.items():
            symbols = word.split()
            for a, b in zip(symbols, symbols[1:]):
                pairs[(a, b)] += freq
        if not pairs:
            break
        best = max(pairs, key=pairs.get)
        merges.append(best)
        bigram, joined = " ".join(best), "".join(best)
        vocab = {w.replace(bigram, joined): c for w, c in vocab.items()}
    return merges


def tokenize(word, merges):
    symbols = list(word) + ["</w>"]
    for a, b in merges:
        i = 0
        while i < len(symbols) - 1:
            if symbols[i] == a and symbols[i + 1] == b:
                symbols[i:i + 2] = [a + b]
            else:
                i += 1
    return symbols


if __name__ == "__main__":
    corpus = ["low"] * 5 + ["lower"] * 2 + ["newest"] * 6 + ["widest"] * 3
    merges = train_bpe(corpus, num_merges=10)
    print("learned merges:", [a + b for a, b in merges])
    for w in ["newest", "lowest", "lower"]:
        print(f"{w!r} -> {tokenize(w, merges)}")
    # A word the merges cover becomes few tokens; a rare word stays in pieces.
    print("tokens for 'newest':", len(tokenize("newest", merges)),
          "| for 'lowest':", len(tokenize("lowest", merges)))

import math
import re
from collections import Counter

STOPWORDS = {"the", "a", "an", "i", "my", "to", "do", "how", "on", "of", "is", "it"}


def bag_of_words(text):
    words = [w for w in re.findall(r"[a-z]+", text.lower()) if w not in STOPWORDS]
    return Counter(words)


def cosine_counts(a, b):
    shared = set(a) & set(b)
    num = sum(a[w] * b[w] for w in shared)
    den = math.sqrt(sum(v * v for v in a.values())) * math.sqrt(sum(v * v for v in b.values()))
    return num / den if den else 0.0


PAIRS = [
    ("how do I reset my password", "I forgot my login credentials"),   # same intent, no shared content words
    ("the bank raised interest rates", "I sat on the river bank"),      # one shared word, different meaning
    ("cancel my subscription", "how to cancel a subscription"),         # genuinely similar and lexically close
]

if __name__ == "__main__":
    for a, b in PAIRS:
        print(f"{cosine_counts(bag_of_words(a), bag_of_words(b)):.2f}  {a!r}  vs  {b!r}")

import math

# Toy 4-dimensional "embeddings". Real ones have hundreds to thousands of learned
# dimensions, but the operations you perform on them are exactly these.
VECTORS = {
    "password reset":  [0.80, 0.10, 0.55, 0.20],
    "forgot my login": [0.78, 0.12, 0.58, 0.15],
    "change password": [0.82, 0.08, 0.50, 0.25],
    "cancel my order": [0.15, 0.85, 0.10, 0.40],
    "refund request":  [0.12, 0.88, 0.08, 0.42],
    "store opening hours": [0.20, 0.20, 0.10, 0.90],
}


def dot(a, b):
    return sum(x * y for x, y in zip(a, b))


def norm(a):
    return math.sqrt(dot(a, a))


def cosine(a, b):
    return dot(a, b) / (norm(a) * norm(b))


def nearest(query_vec, k=3):
    scored = [(name, cosine(query_vec, v)) for name, v in VECTORS.items()]
    return sorted(scored, key=lambda t: t[1], reverse=True)[:k]


def truncate(vec, dims):
    """Matryoshka-style: keep the first `dims`, then renormalise to unit length."""
    head = vec[:dims]
    n = norm(head)
    return [x / n for x in head]


if __name__ == "__main__":
    q = VECTORS["password reset"]
    print("nearest to 'password reset':")
    for name, score in nearest(q):
        print(f"  {score:.3f}  {name}")

    # Cosine ignores magnitude: doubling a vector's length doesn't change the angle.
    doubled = [2 * x for x in VECTORS["refund request"]]
    print("cosine(refund, 2x refund) =", round(cosine(VECTORS["refund request"], doubled), 6))

    # Truncating to 2 dims keeps the top neighbour, at a fraction of the storage.
    short = {name: truncate(v, 2) for name, v in VECTORS.items()}
    qs = short["password reset"]
    best = max((n for n in short if n != "password reset"),
              key=lambda n: cosine(qs, short[n]))
    print("top neighbour at 2 dims:", best)

import json
import re

# The schema your code relies on. Constrained decoding (below) guarantees the shape;
# this validator is the belt to that braces, and the only option when a provider or
# model can't constrain output.
INVOICE_SCHEMA = {
    "type": "object",
    "required": ["vendor", "total", "currency", "status"],
    "properties": {
        "vendor": {"type": "string"},
        "total": {"type": "number", "minimum": 0},
        "currency": {"type": "string", "enum": ["USD", "EUR", "GBP"]},
        "status": {"type": "string", "enum": ["paid", "unpaid", "void"]},
    },
}


def validate(value, schema, path="$"):
    """Return a list of human-readable errors; empty means valid. A tiny JSON-Schema subset."""
    errors = []
    t = schema.get("type")
    types = {"object": dict, "array": list, "string": str, "boolean": bool,
             "number": (int, float), "integer": int}
    if t and not isinstance(value, types[t]) or (t == "number" and isinstance(value, bool)):
        return [f"{path}: expected {t}, got {type(value).__name__}"]
    if t == "object":
        for key in schema.get("required", []):
            if key not in value:
                errors.append(f"{path}.{key}: required field missing")
        for key, sub in schema.get("properties", {}).items():
            if key in value:
                errors += validate(value[key], sub, f"{path}.{key}")
    elif t == "array":
        for i, item in enumerate(value):
            errors += validate(item, schema["items"], f"{path}[{i}]")
    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: {value!r} not in {schema['enum']}")
    if "minimum" in schema and isinstance(value, (int, float)) and value < schema["minimum"]:
        errors.append(f"{path}: {value} below minimum {schema['minimum']}")
    return errors


def extract_json(text):
    """Models wrap JSON in prose or ``` fences. Pull out the first balanced object."""
    text = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.M).strip()
    start = text.find("{")
    if start == -1:
        return None
    depth = 0
    for i in range(start, len(text)):
        depth += (text[i] == "{") - (text[i] == "}")
        if depth == 0:
            try:
                return json.loads(text[start:i + 1])
            except json.JSONDecodeError:
                return None
    return None


def parse_structured(model_output, schema):
    """Returns (value, errors). errors is empty on success."""
    value = extract_json(model_output)
    if value is None:
        return None, ["output was not parseable JSON"]
    return value, validate(value, schema)


def repair_prompt(errors):
    return "Your previous output had these problems:\n" + "\n".join(
        f"- {e}" for e in errors) + "\nReturn only corrected JSON matching the schema."


if __name__ == "__main__":
    outputs = {
        "clean":        '{"vendor": "Acme", "total": 1200, "currency": "USD", "status": "paid"}',
        "fenced+prose": 'Sure! Here is the data:\n```json\n{"vendor":"Globex","total":90,"currency":"EUR","status":"unpaid"}\n```',
        "bad enum":     '{"vendor": "Initech", "total": 50, "currency": "YEN", "status": "paid"}',
        "missing+type": '{"vendor": "Umbrella", "total": "lots", "currency": "GBP"}',
        "not json":     "I could not find an invoice in that document.",
    }
    for name, out in outputs.items():
        value, errors = parse_structured(out, INVOICE_SCHEMA)
        print(f"{name:14} -> {'OK' if not errors else errors}")
    print("\nrepair prompt for 'missing+type':")
    _, errs = parse_structured(outputs["missing+type"], INVOICE_SCHEMA)
    print(repair_prompt(errs))

import math
import re
from collections import Counter

# Four chunks. Two answer the query "E-4021 payment declined": c1 by its exact code,
# c2 by paraphrase. BM25 (lexical) will find c1 and miss the paraphrase; a semantic
# search will find c2 and rank the code-heavy c1 low. Each alone gets only one.
CHUNKS = {
    "c1": "Error E-4021 means the payment was declined by the issuing bank.",
    "c2": "Your charge was turned down; try a different card or contact your bank.",
    "c3": "A refund request may be declined if the order already shipped.",
    "c4": "Shipping is free on orders over 50 dollars.",
}
RELEVANT = {"c1", "c2"}


def bm25(query, chunks, k1=1.5, b=0.75):
    docs = {cid: re.findall(r"[a-z0-9-]+", t.lower()) for cid, t in chunks.items()}
    avglen = sum(len(d) for d in docs.values()) / len(docs)
    df = Counter(w for d in docs.values() for w in set(d))
    N = len(docs)
    scores = {}
    for cid, d in docs.items():
        tf, s = Counter(d), 0.0
        for w in re.findall(r"[a-z0-9-]+", query.lower()):
            if w in tf:
                idf = math.log(1 + (N - df[w] + 0.5) / (df[w] + 0.5))
                s += idf * tf[w] * (k1 + 1) / (tf[w] + k1 * (1 - b + b * len(d) / avglen))
        scores[cid] = s
    return [cid for cid, _ in sorted(scores.items(), key=lambda t: t[1], reverse=True)]


def rrf(rankings, k=60):
    fused = Counter()
    for ranking in rankings:
        for i, cid in enumerate(ranking):
            fused[cid] += 1 / (k + i + 1)
    return [cid for cid, _ in sorted(fused.items(), key=lambda t: t[1], reverse=True)]


def recall_at_k(ranking, relevant, k):
    return sum(1 for cid in ranking[:k] if cid in relevant) / len(relevant)


if __name__ == "__main__":
    query = "E-4021 payment declined"
    bm = bm25(query, CHUNKS)
    # The embedding model's ranking, shown as a fixed result the way a test mocks a model:
    # it nails the paraphrase c2 but ranks the code-heavy c1 third.
    dense = ["c2", "c3", "c1", "c4"]
    hybrid = rrf([bm, dense])
    print("BM25  :", bm,    f"recall@2 = {recall_at_k(bm, RELEVANT, 2):.2f}")
    print("Dense :", dense, f"recall@2 = {recall_at_k(dense, RELEVANT, 2):.2f}")
    print("Hybrid:", hybrid, f"recall@2 = {recall_at_k(hybrid, RELEVANT, 2):.2f}")

import math


def recall_at_k(retrieved, relevant, k):
    hits = sum(1 for cid in retrieved[:k] if cid in relevant)
    return hits / len(relevant)


def precision_at_k(retrieved, relevant, k):
    return sum(1 for cid in retrieved[:k] if cid in relevant) / k


def mrr(retrieved, relevant):
    for i, cid in enumerate(retrieved, 1):
        if cid in relevant:
            return 1 / i
    return 0.0


def ndcg_at_k(retrieved, relevant, k):
    dcg = sum((1 if cid in relevant else 0) / math.log2(i + 1)
              for i, cid in enumerate(retrieved[:k], 1))
    ideal = sum(1 / math.log2(i + 1) for i in range(1, min(len(relevant), k) + 1))
    return dcg / ideal if ideal else 0.0


if __name__ == "__main__":
    # One query's ranked results, and the set of chunks that truly answer it.
    retrieved = ["c3", "c7", "c1", "c9", "c2"]
    relevant = {"c1", "c2", "c3"}
    print(f"recall@5    = {recall_at_k(retrieved, relevant, 5):.2f}")
    print(f"precision@5 = {precision_at_k(retrieved, relevant, 5):.2f}")
    print(f"MRR         = {mrr(retrieved, relevant):.2f}")
    print(f"nDCG@5      = {ndcg_at_k(retrieved, relevant, 5):.3f}")
    # Reranking that lifts the relevant chunks to the top improves nDCG without changing recall.
    reranked = ["c3", "c1", "c2", "c7", "c9"]
    print(f"nDCG@5 after rerank = {ndcg_at_k(reranked, relevant, 5):.3f}"
          f"  (recall@5 unchanged = {recall_at_k(reranked, relevant, 5):.2f})")

from dataclasses import dataclass

# A tool is a plain function plus a schema the model is shown. The schema both tells the
# model how to call it and lets you validate the call before you run anything (chapter 4).
ORDERS = {"1042": {"total": 120.0, "status": "shipped", "days_since": 3}}


def get_order(order_id: str):
    order = ORDERS.get(order_id)
    return order if order else {"error": "no such order"}


def refund_quote(total: float, days_since: int):
    # Business rule lives in code, not in the model's head: full refund within 30 days.
    return {"refund": total if days_since <= 30 else 0.0}


TOOLS = {
    "get_order": {"fn": get_order, "args": {"order_id": str}},
    "refund_quote": {"fn": refund_quote, "args": {"total": float, "days_since": int}},
}


def dispatch(call):
    """Validate a tool call against its schema, then run it. Errors come back as data."""
    name, args = call["tool"], call["args"]
    spec = TOOLS.get(name)
    if spec is None:
        return {"error": f"unknown tool {name!r}"}
    missing = [k for k in spec["args"] if k not in args]
    if missing:
        return {"error": f"missing args {missing}"}
    for k, typ in spec["args"].items():
        if not isinstance(args[k], typ) or (typ is not bool and isinstance(args[k], bool)):
            return {"error": f"arg {k} must be {typ.__name__}"}
    return spec["fn"](**args)


def run(model, user_goal, max_steps=6):
    """The agent loop: the model proposes an action, we execute it, repeat until it answers."""
    transcript = [("user", user_goal)]
    for step in range(max_steps):
        action = model(transcript)
        if action["type"] == "final":
            return action["text"], transcript
        result = dispatch(action)
        transcript.append(("tool", {"call": action, "result": result}))
    return "stopped: step budget exhausted", transcript


# A scripted stand-in for the model, so the loop is deterministic and testable. A real model
# would decide these steps itself; here we fix them the way a test mocks an API.
def scripted_model(transcript):
    steps = [t for t in transcript if t[0] == "tool"]
    if not steps:
        return {"type": "tool", "tool": "get_order", "args": {"order_id": "1042"}}
    if len(steps) == 1:
        order = steps[0][1]["result"]
        return {"type": "tool", "tool": "refund_quote",
                "args": {"total": order["total"], "days_since": order["days_since"]}}
    refund = steps[1][1]["result"]["refund"]
    return {"type": "final", "text": f"You're eligible for a ${refund:.2f} refund."}


if __name__ == "__main__":
    answer, transcript = run(scripted_model, "Can I get a refund on order 1042?")
    for who, what in transcript:
        print(f"{who:5}: {what}")
    print("ANSWER:", answer)
    # The dispatcher rejects bad calls without running anything:
    print("\nguards:",
          dispatch({"tool": "drop_table", "args": {}}),
          dispatch({"tool": "get_order", "args": {}}),
          dispatch({"tool": "refund_quote", "args": {"total": "lots", "days_since": 3}}))

def end_to_end(step_reliability, steps):
    """If each step must succeed and succeeds independently with prob p, the whole chain
    succeeds with p**steps. Small per-step error compounds fast over a long agent run."""
    return step_reliability ** steps


def pass_at_k(p, k):
    """At least one of k independent attempts succeeds. Flatters a system: good for 'can it ever?'"""
    return 1 - (1 - p) ** k


def pass_hat_k(p, k):
    """ALL k attempts succeed (tau-bench's pass^k): the honest measure of reliability."""
    return p ** k


if __name__ == "__main__":
    print("end-to-end success by chain length:")
    print(f"{'per-step':>8} " + "".join(f"{n:>8}" for n in (1, 5, 10, 20)))
    for p in (0.99, 0.95, 0.90):
        row = "".join(f"{end_to_end(p, n) * 100:>7.0f}%" for n in (1, 5, 10, 20))
        print(f"{p * 100:>7.0f}% {row}")

    print("\nwhy 'it worked once' misleads, at 80% per-attempt success:")
    for k in (1, 3, 5):
        print(f"  k={k}: pass@k (ever) = {pass_at_k(0.80, k) * 100:4.0f}%"
              f"   pass^k (every time) = {pass_hat_k(0.80, k) * 100:4.0f}%")

# Many "agents" are really a router plus one focused call: no loop, no autonomy, far more reliable.
def classify(request, model):
    """model() returns a category label (schema-constrained, chapter 4). Mocked here."""
    return model(request)


def handle_billing(request):   return f"[billing] looked up invoice for: {request}"
def handle_bug(request):       return f"[bug] filed a ticket for: {request}"
def handle_question(request):  return f"[question] answered from the docs: {request}"
def handle_other(request):     return "[other] escalated to a human"

HANDLERS = {"billing": handle_billing, "bug": handle_bug,
            "question": handle_question, "other": handle_other}


def route(request, model):
    category = classify(request, model)
    return HANDLERS.get(category, handle_other)(request)


if __name__ == "__main__":
    # A fixed classifier output stands in for the model's decision.
    labels = {"I was charged twice": "billing",
              "the app crashes on login": "bug",
              "do you ship to Canada": "question",
              "I want to discuss a partnership": "partnerships"}  # unknown -> safe default
    for text, label in labels.items():
        print(route(text, model=lambda r, lbl=label: lbl))

from dataclasses import dataclass, field


@dataclass
class Span:
    name: str
    ms: float
    tokens: int = 0
    cost: float = 0.0
    note: str = ""
    children: list = field(default_factory=list)


def totals(span):
    t = {"ms": span.ms, "tokens": span.tokens, "cost": span.cost}
    for c in span.children:
        ct = totals(c)
        for k in t:
            t[k] += ct[k]
    return t


def show(span, depth=0):
    print(f"{'  ' * depth}{span.name:22} {span.ms:6.0f}ms  {span.tokens:5} tok  ${span.cost:.4f}"
          + (f"  {span.note}" if span.note else ""))
    for c in span.children:
        show(c, depth + 1)


if __name__ == "__main__":
    # One request's trace: the step-by-step record you need to debug a run you can't reproduce.
    trace = Span("request", 0, note="q: refund for order 1042", children=[
        Span("retrieve", 40, tokens=0, children=[
            Span("embed query", 15),
            Span("vector search", 20, note="top-5, best 0.88"),
            Span("rerank", 5),
        ]),
        Span("generate", 1300, tokens=2300, cost=0.0126, note="model=big, temp=0"),
        Span("guardrail: output", 8, note="passed"),
    ])
    show(trace)
    t = totals(trace)
    print(f"\nTOTAL  {t['ms']:.0f}ms  {t['tokens']} tokens  ${t['cost']:.4f}")
    print("generate dominates latency and cost, as usual")

from dataclasses import dataclass


@dataclass
class Task:
    base_model_passes_eval: bool   # does prompting alone already pass your eval?
    needs_fresh_or_private_knowledge: bool
    needs_citations: bool
    needs_specific_form: bool      # a fixed style, schema or refusal behaviour prompting can't hold
    labeled_examples: int          # in-distribution examples you have
    high_volume_cost_sensitive: bool


def recommend(task):
    """The 2026 ladder: prompt -> RAG -> fine-tune -> distill. Climb only as far as you must."""
    steps = ["prompt"]                                  # always start here
    if task.needs_fresh_or_private_knowledge or task.needs_citations:
        steps.append("RAG")                             # knowledge problems are retrieval problems
    if task.needs_specific_form and task.labeled_examples >= 500:
        steps.append("fine-tune")                       # form/behaviour, not facts; needs data + eval
    if task.high_volume_cost_sensitive and (task.base_model_passes_eval or "fine-tune" in steps):
        steps.append("distill")                         # cost/latency: frontier labels -> small model
    # If prompting already passes and nothing else is needed, don't add complexity.
    if task.base_model_passes_eval and len(steps) == 1:
        return ["prompt (already passes; stop here)"]
    return steps


if __name__ == "__main__":
    cases = {
        "Q&A over changing docs, cited": Task(False, True, True, False, 0, False),
        "strict house style, lots of data": Task(False, False, False, True, 2000, False),
        "high-volume classification": Task(True, False, False, False, 50000, True),
        "simple task, base model fine": Task(True, False, False, False, 0, False),
    }
    for name, t in cases.items():
        print(f"{name:34} -> {' + '.join(recommend(t))}")

import random


def solve(A, b):
    """Gaussian elimination with partial pivoting: solve A x = b (small systems)."""
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        M[col], M[piv] = M[piv], M[col]
        for r in range(n):
            if r != col and M[col][col]:
                f = M[r][col] / M[col][col]
                M[r] = [a - f * b for a, b in zip(M[r], M[col])]
    return [M[i][n] / M[i][i] for i in range(n)]


def polyfit(xs, ys, degree):
    """Least-squares polynomial fit via the normal equations."""
    powers = [[x ** d for d in range(degree + 1)] for x in xs]
    A = [[sum(p[i] * p[j] for p in powers) for j in range(degree + 1)] for i in range(degree + 1)]
    b = [sum(p[i] * y for p, y in zip(powers, ys)) for i in range(degree + 1)]
    return solve(A, b)


def predict(coeffs, x):
    return sum(c * x ** d for d, c in enumerate(coeffs))


def mse(coeffs, xs, ys):
    return sum((predict(coeffs, x) - y) ** 2 for x, y in zip(xs, ys)) / len(xs)


if __name__ == "__main__":
    rng = random.Random(0)
    true = lambda x: 2 * x + 1                       # the real relationship is a gentle line
    data = [(x, true(x) + rng.gauss(0, 1.5)) for x in [i * 0.5 for i in range(-8, 9)]]
    rng.shuffle(data)
    split = int(len(data) * 0.7)
    train, test = data[:split], data[split:]         # fit on train, judge on unseen test
    tx, ty = zip(*train); ex, ey = zip(*test)

    baseline = sum(ty) / len(ty)                     # "predict the mean": the bar to beat
    base_test = sum((baseline - y) ** 2 for y in ey) / len(ey)
    print(f"baseline (predict mean): test MSE {base_test:5.2f}")
    print(f"{'degree':>6} {'train MSE':>10} {'test MSE':>10}")
    for d in (1, 3, 9):
        c = polyfit(tx, ty, d)
        print(f"{d:>6} {mse(c, tx, ty):>10.2f} {mse(c, ex, ey):>10.2f}")
    print("\ndegree 9 fits the training noise (lowest train error) but generalises worst:"
          " that's overfitting.")

# The spec, written as tests, is what you actually own when an agent writes the code.
# Each case is (quantity, unit_price, expected_total_cents). The edge cases encode the
# real requirements: no negative quantities, prices in integer cents, a per-order cap.
SPEC = [
    ((1, 100), 100),
    ((3, 100), 300),
    ((0, 100), 0),
    ((2, 1999), 3998),          # money stays in integer cents: no float drift
    ((100000, 100), 1000000),   # capped at $10,000 (1,000,000 cents) per order
]
REJECTS = [(-1, 100), (1, -100)]   # invalid inputs must raise, not silently compute


def run_spec(order_total):
    passed = 0
    for (qty, price), expected in SPEC:
        try:
            ok = order_total(qty, price) == expected
        except Exception:
            ok = False
        passed += ok
    for qty, price in REJECTS:
        try:
            order_total(qty, price)
            rejected = False            # it should have raised
        except ValueError:
            rejected = True
        except Exception:
            rejected = False
        passed += rejected
    return passed, len(SPEC) + len(REJECTS)


# Candidate A: the plausible version an agent writes from the happy-path description.
def order_total_a(qty, price):
    return qty * price

# Candidate B: the version that actually meets the spec's edge cases.
def order_total_b(qty, price):
    if qty < 0 or price < 0:
        raise ValueError("quantity and price must be non-negative")
    return min(qty * price, 1_000_000)


if __name__ == "__main__":
    for name, fn in [("agent's first draft", order_total_a), ("meets the spec", order_total_b)]:
        passed, total = run_spec(fn)
        print(f"{name:20} {passed}/{total} spec cases pass")
    print("\nThe draft looks right and passes the happy path, but the spec's edge cases"
          "\n(the cap, the rejects) are what catch what review by eye would miss.")
